def is_low_value_title(title: str) -> bool:
    title = clean_text(title)
    if not title:
        return True
    if title in LOW_VALUE_TITLE_TOKENS:
        return True
    return any(
        token in title
        for token in (
            "\uc2a4\ud0b5\ub124\ube44\uac8c\uc774\uc158", "\uc804\uccb4\uba54\ub274", "\ud558\uc704\uba54\ub274 \uc704\uce58\uae30",
            "\ucc44\uc6a9 \uacf5\uace0", "\uae30\uac04\ubcc4", "\uc778\ub825\ud480", "\ubcf4\ub3c4\uc790\ub8cc",
        )
    )


def fetch_soup(s: requests.Session, url: str, timeout: int = 20) -> BeautifulSoup:
    try:
        response = s.get(url, timeout=timeout)
    except RequestException:
        try:
            response = s.get(url, timeout=max(timeout, 25), verify=False)
        except RequestException:
            completed = subprocess.run(
                [
                    "curl",
                    "-L",
                    "-k",
                    "--max-time",
                    str(timeout),
                    "-A",
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/125.0 Safari/537.36",
                    "-H",
                    "Accept-Language: ko-KR,ko;q=0.9,en;q=0.8",
                    url,
                ],
                check=True,
                capture_output=True,
            )
            return BeautifulSoup(completed.stdout, "lxml")
    response.raise_for_status()
    if not response.encoding or response.encoding.lower() == "iso-8859-1":
        response.encoding = response.apparent_encoding
    return BeautifulSoup(response.text, "lxml")


def html_to_text(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    return clean_text(BeautifulSoup(text, "lxml").get_text(" ", strip=True))


def lines_from_soup(node: Any) -> list[str]:
    if not hasattr(node, "get_text"):
        return []
    return [
        clean_text(line).replace("\xa0", " ")
        for line in node.get_text("\n", strip=True).splitlines()
        if clean_text(line)
    ]


def extract_korean_labeled_value(text: str, label: str, stop_labels: tuple[str, ...]) -> str:
    separator = r"\s*(?::|：|\s)\s*"
    stop_pattern = "|".join(re.escape(stop) + separator for stop in stop_labels if stop != label)
    pattern = re.escape(label) + separator + r"(.*?)(?=" + stop_pattern + r"|$)"
    match = re.search(pattern, text, re.DOTALL)
    return clean_text(match.group(1)) if match else ""


def format_yyyymmdd(value: Any) -> str:
    text = clean_text(value)
    if re.fullmatch(r"\d{8}", text):
        return f"{text[:4]}-{text[4:6]}-{text[6:8]}"
    return text


def format_hhmm(value: Any) -> str:
    text = clean_text(value)
    if re.fullmatch(r"\d{4}", text):
        return f"{text[:2]}:{text[2:]}"
    return text


def normalize_short_korean_date(value: str) -> str:
    text = clean_text(value)
    match = re.fullmatch(r"(\d{2})[.](\d{2})[.](\d{2})", text)
    if match:
        return f"20{match.group(1)}-{match.group(2)}-{match.group(3)}"
    match = re.fullmatch(r"(\d{4})[./](\d{1,2})[./](\d{1,2})", text)
    if match:
        return f"{match.group(1)}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"
    return text


def labeled_lines_to_pairs(lines: list[str]) -> dict[str, str]:
    pairs: dict[str, str] = {}
    index = 0
    while index < len(lines):
        line = clean_text(lines[index])
        if line.endswith(":") and index + 1 < len(lines):
            key = line.rstrip(":").strip()
            values: list[str] = []
            index += 1
            while index < len(lines) and not clean_text(lines[index]).endswith(":"):
                values.append(clean_text(lines[index]))
                index += 1
            pairs[key] = clean_text(" ".join(values))
            continue
        index += 1
    return pairs


def sequence_lines_to_pairs(lines: list[str], labels: set[str]) -> dict[str, str]:
    pairs: dict[str, str] = {}
    index = 0
    while index < len(lines):
        label = clean_text(lines[index]).rstrip(":").strip()
        if label not in labels:
            index += 1
            continue
        values: list[str] = []
        index += 1
        while index < len(lines):
            candidate = clean_text(lines[index])
            next_label = candidate.rstrip(":").strip()
            if next_label in labels:
                break
            if candidate and candidate not in {":", "|"}:
                values.append(candidate.lstrip(":").strip())
            index += 1
        pairs[label] = clean_text(" ".join(value for value in values if value))
    return pairs


def pairs_from_lines(lines: list[str]) -> dict[str, str]:
    cleaned = [clean_text(line) for line in lines if clean_text(line)]
    pairs = labeled_lines_to_pairs(cleaned)
    pairs.update(sequence_lines_to_pairs(cleaned, GENERIC_LABELS))
    return pairs


def pairs_from_definition_lists(node: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not hasattr(node, "select"):
        return pairs
    for dl in node.select("dl"):
        pending_key = ""
        for child in dl.find_all(["dt", "dd"], recursive=False):
            text = clean_text(child.get_text(" ", strip=True))
            if not text:
                continue
            if child.name == "dt":
                pending_key = text.rstrip(":：").strip()
            elif pending_key:
                pairs[pending_key] = text
                pending_key = ""
    return pairs


def pairs_from_tables(node: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not hasattr(node, "select"):
        return pairs
    for tr in node.select("tr"):
        cells = tr.find_all(["th", "td"], recursive=False)
        if len(cells) < 2:
            cells = tr.find_all(["th", "td"])
        index = 0
        while index < len(cells) - 1:
            key_cell = cells[index]
            value_cell = cells[index + 1]
            key = clean_text(key_cell.get_text(" ", strip=True)).rstrip(":：").strip()
            value = clean_text(value_cell.get_text(" ", strip=True))
            if key and value and (key_cell.name == "th" or key in GENERIC_LABELS or len(cells) <= 4):
                pairs[key] = value
                index += 2
                continue
            index += 1
    return pairs


def normalize_month_day_range(value: str) -> str:
    text = clean_text(value)
    matches = re.findall(r"(\d{1,2})[.](\d{1,2})", text)
    if len(matches) >= 2:
        year = datetime.now().year
        first = f"{year}-{int(matches[0][0]):02d}-{int(matches[0][1]):02d}"
        second = f"{year}-{int(matches[1][0]):02d}-{int(matches[1][1]):02d}"
        return f"{first} ~ {second}"
    return text


def normalize_korean_month_day_range(value: str) -> str:
    text = clean_text(value)
    matches = re.findall(r"(\d{1,2})\s*\uC6D4\s*(\d{1,2})\s*\uC77C", text)
    if len(matches) >= 2:
        year = datetime.now().year
        first = f"{year}-{int(matches[0][0]):02d}-{int(matches[0][1]):02d}"
        second = f"{year}-{int(matches[1][0]):02d}-{int(matches[1][1]):02d}"
        return f"{first} ~ {second}"
    return text


def normalize_yymmdd_range(value: str) -> str:
    text = clean_text(value)
    matches = re.findall(r"(\d{2})[.](\d{1,2})[.](\d{1,2})", text)
    if len(matches) >= 2:
        first = f"20{matches[0][0]}-{int(matches[0][1]):02d}-{int(matches[0][2]):02d}"
        second = f"20{matches[1][0]}-{int(matches[1][1]):02d}-{int(matches[1][2]):02d}"
        return f"{first} ~ {second}"
    matches4 = re.findall(r"(\d{4})[.](\d{1,2})[.](\d{1,2})", text)
    if len(matches4) >= 2:
        first = f"{matches4[0][0]}-{int(matches4[0][1]):02d}-{int(matches4[0][2]):02d}"
        second = f"{matches4[1][0]}-{int(matches4[1][1]):02d}-{int(matches4[1][2]):02d}"
        return f"{first} ~ {second}"
    return text


def normalize_mixed_date_range(value: str) -> str:
    text = clean_text(value)
    match = re.search(
        r"(\d{4})[.-](\d{1,2})[.-](\d{1,2})\s*~\s*(?:(\d{4})[.-])?(\d{1,2})[.-](\d{1,2})",
        text,
    )
    if match:
        year = match.group(1)
        end_year = match.group(4) or year
        return (
            f"{year}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"
            f" ~ {end_year}-{int(match.group(5)):02d}-{int(match.group(6)):02d}"
        )
    return normalize_yymmdd_range(text)


def normalize_korean_label(value: str) -> str:
    return clean_text(value).replace(" ", "").rstrip(":：")


def onclick_location_url(base_url: str, node: Any) -> str:
    candidates = [node]
    if hasattr(node, "select"):
        candidates.extend(list(node.select("[onclick]")))
    for candidate in candidates:
        onclick = clean_text(candidate.get("onclick") if hasattr(candidate, "get") else "")
        match = re.search(r"location\.href\s*=\s*['\"]([^'\"]+)['\"]", onclick)
        if match:
            return normalize_link(base_url, match.group(1))
    return ""


def labeled_pairs_from_named_spans(node: Any, selector: str = "span.name") -> dict[str, str]:
    pairs: dict[str, str] = {}
    for label_node in node.select(selector):
        label = normalize_korean_label(label_node.get_text(" ", strip=True))
        parent = label_node.parent
        if not label or parent is None:
            continue
        parent_text = clean_text(parent.get_text(" ", strip=True))
        label_text = clean_text(label_node.get_text(" ", strip=True))
        value = clean_text(parent_text.replace(label_text, "", 1))
        pairs[label] = value
    return pairs


def split_period_and_schedule(value: str) -> tuple[str, str]:
    text = clean_text(value)
    match = re.search(
        r"(\d{4}[.-]\d{1,2}[.-]\d{1,2})\s*~\s*(\d{4}[.-]\d{1,2}[.-]\d{1,2})(.*)",
        text,
    )
    if not match:
        single = re.search(r"(\d{4}[.-]\d{1,2}[.-]\d{1,2})(.*)", text)
        if single:
            day = normalize_short_korean_date(single.group(1).replace("-", "."))
            return f"{day} ~ {day}", clean_text(single.group(2))
        return text, ""
    start = normalize_short_korean_date(match.group(1).replace("-", "."))
    end = normalize_short_korean_date(match.group(2).replace("-", "."))
    return f"{start} ~ {end}", clean_text(match.group(3))


def status_from_lines(lines: list[str]) -> str:
    exact_statuses = {
        "\uc811\uc218\uc911", "\uc811\uc218\ub9c8\uac10", "\ub9c8\uac10", "\ub300\uae30", "\uc2e0\uccad\ub300\uae30",
        "\ub300\uae30\uc790\uc2e0\uccad", "\uc218\uac15\uc2e0\uccad", "\uc815\uc6d0\ub9c8\uac10", "\uc2b9\uc778", "\uc885\ub8cc",
    }
    for line in reversed(lines):
        text = clean_text(line)
        if text in exact_statuses:
            return text
    for line in lines:
        text = clean_text(line)
        if text in exact_statuses:
            return text
    return ""


def course_title_from_status_lines(lines: list[str], status: str) -> str:
    skip = {
        "", "\uac15\uc758\uacc4\ud68d\uc11c", "\ubb34\ub8cc", "\uc720\ub8cc", "\uc778\ud130\ub137", "\ubc29\ubb38", "\uc804\ud654",
        "\uc0c1\uc138\ubcf4\uae30", "\uc0c1\uc138\ub2eb\uae30", "\uac15\uc88c \uc0c1\uc138\uc815\ubcf4 \ubcf4\uae30",
    }
    start_index = 0
    if status in lines:
        start_index = lines.index(status) + 1
    for line in lines[start_index:]:
        text = clean_text(line)
        if text in skip or text.rstrip(":").strip() in skip:
            continue
        if text.endswith(":"):
            continue
        if status_has_course_state(text):
            continue
        return text
    return ""


def collect_gbe_eq_list(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        if page > 1:
            query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            cells = tr.find_all("td")
            if len(cells) < 5:
                continue
            lines = [clean_text(line) for line in cells[0].get_text("\n", strip=True).splitlines() if clean_text(line)]
            if not lines:
                continue
            title = lines[0]
            if not title or is_low_value_title(title):
                continue
            joined = clean_text(" ".join(lines[1:]))
            apply_period = ""
            period = ""
            schedule = ""
            apply_match = re.search(r"접수기간\s*:?\s*([0-9./:\s~]+?)(?=강좌기간|$)", joined)
            if apply_match:
                apply_period = clean_text(apply_match.group(1))
            period_match = re.search(r"강좌기간\s*:?\s*([0-9./\s~]+)(?:\(([^)]*)\))?", joined)
            if period_match:
                period = clean_text(period_match.group(1))
                schedule = clean_text(period_match.group(2))
            capacity = clean_text(cells[1].get_text(" ", strip=True))
            method = clean_text(cells[2].get_text(" ", strip=True))
            status = clean_text(cells[4].get_text(" ", strip=True))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, current_url, title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "category": "",
                    "raw_url": current_url,
                    "application_url": current_url,
                    "status": status,
                    "fee": "",
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule,
                    "target": "",
                    "capacity": capacity,
                    "application_method_raw": method,
                    "description": title,
                    "raw_fields": {"lines": lines, "capacity": capacity, "method": method, "parser": "gbe_eq_table"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "gbe_eq_table", meta


def collect_changwon_booking(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["cpage"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for item in soup.select(".cp31edu1list1 > ul > li"):
            lines = [clean_text(line) for line in item.get_text("\n", strip=True).splitlines() if clean_text(line)]
            if len(lines) < 8:
                continue
            status = status_from_lines(lines) or lines[0]
            fee_hint = next((line for line in lines[:5] if line in {"\uBB34\uB8CC", "\uC720\uB8CC"} or re.search(r"\d[\d,]*\s*\uC6D0", line)), "")
            title = course_title_from_status_lines(lines, status)
            if not title or is_low_value_title(title):
                continue
            pairs = labeled_lines_to_pairs(lines)
            link = item.find("a", href=True)
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            fee = clean_text(pairs.get("\uC218\uAC15\uB8CC")) or fee_hint
            room = clean_text(pairs.get("\uAD50\uC721\uC7A5\uC18C"))
            capacity = clean_text(pairs.get("\uC815\uC6D0/\uB300\uAE30\uC815\uC6D0") or pairs.get("\uC815\uC6D0/\uC811\uC218\uC778\uC6D0/\uB300\uAE30\uC790\uC815\uC6D0"))
            target_text = clean_text(pairs.get("\uC2E0\uCCAD\uB300\uC0C1\uC790") or pairs.get("\uC2E0\uCCAD\uB300\uC0C1"))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "category": clean_text(pairs.get("\uAD50\uC721\uACFC\uC815")),
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": fee,
                    "period": clean_text(pairs.get("\uAD50\uC721\uAE30\uAC04")),
                    "apply_period": clean_text(pairs.get("\uC811\uC218\uC77C\uC2DC")),
                    "schedule_raw": clean_text(
                        pairs.get("\uAD50\uC721\uC77C\uC2DC")
                        or pairs.get("\uC694\uC77C/\uC2DC\uAC04")
                        or pairs.get("\uAD50\uC721\uC2DC\uAC04")
                    ),
                    "target": target_text,
                    "room": room,
                    "venue_name": room,
                    "capacity": capacity,
                    "capacity_current": clean_text(pairs.get("\uC2E0\uCCAD\uD604\uD669")),
                    "instructor": clean_text(pairs.get("\uAC15\uC0AC\uBA85")),
                    "description": clean_text(item.get_text(" ", strip=True)),
                    "raw_fields": {"pairs": pairs, "lines": lines, "parser": "changwon_booking_list"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='cpage=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "changwon_booking_list", meta


