def jinju_branch_name_for_all_course_link(link: Any) -> str:
    current = link
    while current is not None:
        parent_li = current.find_parent("li") if hasattr(current, "find_parent") else None
        if parent_li is None:
            break
        direct_link = parent_li.find("a", recursive=False)
        if direct_link is not None and direct_link is not link:
            text = clean_text(direct_link.get_text(" ", strip=True))
            if text and text != "\uc804\uccb4\uac15\uc88c" and "\uc7a5\ub09c\uac10\uc740\ud589" in text and "\ub300\uccb4\uc218\uac15" not in text:
                return text
        current = parent_li
    return ""


HAMAN_WELFARE_AGENCIES = ("AGENCY001", "AGENCY024", "AGENCY003", "AGENCY005", "AGENCY006")


def url_with_query(base_url: str, updates: dict[str, Any]) -> str:
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    for key, value in updates.items():
        if value is None or value == "":
            query.pop(key, None)
        else:
            query[key] = [str(value)]
    return parsed._replace(query=urlencode(query, doseq=True)).geturl()


def lines_from_node(node: Any) -> list[str]:
    if not hasattr(node, "get_text"):
        return []
    return [clean_text(line) for line in node.get_text("\n", strip=True).splitlines() if clean_text(line)]


def first_matching_line(lines: list[str], candidates: set[str]) -> str:
    for line in lines:
        text = clean_text(line)
        if text in candidates:
            return text
    return ""


def first_title_candidate(soup: BeautifulSoup) -> str:
    for selector in ("h1", "h2", "h3", "h4", ".title", ".tit", "caption", "title"):
        for node in soup.select(selector)[:20]:
            text = clean_text(node.get_text(" ", strip=True) if node else "")
            if text and not is_low_value_title(text):
                return text
    for line in lines_from_node(soup)[:180]:
        text = clean_text(line)
        if not text or len(text) > 100 or is_low_value_title(text):
            continue
        if re.match(r"^\[[^\]]{2,30}\]\s*.{2,}", text):
            return text
    return ""


def leading_bracket_label(value: Any) -> str:
    text = clean_text(value)
    match = re.match(r"^[\[\(【]\s*([^\]\)】]{2,40})\s*[\]\)】]", text)
    return clean_text(match.group(1)) if match else ""


def is_generic_venue_name(value: Any) -> bool:
    text = clean_text(value)
    if not text:
        return True
    if len(text) <= 1:
        return True
    generic_values = {
        "-",
        "없음",
        "미정",
        "온라인",
        "비대면",
        "강의실",
        "교육장",
        "교육장소",
        "장소",
        "해당없음",
    }
    if text in generic_values:
        return True
    if re.fullmatch(r"(?:\d+층|[A-Za-z]?\d{1,4}호|제?\d+강의실)", text):
        return True
    if re.search(r"(?:강의실|회의실|교육실|교실)$", text) and not re.search(
        r"(?:학습관|센터|주민센터|도서관|복지관|체육관|문화관|청소년|미술관|박물관)", text
    ):
        return True
    return False


PROMOTABLE_VENUE_KEYS = extend_unique(
    ROOM_KEYS,
    (
        "\uc7a5\uc18c\uba85",
        "\uc7a5\uc18c/\uc704\uce58",
        "\uc7a5\uc18c \ubc0f \uc704\uce58",
        "\ud589\uc0ac\uc7a5",
        "\ud589\uc0ac\uc7a5\uc18c",
        "\uad50\uc721\uc7a5",
        "\uad50\uc721\uc7a5\uc18c",
        "\uac15\uc758\uc7a5\uc18c",
    ),
)

VENUE_HINT_RE = re.compile(
    r"(?:"
    r"\uc13c\ud130|\ub3c4\uc11c\uad00|\ubcf5\uc9c0\uad00|\uccb4\uc721\uad00|\ubb38\ud654\uad00|"
    r"\uc544\ud2b8\uc13c\ud130|\ubc15\ubb3c\uad00|\ubbf8\uc220\uad00|\uae30\ub150\uad00|"
    r"\ubb38\ud654\uc6d0|\ubb38\ud654\ud68c\uad00|\uacf5\uc5f0\uc7a5|\uadf9\uc7a5|\uc18c\uadf9\uc7a5|"
    r"\uac24\ub7ec\ub9ac|\ubba4\uc9c0\uc5c4|\uc2a4\ud14c\uc774\uc158|\uc544\ud2b8\ud640|\ud640|"
    r"\ub300\ud559\uad50|\ub300\ud559|\ud559\uad50|\ucea0\ud37c\uc2a4|\ud559\uc2b5\uad00|\uad50\uc721\uad00|"
    r"\uac15\uc758\uc2e4|\uc2e4\uc2b5\uc2e4|\uacfc\ud559\uad00|\uccb4\ud5d8\uad00|\uc804\uc2dc\uad00|"
    r"\uc218\ub828\uad00|\uc8fc\ubbfc\uc13c\ud130|\ud589\uc815\ubcf5\uc9c0\uc13c\ud130|"
    r"\ud3c9\uc0dd\ud559\uc2b5\uad00|\uc218\ubaa9\uc6d0|\uacf5\uc6d0|\uc804\ub2f9|\ub300\uac15\ub2f9|\uac15\ub2f9"
    r")"
)


def is_region_only_name(value: Any) -> bool:
    text = clean_text(value)
    if not text:
        return True
    if VENUE_HINT_RE.search(text):
        return False
    region_unit = (
        r"(?:\ud2b9\ubcc4\uc2dc|\uad11\uc5ed\uc2dc|\ud2b9\ubcc4\uc790\uce58\uc2dc|"
        r"\ud2b9\ubcc4\uc790\uce58\ub3c4|\ub3c4|\uc2dc|\uad70|\uad6c|\uc74d|\uba74|\ub3d9|\ub9ac)"
    )
    return bool(re.fullmatch(rf"(?:[\uac00-\ud7a3]{{1,14}}{region_unit}\s*){{1,6}}", text))


def normalize_venue_candidate(value: Any, *, require_hint: bool = False) -> str:
    text = clean_text(value)
    if not text or is_generic_venue_name(text) or is_region_only_name(text):
        return ""
    if len(text) > 80:
        return ""
    venue_hints = VENUE_HINT_RE.findall(text)
    if len(text) > 45 and len(set(venue_hints)) >= 4:
        return ""
    if re.match(
        r"^(?:\ub300\uc0c1|\uad50\uc721\ub300\uc0c1|\uc218\uac15\ub300\uc0c1|\ucc38\uc5ec\ub300\uc0c1|"
        r"\uc774\uc6a9\ub300\uc0c1|\uc2e0\uccad\ub300\uc0c1|\uc778\uc6d0|\uc815\uc6d0|\ubaa8\uc9d1\uc778\uc6d0)\b",
        text,
    ):
        return ""
    if re.match(r"^(?:\uae30\uac04|\uc2dc\uac04|\uc77c\uc2dc|\uc77c\uc815)\b", text):
        return ""
    if re.search(
        r"(?:^|\s)(?:\ub300\uc0c1|\uad50\uc721\ub300\uc0c1|\uc218\uac15\ub300\uc0c1|\ucc38\uc5ec\ub300\uc0c1|"
        r"\uc774\uc6a9\ub300\uc0c1|\uc2e0\uccad\ub300\uc0c1|\uc778\uc6d0|\uc815\uc6d0|\ubaa8\uc9d1\uc778\uc6d0)(?:\s|$)",
        text,
    ):
        return ""
    text = re.sub(r"\s+(?:\uc870\ud68c\uc218|\uc870\ud68c|views?)?\s*\d{1,7}$", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s+(?:\uc0c1\uc138\ubcf4\uae30|\uc790\uc138\ud788\ubcf4\uae30|\ub354\ubcf4\uae30)$", "", text)
    text = clean_text(text.strip(" -~\u223c\uff5e:：,|\u00b7"))
    if not text or is_generic_venue_name(text) or is_region_only_name(text):
        return ""
    if require_hint and not VENUE_HINT_RE.search(text):
        return ""
    if re.search(r"\d{4}[./-]\d{1,2}[./-]\d{1,2}", text):
        return ""
    return text[:100]


def raw_pair_maps_from_row(row: dict[str, Any]) -> list[dict[str, Any]]:
    raw_fields = row.get("raw_fields")
    if not isinstance(raw_fields, dict):
        return []
    maps: list[dict[str, Any]] = []
    for key in ("pairs", "list_pairs", "detail_pairs"):
        value = raw_fields.get(key)
        if isinstance(value, dict):
            maps.append(value)
    maps.append(raw_fields)
    return maps


def is_generic_parser_row(row: dict[str, Any]) -> bool:
    raw_fields = row.get("raw_fields")
    if not isinstance(raw_fields, dict):
        return False
    return clean_text(raw_fields.get("parser")).lower().startswith("generic_")


def structured_venue_name_from_row(row: dict[str, Any]) -> str:
    direct = normalize_venue_candidate(
        row.get("venue_name") or row.get("venue") or row.get("place") or row.get("room"),
        require_hint=is_generic_parser_row(row),
    )
    if direct:
        return direct
    top_level = {
        str(key): value
        for key, value in row.items()
        if isinstance(key, str) and key not in {"raw_fields", "description", "title"}
    }
    candidate = normalize_venue_candidate(first_by_keys(top_level, PROMOTABLE_VENUE_KEYS))
    if candidate:
        return candidate
    for pair_map in raw_pair_maps_from_row(row):
        candidate = normalize_venue_candidate(first_by_keys(pair_map, PROMOTABLE_VENUE_KEYS))
        if candidate:
            return candidate
    return ""


def trailing_venue_name_from_text(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    label_pattern = (
        r"(?:\uc7a5\uc18c|\uc7a5\uc18c\uba85|\uc7a5\uc18c/\uc704\uce58|\ud589\uc0ac\uc7a5\uc18c|"
        r"\uad50\uc721\uc7a5\uc18c|\uac15\uc758\uc7a5\uc18c|\uc704\uce58)\s*[:：]\s*"
    )
    stop_pattern = (
        r"(?=\s+(?:\ub300\uc0c1|\uae30\uac04|\uc77c\uc2dc|\uc2dc\uac04|\uc815\uc6d0|\ubb38\uc758|"
        r"\uc811\uc218|\uc2e0\uccad|\ube44\uc6a9|\uc694\uae08|\uc218\uac15\ub8cc)\s*[:：]|\Z)"
    )
    for match in re.finditer(label_pattern + r"(.{2,120}?)" + stop_pattern, text):
        candidate = normalize_venue_candidate(match.group(1))
        if candidate:
            return candidate

    date_pattern = r"(?:20\d{2}[./-]\s*\d{1,2}[./-]\s*\d{1,2}|\d{4}\s*\ub144\s*\d{1,2}\s*\uc6d4\s*\d{1,2}\s*\uc77c)"
    time_pattern = r"\d{1,2}\s*[:\uc2dc]\s*\d{0,2}\s*(?:\ubd84)?"
    marker_ends = [match.end() for match in re.finditer(date_pattern, text)]
    marker_ends.extend(match.end() for match in re.finditer(time_pattern, text))
    for start in sorted(marker_ends, reverse=True):
        candidate_text = text[start:]
        candidate_text = re.split(
            r"\s+(?:\uc2e0\uccad|\uc811\uc218|\uc608\uc57d|\uc608\ub9e4|\uc0c1\uc138\ubcf4\uae30|\uc790\uc138\ud788\ubcf4\uae30)\b",
            candidate_text,
            maxsplit=1,
        )[0]
        candidate = normalize_venue_candidate(candidate_text, require_hint=True)
        if candidate:
            return candidate
    return ""


def infer_venue_name_from_row(row: dict[str, Any], *, allow_text_fallback: bool = False) -> str:
    candidate = structured_venue_name_from_row(row)
    if candidate:
        return candidate
    if allow_text_fallback:
        candidate = trailing_venue_name_from_text(row.get("description"))
        if candidate:
            return candidate
        return trailing_venue_name_from_text(row.get("title"))
    return ""


def haman_course_row_from_link(
    target: CrawlTarget,
    current_url: str,
    link: Any,
    parser_name: str,
) -> dict[str, Any] | None:
    lines = lines_from_node(link)
    if len(lines) < 2:
        return None
    status = status_from_lines(lines) or lines[0]
    title = course_title_from_status_lines(lines, status)
    if not title or is_low_value_title(title):
        return None
    pairs = pairs_from_lines(lines)
    raw_url = normalize_link(current_url, link.get("href") if hasattr(link, "get") else None) or current_url
    branch = clean_text(pairs.get("교육기관")) or target.branch
    capacity = clean_text(pairs.get("신청/정원") or pairs.get("정원"))
    capacity_current, capacity_total = parse_capacity_pair(capacity)
    if capacity_total is None:
        capacity_total = parse_capacity_number(pairs.get("정원"))
    schedule_parts = [clean_text(pairs.get("강좌요일")), clean_text(pairs.get("강좌시간"))]
    schedule_raw = clean_text(" ".join(part for part in schedule_parts if part))
    application_method = clean_text(pairs.get("접수방법") or pairs.get("선별방법"))
    row = {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
        "title": title,
        "branch": branch,
        "category": clean_text(pairs.get("분류")) or "교육/강좌",
        "raw_url": raw_url,
        "application_url": raw_url if "인터넷" in application_method or "접수" in status else "",
        "status": status,
        "fee": clean_text(pairs.get("수강료") or pairs.get("부대비용")),
        "period": clean_text(pairs.get("교육기간")),
        "apply_period": clean_text(pairs.get("접수기간")),
        "schedule_raw": schedule_raw,
        "target": clean_text(pairs.get("교육대상") or pairs.get("대상")),
        "room": clean_text(pairs.get("교육장소")),
        "venue_name": clean_text(pairs.get("교육장소")),
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "application_method_raw": application_method,
        "description": clean_text(link.get_text(" ", strip=True)),
        "raw_fields": {"pairs": pairs, "lines": lines, "parser": parser_name},
    }
    return row


def enrich_haman_course_detail(row: dict[str, Any], detail_soup: BeautifulSoup) -> None:
    detail_node = detail_soup.select_one(".edu1view")
    if not detail_node:
        return
    lines = lines_from_node(detail_node)
    pairs = pairs_from_lines(lines)
    row["fee"] = clean_text(pairs.get("수강료") or row.get("fee"))
    row["period"] = clean_text(pairs.get("교육기간") or row.get("period"))
    row["apply_period"] = clean_text(pairs.get("접수기간") or row.get("apply_period"))
    schedule_parts = [clean_text(pairs.get("강좌요일")), clean_text(pairs.get("강좌시간"))]
    row["schedule_raw"] = clean_text(" ".join(part for part in schedule_parts if part)) or row.get("schedule_raw")
    row["room"] = clean_text(pairs.get("교육장소") or row.get("room"))
    row["venue_name"] = clean_text(pairs.get("교육장소") or row.get("venue_name"))
    row["capacity_total"] = parse_capacity_number(pairs.get("정원")) or row.get("capacity_total")
    row["capacity_current"] = parse_capacity_number(pairs.get("신청인원")) or row.get("capacity_current")
    row["phone"] = clean_text(pairs.get("문의처") or row.get("phone"))
    row["instructor"] = clean_text(pairs.get("강사명") or row.get("instructor"))
    row["description"] = clean_text(detail_node.get_text(" ", strip=True)) or row.get("description")
    raw_fields = row.setdefault("raw_fields", {})
    if isinstance(raw_fields, dict):
        raw_fields["detail_pairs"] = pairs


def collect_haman_welfare_lifelong(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    agency_counts: dict[str, int] = {}
    parsed = urlparse(target.url)
    query_agency = clean_text((parse_qs(parsed.query).get("agency") or [""])[0])
    agencies = [query_agency] if query_agency else list(HAMAN_WELFARE_AGENCIES)

    for agency in agencies:
        agency_count = 0
        for page in range(1, max_pages + 1):
            current_url = url_with_query(target.url, {"agency": agency, "cpage": page})
            soup = fetch_soup(s, current_url, timeout=timeout)
            pages += 1
            page_rows = 0
            for link in soup.select(".edu1list a[href*='amode=view'][href*='idx=']"):
                row = haman_course_row_from_link(target, current_url, link, "haman_lifelong_agency_list")
                if not row:
                    continue
                raw_url = clean_text(row.get("raw_url"))
                if raw_url and detail_pages < detail_limit:
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail_pages += 1
                        enrich_haman_course_detail(row, detail_soup)
                    except Exception as exc:
                        logger.debug("Haman detail fetch failed %s: %s", raw_url, exc)
                rows.append(row)
                page_rows += 1
                agency_count += 1
            pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='cpage=']"))
            if page_rows == 0:
                break
        agency_counts[agency] = agency_count

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "agencies": len(agencies),
        "agency_rows": agency_counts,
    }
    return dedupe_rows(rows), "haman_lifelong_agency_list+detail", meta


def collect_ulsannamgu_resident_autonomy(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    first_soup = fetch_soup(s, target.url, timeout=timeout)
    per_target_limit = int(target.extra.get("per_target_limit") or 0)
    options: list[tuple[str, str]] = []
    for option in first_soup.select("select[name='dongName'] option[value]"):
        value = clean_text(option.get("value"))
        name = clean_text(option.get_text(" ", strip=True))
        if value:
            options.append((value, name))
    if not options:
        value = clean_text((parse_qs(urlparse(target.url).query).get("dongName") or [""])[0])
        options = [(value, target.branch)] if value else [("", target.branch)]

    rows: list[dict[str, Any]] = []
    pages = 0
    contact_by_branch: dict[str, str] = {}
    for dong_value, dong_name in options[: max(1, max_pages)]:
        if per_target_limit > 0 and len(rows) >= per_target_limit:
            break
        current_url = url_with_query(target.url, {"dongName": dong_value, "pageIndex": None})
        soup = first_soup if current_url == target.url else fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        for table in soup.find_all("table"):
            header_cells = [clean_text(cell.get_text(" ", strip=True)) for cell in table.select("tr:first-child th")]
            if header_cells and {"센터명", "전화번호"}.issubset(set(header_cells)):
                for tr in table.find_all("tr")[1:]:
                    cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
                    for index in range(0, len(cells) - 1, 2):
                        if cells[index] and cells[index + 1]:
                            contact_by_branch[cells[index]] = cells[index + 1]

        for table in soup.find_all("table"):
            header_row = table.find("tr")
            headers = [clean_text(cell.get_text(" ", strip=True)) for cell in header_row.find_all(["th", "td"])] if header_row else []
            if "강좌명" not in headers or "교육기관" not in headers:
                continue
            for tr in table.find_all("tr")[1:]:
                cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
                if len(cells) < len(headers):
                    continue
                pairs = {headers[index]: cells[index] for index in range(min(len(headers), len(cells)))}
                title = clean_text(pairs.get("강좌명"))
                if not title or is_low_value_title(title):
                    continue
                branch = clean_text(pairs.get("교육기관") or dong_name or target.branch)
                schedule_raw = clean_text(" ".join(part for part in [pairs.get("수업요일"), pairs.get("수업시간")] if clean_text(part)))
                capacity = clean_text(pairs.get("모집인원"))
                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": stable_course_id(target.provider, current_url, title, branch),
                        "title": title,
                        "branch": branch,
                        "category": "주민자치프로그램",
                        "raw_url": current_url,
                        "application_url": "",
                        "status": "",
                        "fee": clean_text(pairs.get("수강료(3개월분)") or pairs.get("수강료")),
                        "period": "",
                        "apply_period": "",
                        "schedule_raw": schedule_raw,
                        "target": "",
                        "room": clean_text(pairs.get("장소")),
                        "venue_name": clean_text(pairs.get("장소")),
                        "capacity": capacity,
                        "capacity_total": parse_capacity_number(capacity),
                        "phone": clean_text(contact_by_branch.get(branch)),
                        "description": clean_text(" ".join(cells)),
                        "raw_fields": {"pairs": pairs, "parser": "ulsannamgu_resident_autonomy_table"},
                    }
                )
                if per_target_limit > 0 and len(rows) >= per_target_limit:
                    break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(options),
        "pagination_detected": False,
        "recursion_depth": 0,
        "branches": len(options),
    }
    return dedupe_rows(rows), "ulsannamgu_resident_autonomy_table", meta


def bukgu_daegu_category_from_soup(soup: BeautifulSoup, fallback: str) -> str:
    for selector in (".location strong", ".sub_title", ".content_title", "h1", "h2", "h3"):
        node = soup.select_one(selector)
        text = clean_text(node.get_text(" ", strip=True) if node else "")
        if text and "서비스 접속" not in text:
            return text
    return fallback


def bukgu_daegu_page_url(base_url: str, page: int) -> str:
    if page <= 1:
        return base_url
    return url_with_query(base_url, {"pageIndex": page})


def bukgu_daegu_row_from_card(
    target: CrawlTarget,
    current_url: str,
    category: str,
    card: Any,
) -> dict[str, Any] | None:
    lines = lines_from_node(card)
    if len(lines) < 2:
        return None
    status = status_from_lines(lines) or lines[0]
    title = course_title_from_status_lines(lines, status)
    if not title or is_low_value_title(title):
        return None
    pairs = pairs_from_lines(lines)
    link = card.find("a", href=True) if hasattr(card, "find") else None
    raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
    capacity = clean_text(pairs.get("수강인원") or pairs.get("교육대상/정원"))
    capacity_current, capacity_total = parse_capacity_pair(capacity)
    if capacity_total is None:
        capacity_total = parse_capacity_number(capacity)
    row = {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
        "title": title,
        "branch": target.branch,
        "category": category,
        "raw_url": raw_url,
        "application_url": raw_url if "접수" in status else "",
        "status": status,
        "fee": "",
        "period": clean_text(pairs.get("교육기간")),
        "apply_period": clean_text(pairs.get("접수기간")),
        "schedule_raw": clean_text(pairs.get("요일/교육시간")),
        "target": clean_text(pairs.get("교육대상") or pairs.get("교육대상/정원")),
        "room": clean_text(pairs.get("교육장소")),
        "venue_name": clean_text(pairs.get("교육장소")),
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "description": clean_text(card.get_text(" ", strip=True)),
        "raw_fields": {"pairs": pairs, "lines": lines, "parser": "bukgu_daegu_lec_list"},
    }
    return row


def enrich_bukgu_daegu_detail(row: dict[str, Any], detail_soup: BeautifulSoup) -> None:
    detail_pairs = pairs_from_tables(detail_soup)
    if not detail_pairs:
        return
    row["period"] = clean_text(detail_pairs.get("교육기간") or row.get("period"))
    row["apply_period"] = clean_text(detail_pairs.get("접수기간") or row.get("apply_period"))
    row["schedule_raw"] = clean_text(detail_pairs.get("요일/교육시간") or row.get("schedule_raw"))
    row["room"] = clean_text(detail_pairs.get("교육장소") or row.get("room"))
    row["venue_name"] = clean_text(detail_pairs.get("교육장소") or row.get("venue_name"))
    row["target"] = clean_text(detail_pairs.get("교육대상/정원") or row.get("target"))
    row["fee"] = clean_text(detail_pairs.get("수강료") or row.get("fee"))
    row["instructor"] = clean_text(detail_pairs.get("강사명") or row.get("instructor"))
    row["phone"] = clean_text(detail_pairs.get("문의") or row.get("phone"))
    capacity_current, capacity_total = parse_capacity_pair(detail_pairs.get("교육대상/정원"))
    row["capacity_current"] = capacity_current or row.get("capacity_current")
    row["capacity_total"] = capacity_total or parse_capacity_number(detail_pairs.get("교육대상/정원")) or row.get("capacity_total")
    raw_fields = row.setdefault("raw_fields", {})
    if isinstance(raw_fields, dict):
        raw_fields["detail_pairs"] = detail_pairs


def collect_bukgu_daegu_reservation(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    list_urls = [clean_text(url) for url in (target.extra.get("list_urls") or []) if clean_text(url)]
    if not list_urls:
        list_urls = [target.url]
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False

    for list_url in dict.fromkeys(list_urls):
        for page in range(1, max_pages + 1):
            current_url = bukgu_daegu_page_url(list_url, page)
            soup = fetch_soup(s, current_url, timeout=timeout)
            pages += 1
            category = bukgu_daegu_category_from_soup(soup, target.branch)
            page_rows = 0
            for card in soup.select(".lec_list"):
                row = bukgu_daegu_row_from_card(target, current_url, category, card)
                if not row:
                    continue
                raw_url = clean_text(row.get("raw_url"))
                if raw_url and raw_url != current_url and detail_pages < detail_limit:
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail_pages += 1
                        enrich_bukgu_daegu_detail(row, detail_soup)
                    except Exception as exc:
                        logger.debug("Bukgu Daegu detail fetch failed %s: %s", raw_url, exc)
                rows.append(row)
                page_rows += 1
            pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='pageIndex=']"))
            if page_rows == 0:
                break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(list_urls),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "bukgu_daegu_lec_list+detail", meta


def discover_jinju_toybank_branches(
    soup: BeautifulSoup,
    base_url: str,
) -> list[tuple[str, str, str]]:
    branches: list[tuple[str, str, str]] = []
    seen_urls: set[str] = set()
    fallback_by_url = {url: (code, name, url) for code, name, url in JINJU_TOYBANK_FALLBACK_BRANCHES}
    for link in soup.find_all("a", href=True):
        text = clean_text(link.get_text(" ", strip=True))
        branch_name = jinju_branch_name_for_all_course_link(link) or text
        if "장난감은행" not in branch_name or "대체수강" in branch_name:
            continue
        url = normalize_link(base_url, link.get("href"))
        if not url or url in seen_urls:
            continue
        fallback_branch = fallback_by_url.get(url)
        if not fallback_branch:
            continue
        branches.append(fallback_branch)
        seen_urls.add(url)
    if branches:
        return branches
    return list(JINJU_TOYBANK_FALLBACK_BRANCHES)


def jinju_page_url(branch_url: str, page: int) -> str:
    return url_with_query(branch_url, {"cpage": max(1, page)})


def jinju_last_page(soup: BeautifulSoup, current_url: str) -> int:
    pages = [1]
    for link in soup.select("a[href*='cpage=']"):
        href = normalize_link(current_url, link.get("href"))
        page_text = clean_text((parse_qs(urlparse(href).query).get("cpage") or [""])[0])
        if page_text.isdigit():
            pages.append(int(page_text))
        label = clean_text(link.get_text(" ", strip=True))
        if label.isdigit():
            pages.append(int(label))
    return max(pages)


def parse_jinju_toybank_item(
    target: CrawlTarget,
    item: Any,
    current_url: str,
    branch_code: str,
    branch_name: str,
    branch_url: str,
) -> dict[str, Any] | None:
    lines = lines_from_node(item)
    if len(lines) < 3:
        return None
    status = status_from_lines(lines)
    if not status:
        status = first_matching_line(lines, {"접수중", "접수마감", "대기", "신청대기", "정원마감"})
    title = course_title_from_status_lines(lines, status)
    if not title or is_low_value_title(title):
        return None
    pairs = pairs_from_lines(lines)
    link = item.find("a", href=True) if hasattr(item, "find") else None
    raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
    capacity = clean_text(pairs.get("정원/접수인원/대기자정원") or pairs.get("정원"))
    capacity_current, capacity_total = parse_capacity_pair(capacity)
    if capacity_total is None:
        capacity_total = parse_capacity_number(capacity)
    method_parts = [line for line in lines if line in {"인터넷", "방문", "전화"}]
    application_method = clean_text(" ".join(method_parts))
    fee = clean_text(pairs.get("수강료"))
    row = {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, branch_name),
        "title": title,
        "branch": branch_name,
        "branch_code": branch_code,
        "branch_url": branch_url,
        "category": clean_text(pairs.get("교육구분")),
        "raw_url": raw_url,
        "application_url": raw_url if "인터넷" in application_method or "접수" in status else "",
        "status": status,
        "fee": fee,
        "period": clean_text(pairs.get("교육기간")),
        "apply_period": clean_text(pairs.get("접수일시")),
        "schedule_raw": clean_text(pairs.get("요일시간")),
        "target": clean_text(pairs.get("신청대상")),
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "application_method_raw": application_method,
        "description": clean_text(item.get_text(" ", strip=True)),
        "raw_fields": {"pairs": pairs, "lines": lines, "parser": "jinju_toybank_branch_list"},
    }
    return row


def collect_jinju_toybank_booking(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    discovery_soup = fetch_soup(s, target.url, timeout=timeout)
    branches = discover_jinju_toybank_branches(discovery_soup, target.url)
    rows: list[dict[str, Any]] = []
    pages = 1
    pagination_detected = False
    branch_page_counts: dict[str, int] = {}
    branch_row_counts: dict[str, int] = {}

    for branch_code, branch_name, branch_url in branches:
        first_url = jinju_page_url(branch_url, 1)
        first_soup = fetch_soup(s, first_url, timeout=timeout)
        pages += 1
        last_page = min(max_pages, jinju_last_page(first_soup, first_url))
        branch_page_counts[branch_name] = last_page
        for page in range(1, last_page + 1):
            if page == 1:
                soup = first_soup
                current_url = first_url
            else:
                current_url = jinju_page_url(branch_url, page)
                soup = fetch_soup(s, current_url, timeout=timeout)
                pages += 1
            page_rows = 0
            for item in soup.select(".cp31edu1list1 > ul > li"):
                row = parse_jinju_toybank_item(target, item, current_url, branch_code, branch_name, branch_url)
                if row:
                    rows.append(row)
                    page_rows += 1
            branch_row_counts[branch_name] = branch_row_counts.get(branch_name, 0) + page_rows
            pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='cpage=']"))
            if page_rows == 0:
                break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(branches),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "branches": len(branches),
        "branch_pages": branch_page_counts,
        "branch_rows": branch_row_counts,
    }
    return dedupe_rows(rows), "jinju_toybank_branch_list", meta


SEONGNAM_LIST_LABEL_KEYS = {
    "\uAC15\uC88C\uBA85",
    "\uAD50\uC721\uAE30\uAD00",
    "\uAD50\uC721\uAE30\uAC04",
    "\uC6B4\uC601\uD615\uD0DC",
    "\uBAA8\uC9D1\uC778\uC6D0/\uC811\uC218\uC778\uC6D0",
    "\uC0C1\uD0DC",
    "\uC218\uAC15\uC815\uBCF4",
}


def seongnam_label_key(value: Any) -> str:
    return re.sub(r"[\s:：]+", "", clean_text(value))


def seongnam_value_lines(node: BeautifulSoup | None) -> list[str]:
    if node is None:
        return []
    lines = [clean_text(line) for line in node.get_text("\n", strip=True).splitlines() if clean_text(line)]
    return [line for line in lines if seongnam_label_key(line) not in SEONGNAM_LIST_LABEL_KEYS]


def collect_seongnam_learning_list(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            cells = tr.find_all("td")
            if len(cells) < 4:
                continue
            lines = [clean_text(line) for line in tr.get_text("\n", strip=True).splitlines() if clean_text(line)]
            title_link = cells[1].find("a") if len(cells) > 1 else None
            title_lines = seongnam_value_lines(cells[1] if len(cells) > 1 else None)
            title = next((line for line in title_lines if not is_low_value_title(line)), "")
            if not title and title_link:
                title = clean_text(title_link.get_text(" ", strip=True))
            if not title or is_low_value_title(title):
                continue
            branch_lines = seongnam_value_lines(cells[2] if len(cells) > 2 else None)
            branch_from_title = next(
                (
                    line
                    for line in title_lines[1:]
                    if line and not is_low_value_title(line) and seongnam_label_key(line) not in {"강좌", "시설"}
                ),
                "",
            )
            branch = branch_from_title or next(iter(branch_lines), target.branch)
            date_lines = seongnam_value_lines(cells[3] if len(cells) > 3 else None)
            date_indexes = [
                index for index, line in enumerate(date_lines)
                if re.fullmatch(r"\d{2}[.]\d{2}[.]\d{2}[.]?", line)
            ]
            period = ""
            schedule = ""
            if len(date_indexes) >= 2:
                start_date = date_lines[date_indexes[0]].rstrip(".")
                end_date = date_lines[date_indexes[1]].rstrip(".")
                period = f"{normalize_short_korean_date(start_date)} ~ {normalize_short_korean_date(end_date)}"
                schedule = clean_text(" ".join(line for line in date_lines[date_indexes[1] + 1:] if line != "~"))
            recruitment_lines = seongnam_value_lines(cells[4] if len(cells) > 4 else None)
            operation = next(iter(recruitment_lines), "")
            if operation:
                operation_key = seongnam_label_key(operation)
                if "모집인원" not in operation_key:
                    schedule = clean_text(" ".join(part for part in [schedule, operation] if part))
            capacity_lines = seongnam_value_lines(cells[5] if len(cells) > 5 else None)
            capacity = next(iter(capacity_lines), "")
            if recruitment_lines and "모집인원" in seongnam_label_key(recruitment_lines[0]):
                capacity = next((line for line in recruitment_lines[1:] if "명" in line or "인원" in line), capacity)
            status_values = {
                "접수중", "대기접수", "대기자신청", "대기자접수", "접수예정", "신청대기",
                "접수마감", "마감", "정원마감", "신청마감", "종료",
            }
            status_pool = [
                *seongnam_value_lines(cells[5] if len(cells) > 5 else None),
                *seongnam_value_lines(cells[6] if len(cells) > 6 else None),
                *lines,
            ]
            status = next((line for line in status_pool if line in status_values), "")
            if not status:
                status = next(iter(seongnam_value_lines(cells[6] if len(cells) > 6 else None)), "") or status_from_lines(lines)
            apply_period = ""
            apply_index = next(
                (
                    index for index, line in enumerate(lines)
                    if line in {
                        "\uC77C\uBC18 \uC811\uC218",
                        "\uC77C\uBC18 \uC778\uD130\uB137\uC811\uC218",
                        "\uC77C\uBC18 \uC778\uD130\uB137 \uC811\uC218",
                        "\uC811\uC218\uAE30\uAC04",
                    }
                ),
                -1,
            )
            if apply_index >= 0:
                apply_dates = [
                    line
                    for line in lines[apply_index + 1: apply_index + 8]
                    if re.search(r"\d{2}[.]\d{2}[.]\d{2}", line)
                ][:2]
                if len(apply_dates) == 2:
                    apply_period = f"{normalize_short_korean_date(apply_dates[0].rstrip('.'))} ~ {normalize_short_korean_date(apply_dates[1].rstrip('.'))}"
            onclick = ""
            link = tr.find("a", onclick=True)
            if link:
                onclick = clean_text(link.get("onclick"))
            match = re.search(r"fn_learning_detail\('([^']+)'\)", onclick)
            raw_url = (
                urljoin(current_url, f"/ilms/learning/learningDetail.do?learning_id={match.group(1)}")
                if match
                else current_url
            )
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "category": "",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": "",
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule,
                    "target": "",
                    "capacity": capacity,
                    "description": clean_text(tr.get_text(" ", strip=True)),
                    "raw_fields": {"lines": lines, "parser": "ilms_learning_table"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ilms_learning_table", meta


OSAN_EDU_LIST_URL = "https://www.osanedu.go.kr/app/app0101/selectEdcList.do"
OSAN_EDU_REFERER = "https://www.osanedu.go.kr/app/app0101/selectEdcView.do"


def osan_labeled_value(text: str, label: str, stop_labels: tuple[str, ...]) -> str:
    stop_pattern = "|".join(re.escape(stop) for stop in stop_labels if stop != label)
    pattern = re.escape(label) + r"\s*\|?\s*(.*?)(?=\s*(?:" + stop_pattern + r")\s*\|?|$)"
    match = re.search(pattern, text, re.DOTALL)
    return clean_text(match.group(1)) if match else ""


def parse_osan_edu_item(target: CrawlTarget, page_url: str, item: BeautifulSoup) -> dict[str, Any] | None:
    title_node = item.select_one("h3")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    if not title or is_low_value_title(title):
        return None
    header_spans = item.select("div.flex.items-center.gap-2.mb-3 span")
    status = clean_text(header_spans[0].get_text(" ", strip=True)) if header_spans else ""
    branch = clean_text(header_spans[1].get_text(" ", strip=True)) if len(header_spans) > 1 else target.branch
    text = clean_text(item.get_text(" ", strip=True))
    labels = (
        "\uAD50\uC721\uAE30\uAC04",
        "\uAD50\uC721\uC77C\uC2DC",
        "\uAD50\uC721\uB300\uC0C1",
        "\uC218\uAC15\uB8CC",
        "\uC120\uCC29",
        "\uCD94\uCCA8",
    )
    period = osan_labeled_value(text, "\uAD50\uC721\uAE30\uAC04", labels)
    schedule = osan_labeled_value(text, "\uAD50\uC721\uC77C\uC2DC", labels)
    target_text = osan_labeled_value(text, "\uAD50\uC721\uB300\uC0C1", labels)
    fee = osan_labeled_value(text, "\uC218\uAC15\uB8CC", labels)
    fee_match = re.search(r"\d[\d,]*\s*\uC6D0|무료", fee)
    if fee_match:
        fee = clean_text(fee_match.group(0))
    capacity_node = item.select_one(".st-num")
    capacity = clean_text(capacity_node.get_text(" ", strip=True)) if capacity_node else ""
    capacity = re.sub(r"^(\uC120\uCC29|\uCD94\uCCA8)\s*", "", capacity).strip()
    edc_code = clean_text(item.get("data-ecd"))
    edc_type = clean_text(item.get("data-ty")) or "LFT"
    raw_url = urljoin(page_url, f"/app/app0101/selectEdcDtls.do?edcCode={quote(edc_code)}&edcTy={quote(edc_type)}") if edc_code else page_url
    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, edc_code or raw_url, title, branch),
        "title": title,
        "branch": branch,
        "branch_code": clean_text(item.get("data-instt")),
        "category": "",
        "raw_url": raw_url,
        "application_url": raw_url,
        "status": status,
        "fee": fee,
        "period": period,
        "apply_period": "",
        "schedule_raw": schedule,
        "target": target_text,
        "capacity": capacity,
        "venue_name": branch,
        "description": text[:800],
        "raw_fields": {
            "parser": "osan_edu_ajax",
            "edc_code": edc_code,
            "edc_type": edc_type,
            "business_code": clean_text(item.get("data-bsns")),
        },
    }


def fetch_osan_edu_list(
    s: requests.Session,
    page_index: int,
    status_code: str,
    timeout: int,
) -> BeautifulSoup:
    payload: dict[str, Any] = {"pageIndex": str(page_index)}
    if status_code:
        payload["eduSttusList"] = status_code
    response = s.post(
        OSAN_EDU_LIST_URL,
        data=json.dumps({"reqData": payload}, ensure_ascii=False).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Accept": "text/html, */*; q=0.01",
            "Referer": OSAN_EDU_REFERER,
            "ajaxAt": "Y",
        },
        timeout=timeout,
    )
    response.raise_for_status()
    if not response.encoding or response.encoding.lower() == "iso-8859-1":
        response.encoding = response.apparent_encoding
    return BeautifulSoup(response.text, "lxml")


def collect_osan_edu_courses(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": OSAN_EDU_REFERER})
    fetch_soup(s, "https://www.osanedu.go.kr/app/app0101/selectEdcView.do", timeout=timeout)
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    status_page_counts: dict[str, int] = {}

    for status_code in ("02", "01"):
        status_pages = 0
        for page_index in range(1, max_pages + 1):
            soup = fetch_osan_edu_list(s, page_index=page_index, status_code=status_code, timeout=timeout)
            pages += 1
            status_pages += 1
            items = soup.select(".class_list .btn_dtls")
            pagination_detected = pagination_detected or bool(soup.select(".more_wrap, .pagination, input[name='totalRecordCount']"))
            if not items:
                break
            for item in items:
                row = parse_osan_edu_item(target, OSAN_EDU_REFERER, item)
                if row:
                    rows.append(row)
            total = clean_text((soup.select_one("input[name='totalRecordCount']") or {}).get("value", ""))
            if total.isdigit() and page_index * len(items) >= int(total):
                break
        status_page_counts[status_code] = status_pages

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "status_pages": status_page_counts,
    }
    return dedupe_rows(rows), "osan_edu_ajax", meta


def jjss_unique_reserv_links(soup: BeautifulSoup, base_url: str, required: tuple[str, ...]) -> list[str]:
    links: list[str] = []
    for link in soup.find_all("a", href=True):
        href = urljoin(base_url, clean_text(link.get("href")))
        if all(token in href for token in required):
            links.append(href)
    return list(dict.fromkeys(links))


def jjss_table_map(table: BeautifulSoup) -> list[dict[str, Any]]:
    headers = [clean_text(th.get_text(" ", strip=True)) for th in table.select("thead th")]
    if not headers:
        first_row = table.select_one("tr")
        headers = [clean_text(th.get_text(" ", strip=True)) for th in first_row.find_all("th")] if first_row else []
    if "\uAC15\uC2B5\uBA85" not in headers or "\uC811\uC218\uC0C1\uD0DC" not in headers:
        return []
    rows: list[dict[str, Any]] = []
    for tr in table.select("tbody tr"):
        cells = tr.find_all("td")
        if len(cells) < len(headers):
            continue
        values = {headers[index]: clean_text(cells[index].get_text(" ", strip=True)) for index in range(len(headers))}
        detail_link = tr.find("a", href=lambda href: href and "infoUid=" in href)
        values["_detail_url"] = clean_text(detail_link.get("href")) if detail_link else ""
        rows.append(values)
    return rows


def jjss_detail_fields(s: requests.Session, detail_url: str, timeout: int) -> dict[str, str]:
    if not detail_url:
        return {}
    soup = fetch_soup(s, detail_url, timeout=timeout)
    text = clean_text(soup.get_text(" ", strip=True))
    apply_period = ""
    match = re.search(r"\uC811\uC218\uAE30\uAC04\s*[:：]?\s*(\d{4}-\d{2}-\d{2}\s*[~\-]\s*\d{4}-\d{2}-\d{2})", text)
    if match:
        apply_period = clean_text(match.group(1).replace("-", "-", 2))
    fee = ""
    fee_match = re.search(r"(?:\uC694\uAE08\s*[:：]\s*)?(\d[\d,]*\s*\uC6D0)", text)
    if fee_match:
        fee = clean_text(fee_match.group(1))
    return {"apply_period": apply_period, "fee": fee, "description": text[:1000]}


def parse_jjss_course_rows(
    target: CrawlTarget,
    s: requests.Session,
    page_url: str,
    soup: BeautifulSoup,
    timeout: int,
    detail_remaining: int,
) -> tuple[list[dict[str, Any]], int]:
    rows: list[dict[str, Any]] = []
    for table in soup.select("table"):
        for values in jjss_table_map(table):
            title = values.get("\uAC15\uC2B5\uBA85", "")
            if not title or is_low_value_title(title):
                continue
            raw_url = urljoin(page_url, values.get("_detail_url") or page_url)
            detail: dict[str, str] = {}
            if detail_remaining > 0 and values.get("_detail_url"):
                try:
                    detail = jjss_detail_fields(s, raw_url, timeout=timeout)
                    detail_remaining -= 1
                except Exception as exc:
                    logger.debug("jjss detail fetch failed %s: %s", raw_url, exc)
            day = values.get("\uAC15\uC2B5\uC694\uC77C", "")
            time_band = values.get("\uC2DC\uAC04\uB300", "")
            time_text = values.get("\uAC15\uC2B5\uC2DC\uAC04", "")
            schedule = clean_text(" ".join(part for part in [day, time_band, time_text] if part))
            fee = detail.get("fee", "")
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, values.get("\uC2DC\uC124\uBA85", target.branch)),
                "title": title,
                "branch": values.get("\uC2DC\uC124\uBA85", target.branch),
                "category": values.get("\uC885\uBAA9", ""),
                "raw_url": raw_url,
                "application_url": raw_url if values.get("\uC811\uC218\uC0C1\uD0DC") == "\uC811\uC218\uC911" else "",
                "status": values.get("\uC811\uC218\uC0C1\uD0DC", ""),
                "fee": fee,
                "period": "",
                "apply_period": detail.get("apply_period", ""),
                "schedule_raw": schedule,
                "target": values.get("\uB2E8\uACC4", ""),
                "capacity": values.get("\uC815\uC6D0", ""),
                "instructor": values.get("\uAC15\uC0AC", ""),
                "venue_name": values.get("\uC2DC\uC124\uBA85", ""),
                "description": detail.get("description") or clean_text(" ".join(value for key, value in values.items() if not key.startswith("_")))[:800],
                "raw_fields": {"parser": "jjss_reserv_table", "cells": values},
            }
            rows.append(row)
    return rows, detail_remaining


def collect_jjss_reserv_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    start_soup = fetch_soup(s, target.url, timeout=timeout)
    facility_links = jjss_unique_reserv_links(start_soup, target.url, ("contentUid=0000000070e6710e0170e6d12df40255", "topUid=", "typeUid="))
    rows: list[dict[str, Any]] = []
    pages = 1
    detail_remaining = detail_limit
    subject_links: list[str] = []
    list_pages = 0

    for facility_url in facility_links[:max(1, max_pages)]:
        facility_soup = fetch_soup(s, facility_url, timeout=timeout)
        pages += 1
        subject_links.extend(
            jjss_unique_reserv_links(
                facility_soup,
                facility_url,
                ("contentUid=0000000070ce17640170ce28244d003d", "topUid=", "typeUid=", "tagUid="),
            )
        )

    for list_url in list(dict.fromkeys(subject_links))[:max(1, max_pages * 3)]:
        soup = fetch_soup(s, list_url, timeout=timeout)
        pages += 1
        list_pages += 1
        page_rows, detail_remaining = parse_jjss_course_rows(
            target,
            s,
            list_url,
            soup,
            timeout=timeout,
            detail_remaining=detail_remaining,
        )
        rows.extend(page_rows)

    meta = {
        "pages": pages,
        "detail_pages": detail_limit - detail_remaining,
        "discovered_links": len(facility_links) + len(subject_links),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 2,
        "list_pages": list_pages,
    }
    return dedupe_rows(rows), "jjss_reserv_table", meta


RAILROAD_MUSEUM_BRANCH = "\uCCA0\uB3C4\uBC15\uBB3C\uAD00"


def railroadmuseum_period(value: Any) -> str:
    text = clean_text(value)
    match = re.search(r"(20\d{2})[.\-](\d{1,2})[.\-](\d{1,2})\s*[~\-]\s*(20\d{2})[.\-](\d{1,2})[.\-](\d{1,2})", text)
    if not match:
        return text
    return (
        f"{match.group(1)}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"
        f" ~ {match.group(4)}-{int(match.group(5)):02d}-{int(match.group(6)):02d}"
    )


def railroadmuseum_label_value(lines: list[str], label: str) -> str:
    prefix = f"{label} :"
    compact_prefix = f"{label}:"
    for line in lines:
        text = clean_text(line)
        if text.startswith(prefix):
            return clean_text(text[len(prefix) :])
        if text.startswith(compact_prefix):
            return clean_text(text[len(compact_prefix) :])
    return ""


def parse_railroadmuseum_edu_cards(target: CrawlTarget, s: requests.Session, timeout: int) -> tuple[list[dict[str, Any]], int]:
    url = "https://www.railroadmuseum.co.kr/edu_res"
    soup = fetch_soup(s, url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    for card in soup.select(".event_card"):
        title = clean_text(card.select_one("h3").get_text(" ", strip=True) if card.select_one("h3") else "")
        if not title or is_low_value_title(title):
            continue
        link = card.find("a", href=True)
        raw_url = urljoin(url, link.get("href")) if link else url
        status = clean_text(card.select_one(".status_badge").get_text(" ", strip=True) if card.select_one(".status_badge") else "")
        info = [clean_text(node.get_text(" ", strip=True)) for node in card.select(".card_info p")]
        period = railroadmuseum_period(info[0]) if len(info) > 0 else ""
        venue = info[1] if len(info) > 1 else ""
        target_text = info[2] if len(info) > 2 else ""
        description = clean_text(card.get_text(" ", strip=True))
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, RAILROAD_MUSEUM_BRANCH),
                "title": title,
                "branch": RAILROAD_MUSEUM_BRANCH,
                "category": "\uAD50\uC721\uD504\uB85C\uADF8\uB7A8",
                "raw_url": raw_url,
                "application_url": "" if status == "\uC885\uB8CC" else raw_url,
                "status": status,
                "fee": "",
                "period": period,
                "apply_period": "",
                "schedule_raw": period,
                "target": target_text,
                "venue_name": venue,
                "description": description,
                "raw_fields": {"parser": "railroadmuseum_edu_card", "source_url": url, "info": info},
            }
        )
    return rows, 1


def parse_railroadmuseum_experience(target: CrawlTarget, s: requests.Session, timeout: int) -> tuple[list[dict[str, Any]], int]:
    url = "https://www.railroadmuseum.co.kr/page/experience"
    soup = fetch_soup(s, url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    for heading in soup.select(".sub_content h3"):
        title = clean_text(heading.get_text(" ", strip=True))
        if not title or is_low_value_title(title):
            continue
        siblings: list[BeautifulSoup] = []
        cursor = heading.find_next_sibling()
        while cursor and cursor.name != "h3":
            siblings.append(cursor)
            cursor = cursor.find_next_sibling()
        table_text = clean_text(" ".join(node.get_text(" ", strip=True) for node in siblings if getattr(node, "name", "") == "table"))
        lines = [
            clean_text(li.get_text(" ", strip=True))
            for node in siblings
            for li in node.find_all("li")
            if clean_text(li.get_text(" ", strip=True))
        ]
        venue = railroadmuseum_label_value(lines, "\uC7A5\uC18C") or railroadmuseum_label_value(lines, "\uC9D1\uACB0\uC7A5\uC18C")
        method = railroadmuseum_label_value(lines, "\uC811\uC218\uBC29\uBC95")
        duration = railroadmuseum_label_value(lines, "\uC18C\uC694\uC2DC\uAC04")
        fee = railroadmuseum_label_value(lines, "\uC774\uC6A9\uC694\uAE08")
        description = clean_text(" ".join([table_text, *lines]))
        status = method or "\uD604\uC7A5\uC811\uC218"
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, url, title, RAILROAD_MUSEUM_BRANCH),
                "title": title,
                "branch": RAILROAD_MUSEUM_BRANCH,
                "category": "\uCCB4\uD5D8/\uC804\uC2DC\uD574\uC124",
                "raw_url": url,
                "application_url": url,
                "status": status,
                "fee": fee,
                "period": "\uC0C1\uC2DC \uC6B4\uC601",
                "apply_period": "",
                "schedule_raw": table_text,
                "target": "\uAD00\uB78C\uAC1D",
                "venue_name": venue,
                "description": clean_text(" / ".join(part for part in [description, duration] if part)),
                "raw_fields": {"parser": "railroadmuseum_experience", "source_url": url, "method": method, "lines": lines},
            }
        )
    return rows, 1


def collect_railroadmuseum_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    edu_rows, edu_pages = parse_railroadmuseum_edu_cards(target, s, timeout=timeout)
    rows.extend(edu_rows)
    pages += edu_pages
    if max_pages > 1:
        experience_rows, experience_pages = parse_railroadmuseum_experience(target, s, timeout=timeout)
        rows.extend(experience_rows)
        pages += experience_pages
    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 1,
    }
    return dedupe_rows(rows), "railroadmuseum_programs", meta


NFM_BRANCH = "\uAD6D\uB9BD\uBBFC\uC18D\uBC15\uBB3C\uAD00"
NFM_EDU_LIST_URL = "https://www.nfm.go.kr/user/eduPlan/home/85/dataList.do?searchStatus=1&searchEduPlanCate="


def nfm_label_pairs(lines: list[str]) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for line in lines:
        if ":" not in line:
            continue
        key, value = line.split(":", 1)
        pairs[clean_text(key)] = clean_text(value)
    return pairs


def collect_national_folk_museum(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    for page in range(1, max(1, max_pages) + 1):
        list_url = f"{NFM_EDU_LIST_URL}&page={page}"
        soup = fetch_soup(s, list_url, timeout=timeout)
        pages += 1
        items = soup.select("li.mixed_item")
        if not items:
            break
        for item in items:
            title = clean_text(item.select_one(".item_title").get_text(" ", strip=True) if item.select_one(".item_title") else "")
            if not title or is_low_value_title(title):
                continue
            link = item.find("a", attrs={"onclick": True})
            onclick = clean_text(link.get("onclick") if link else "")
            match = re.search(r"fn_viewEduPlan\('([^']+)'\)", onclick)
            edu_plan_idx = match.group(1) if match else ""
            detail_url = (
                f"https://www.nfm.go.kr/user/eduPlan/home/85/dataView.do?eduPlanIdx={edu_plan_idx}"
                if edu_plan_idx
                else list_url
            )
            status = clean_text(item.select_one(".item_info").get_text(" ", strip=True) if item.select_one(".item_info") else "")
            lines = [clean_text(node.get_text(" ", strip=True)) for node in item.select(".item_txt") if clean_text(node.get_text(" ", strip=True))]
            pairs = nfm_label_pairs(lines)
            badges = [clean_text(node.get_text(" ", strip=True)) for node in item.select(".info_box") if clean_text(node.get_text(" ", strip=True))]
            period = railroadmuseum_period(pairs.get("\uAD50\uC721\uAE30\uAC04", ""))
            apply_period = railroadmuseum_period(pairs.get("\uC811\uC218\uAE30\uAC04", ""))
            target_text = pairs.get("\uC811\uC218\uB300\uC0C1", "")
            venue = pairs.get("\uAD50\uC721\uC7A5\uC18C", "")
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, detail_url, title, NFM_BRANCH),
                    "title": title,
                    "branch": NFM_BRANCH,
                    "category": badges[0] if badges else "\uAD50\uC721",
                    "raw_url": detail_url,
                    "application_url": detail_url if "\uC811\uC218\uC911" in status else "",
                    "status": status,
                    "fee": "",
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": period,
                    "target": target_text,
                    "venue_name": venue,
                    "description": clean_text(" ".join([status, title, *lines, *badges])),
                    "raw_fields": {"parser": "nfm_edu_plan_list", "source_url": list_url, "badges": badges, "pairs": pairs},
                }
            )
    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > 1,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "nfm_edu_plan_list", meta


AVIATION_BRANCH = "\uAD6D\uB9BD\uD56D\uACF5\uBC15\uBB3C\uAD00"
AVIATION_GROUP_EDU_URL = "https://www.aviation.or.kr/reservation-edu.do?menuno=336"


def aviation_section_nodes(soup: BeautifulSoup, label: str) -> list[Any]:
    heading = None
    for candidate in soup.select(".eduRev h4"):
        if clean_text(candidate.get_text(" ", strip=True)) == label:
            heading = candidate
            break
    if not heading:
        return []
    nodes: list[Any] = []
    cursor = heading.find_next_sibling()
    while cursor and getattr(cursor, "name", "") != "h4":
        nodes.append(cursor)
        cursor = cursor.find_next_sibling()
    return nodes


def aviation_section_text(soup: BeautifulSoup, label: str) -> str:
    return clean_text(" ".join(node.get_text(" ", strip=True) for node in aviation_section_nodes(soup, label)))


def aviation_month_period(month_value: int) -> str:
    year = datetime.now().year
    last_day = calendar.monthrange(year, month_value)[1]
    return f"{year}-{month_value:02d}-01 ~ {year}-{month_value:02d}-{last_day:02d}"


def aviation_month_status(month_value: int) -> str:
    current_month = datetime.now().month
    if month_value < current_month:
        return "\uB9C8\uAC10"
    if month_value == current_month:
        return "\uC811\uC218\uC911"
    return "\uC811\uC218\uC608\uC815"


def collect_national_aviation_museum(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, AVIATION_GROUP_EDU_URL, timeout=timeout)
    target_text = aviation_section_text(soup, "\uAD50\uC721 \uB300\uC0C1")
    program_text = aviation_section_text(soup, "\uAD50\uC721 \uD504\uB85C\uADF8\uB7A8")
    period_text = aviation_section_text(soup, "\uAD50\uC721 \uAE30\uAC04")
    application_nodes = aviation_section_nodes(soup, "\uC2E0\uCCAD \uBC29\uBC95")
    rows: list[dict[str, Any]] = []
    for node in application_nodes:
        for link in node.find_all("a", href=True):
            href = clean_text(link.get("href"))
            if not href:
                continue
            li = link.find_parent("li")
            title_text = clean_text(li.get_text(" ", strip=True) if li else link.get_text(" ", strip=True))
            title_text = clean_text(title_text.replace("\uBC14\uB85C \uAC00\uAE30", ""))
            month_match = re.search(r"\[(\d{1,2})\uC6D4\]", title_text)
            month_value = int(month_match.group(1)) if month_match else 0
            period = aviation_month_period(month_value) if month_value else period_text
            status = aviation_month_status(month_value) if month_value else "\uC811\uC218\uC911"
            is_childcare = "\uC5B4\uB9B0\uC774\uC9D1" in title_text
            row_target = (
                "24\uAC1C\uC6D4~48\uAC1C\uC6D4 \uC5B4\uB9B0\uC774\uC9D1 \uB2E8\uCCB4"
                if is_childcare
                else "\uCD08\u00B7\uC911\u00B7\uACE0\uB4F1\uD559\uAD50 \uD559\uAE09 \uB2E8\uCCB4 \uBC0F \uAD6D\uACF5\uB9BD \uB3CC\uBD04\u00B7\uCCAD\uC18C\uB144\uC13C\uD130 \uB2E8\uCCB4"
            )
            title = clean_text(f"{AVIATION_BRANCH} {title_text}")
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, href, title, AVIATION_BRANCH),
                    "title": title,
                    "branch": AVIATION_BRANCH,
                    "category": "\uB2E8\uCCB4\uAD50\uC721",
                    "raw_url": AVIATION_GROUP_EDU_URL,
                    "application_url": href if status != "\uB9C8\uAC10" else "",
                    "status": status,
                    "fee": "",
                    "period": period,
                    "apply_period": period,
                    "schedule_raw": period,
                    "target": row_target,
                    "venue_name": AVIATION_BRANCH,
                    "description": clean_text(" ".join([target_text, program_text, period_text, title_text])),
                    "raw_fields": {"parser": "aviation_group_edu", "source_url": AVIATION_GROUP_EDU_URL, "title_text": title_text},
                }
            )
    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "aviation_group_edu", meta


NAMUK_BRANCH = "\uAD6D\uB9BD\uB18D\uC5C5\uBC15\uBB3C\uAD00"
NAMUK_EDU_URL = "https://www.namuk.or.kr/kr/204/subview.do"


def namuk_info_pairs(item: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in item.select(".info ul li"):
        label = clean_text(li.select_one(".info-title").get_text(" ", strip=True) if li.select_one(".info-title") else "")
        value = clean_text(li.select_one("p").get_text(" ", strip=True) if li.select_one("p") else "")
        if label and value:
            pairs[label] = value
    return pairs


def collect_national_agricultural_museum(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, NAMUK_EDU_URL, timeout=timeout)
    rows: list[dict[str, Any]] = []
    for item in soup.select(".event-wrap .list-webzine > li"):
        title = clean_text(item.select_one(".title strong").get_text(" ", strip=True) if item.select_one(".title strong") else "")
        if not title or is_low_value_title(title):
            continue
        badges = [clean_text(node.get_text(" ", strip=True)) for node in item.select(".type-text-box") if clean_text(node.get_text(" ", strip=True))]
        status = badges[0] if badges else ""
        fee = badges[1] if len(badges) > 1 else ""
        category = badges[2] if len(badges) > 2 else "\uAD50\uC721"
        pairs = namuk_info_pairs(item)
        link = item.find("a", attrs={"onclick": True})
        onclick = clean_text(link.get("onclick") if link else "")
        match = re.search(r"reserv_View\('([^']+)','([^']+)','([^']+)'\)", onclick)
        reservation_id = match.group(2) if match else stable_course_id(target.provider, NAMUK_EDU_URL, title, NAMUK_BRANCH)
        raw_url = f"{NAMUK_EDU_URL}#{reservation_id}"
        period = railroadmuseum_period(pairs.get("\uAE30\uAC04", ""))
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, NAMUK_BRANCH),
                "title": title,
                "branch": NAMUK_BRANCH,
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url if "\uC811\uC218\uC911" in status else "",
                "status": status,
                "fee": fee,
                "period": period,
                "apply_period": "",
                "schedule_raw": period,
                "target": pairs.get("\uB300\uC0C1", ""),
                "venue_name": pairs.get("\uC7A5\uC18C", NAMUK_BRANCH),
                "description": clean_text(" ".join([*badges, title, *pairs.values()])),
                "raw_fields": {"parser": "namuk_reservation_list", "source_url": NAMUK_EDU_URL, "onclick": onclick, "pairs": pairs},
            }
        )
    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": bool(soup.select_one("._paging")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "namuk_reservation_list", meta


def hscity_detail_url(current_url: str, item: BeautifulSoup) -> str:
    onclick = clean_text((item.select_one(".table-list-main") or item).get("onclick") if item else "")
    match = re.search(r"fnDetail\('([^']+)'\)", onclick)
    lecture_idx = match.group(1) if match else ""
    if not lecture_idx:
        hidden = item.find("input", attrs={"name": re.compile(r"\.serviceIdx$")}) if item else None
        lecture_idx = clean_text(hidden.get("value") if hidden else "")
    if not lecture_idx:
        hidden_detail = item.find("input", attrs={"value": re.compile(r"lectureDetail\.do")}) if item else None
        href = clean_text(hidden_detail.get("value") if hidden_detail else "")
        href_match = re.search(r"lectureIdx=(\d+)", href)
        lecture_idx = href_match.group(1) if href_match else ""
    if not lecture_idx:
        return ""
    parsed = urlparse(current_url)
    return f"{parsed.scheme}://{parsed.netloc}/1002/3001/lectureDetail.do?lectureIdx={lecture_idx}"


def hscity_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for dl in soup.select(".detail-info-list dl.item-desc"):
        key_node = dl.select_one("dt.desc-title")
        value_node = dl.select_one("dd.desc-txt")
        key = clean_text(key_node.get_text(" ", strip=True) if key_node else "")
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if not key or not value:
            continue
        value = clean_text(value.replace("\uBC14\uB85C\uAC00\uAE30", "").replace("\uAC15\uC0AC\uC774\uB825\uBCF4\uAE30", ""))
        pairs[key] = value
    return pairs


def hscity_description(soup: BeautifulSoup) -> str:
    node = soup.select_one(".detail-tab.info-tab") or soup.select_one(".detail-tab-item.active")
    if not node:
        return ""
    return clean_text(node.get_text(" ", strip=True))[:2000]


def hscity_image_url(detail_url: str, soup: BeautifulSoup) -> str:
    image = soup.select_one("img[src*='/attach/editor/']")
    src = clean_text(image.get("src") if image else "")
    return urljoin(detail_url, src) if src else ""


def hscity_clean_title(title: str, branch: str) -> str:
    value = clean_text(title)
    branch = clean_text(branch)
    match = re.match(r"^\[([^\]]+)\]\s*(.+)$", value)
    if match and branch and clean_text(match.group(1)) == branch:
        return clean_text(match.group(2))
    return value


def hscity_status_from_item(item: BeautifulSoup, detail_status: str = "") -> str:
    if detail_status:
        return detail_status
    text = clean_text(item.get_text(" ", strip=True))
    if "\ub300\uae30\uc2e0\uccad" in text or "\ub300\uae30\uc811\uc218" in text:
        return "\ub300\uae30\uc811\uc218"
    if "\uc2e0\uccad\ud558\uae30" in text or "\uc811\uc218\uc911" in text:
        return "\uc811\uc218\uc911"
    if "\uc811\uc218\uc608\uc815" in text:
        return "\uc811\uc218\uc608\uc815"
    if "\uc811\uc218\ub9c8\uac10" in text or "\uac15\uc88c\uc885\ub8cc" in text or "\ub9c8\uac10" in text:
        return "\uc811\uc218\ub9c8\uac10"
    return ""


def hscity_capacity_pair(value: str, label: str) -> tuple[Optional[int], Optional[int]]:
    text = clean_text(value).replace(",", "")
    match = re.search(rf"{re.escape(label)}\s*:?\s*(\d{{1,5}})\s*/\s*(\d{{1,5}})", text)
    if match:
        return int(match.group(1)), int(match.group(2))
    return parse_capacity_pair(text)


def collect_hscity_lecture_list(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 30,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    labels = {"\uAC15\uC88C\uAE30\uAC04", "\uC811\uC218\uAE30\uAC04", "\uC2E0\uCCAD\uC790\uC218", "\uB300\uAE30\uC790\uC218", "\uC218\uAC15\uB8CC", "\uC811\uC218\uBC29\uBC95", "\uBB38\uC758\uCC98"}
    pagination_detected = False
    base_status = clean_text((base_query.get("statusCd") or [""])[0])
    status_filters = [base_status]
    if not base_status and clean_text((base_query.get("searchInstitutionTypeCd") or [""])[0]) == "INS01":
        status_filters = ["apply", "wait", "ready", "finish"]

    for status_filter in status_filters:
        for page in range(1, max_pages + 1):
            query = dict(base_query)
            query["statusCd"] = [status_filter]
            query["currentPageNo"] = [str(page)]
            current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
            soup = fetch_soup(s, current_url, timeout=timeout)
            pages += 1
            page_rows = 0
            for item in soup.select(".table-list-item"):
                main = item.select_one(".table-list-main") or item
                lines = [clean_text(line) for line in main.get_text("\n", strip=True).splitlines() if clean_text(line)]
                if len(lines) < 5:
                    continue
                title, target_text, fee_hint, list_branch = lines[:4]
                if not title or is_low_value_title(title):
                    continue
                pairs = sequence_lines_to_pairs(lines[4:], labels)
                raw_url = hscity_detail_url(current_url, item) or current_url
                detail_pairs: dict[str, str] = {}
                description = clean_text(item.get_text(" ", strip=True))
                image_url = ""
                if raw_url != current_url and detail_pages < max(1, detail_limit):
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail_pages += 1
                        detail_pairs = hscity_detail_pairs(detail_soup)
                        detail_status = clean_text(
                            (
                                detail_soup.select_one(".detail-info-head .flag-list")
                                or detail_soup.select_one(".detail-info-head")
                                or detail_soup
                            ).get_text(
                                " ",
                                strip=True,
                            )
                        )
                        if detail_status:
                            detail_pairs["\uC0C1\uD0DC"] = detail_status
                        description = hscity_description(detail_soup) or description
                        image_url = hscity_image_url(raw_url, detail_soup)
                    except Exception as exc:
                        logger.debug("hscity lecture detail fetch failed %s: %s", raw_url, exc)
                branch = clean_text(detail_pairs.get("\uC6B4\uC601\uAE30\uAD00") or list_branch or target.branch)
                title = hscity_clean_title(detail_pairs.get("\uAC15\uC88C\uBA85") or title, branch)
                capacity_current, capacity_total = hscity_capacity_pair(
                    detail_pairs.get("\uC2E0\uCCAD/\uB300\uAE30") or pairs.get("\uC2E0\uCCAD\uC790\uC218", ""),
                    "\uC2E0\uCCAD\uC790\uC218",
                )
                waitlist_current, waitlist_total = hscity_capacity_pair(
                    detail_pairs.get("\uC2E0\uCCAD/\uB300\uAE30") or pairs.get("\uB300\uAE30\uC790\uC218", ""),
                    "\uB300\uAE30\uC790\uC218",
                )
                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                        "title": title,
                        "branch": branch,
                        "venue_name": clean_text(detail_pairs.get("\uC7A5\uC18C")) or branch,
                        "category": clean_text(detail_pairs.get("\uAC15\uC88C\uBD84\uB958")) or "\uB3C4\uC11C\uAD00",
                        "raw_url": raw_url,
                        "application_url": raw_url,
                        "status": hscity_status_from_item(item, detail_pairs.get("\uC0C1\uD0DC", "")),
                        "fee": clean_text(detail_pairs.get("\uC218\uAC15\uB8CC") or pairs.get("\uC218\uAC15\uB8CC")) or fee_hint,
                        "material_fee": clean_text(detail_pairs.get("\uC7AC\uB8CC\uBE44")),
                        "period": normalize_mixed_date_range(detail_pairs.get("\uC218\uAC15\uAE30\uAC04", ""))
                        or normalize_month_day_range(pairs.get("\uC811\uC218\uAE30\uAC04", "")),
                        "apply_period": normalize_mixed_date_range(detail_pairs.get("\uC811\uC218\uC77C\uC2DC", ""))
                        or normalize_month_day_range(pairs.get("\uC811\uC218\uAE30\uAC04", "")),
                        "schedule_raw": clean_text(detail_pairs.get("\uC694\uC77C/\uC2DC\uAC04")),
                        "target": target_text,
                        "capacity": capacity_total,
                        "capacity_current": capacity_current,
                        "capacity_total": capacity_total,
                        "waitlist_total": waitlist_total,
                        "application_method_raw": clean_text(detail_pairs.get("\uC811\uC218\uBC29\uBC95") or pairs.get("\uC811\uC218\uBC29\uBC95")),
                        "instructor": clean_instructor_name(detail_pairs.get("\uAC15\uC0AC\uBA85")),
                        "description": description,
                        "image_url": image_url,
                        "program_type": "\uAC15\uC88C",
                        "raw_fields": {
                            "pairs": pairs,
                            "detail_pairs": detail_pairs,
                            "lines": lines,
                            "status_filter": status_filter,
                            "waitlist_current": waitlist_current,
                            "parser": "hscity_library_lecture_list+detail",
                        },
                    }
                )
                page_rows += 1
            pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='currentPageNo=']"))
            if page_rows == 0:
                break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "hscity_library_lecture_list+detail", meta


def normalize_ydp_schedule(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    days = "\uC6D4\uD654\uC218\uBAA9\uAE08\uD1A0\uC77C"
    return re.sub(rf"\b([{days}])\s+\1\b", r"\1", text)


def collect_ydp_reserve_list(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        if page > 1:
            query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        page_has_pagination = bool(soup.select(".pagination, .paging, a[href*='pageIndex=']"))
        containers = soup.select("ul.board-lines > li")
        if not containers:
            containers = soup.select(".list-area")
        for container in containers:
            item = container.select_one(".list-area") or container
            lines = [clean_text(line) for line in item.get_text("\n", strip=True).splitlines() if clean_text(line)]
            if not lines:
                continue
            title_link = item.select_one("a.lists[href]") or item.find("a", href=True)
            title = clean_text(title_link.get_text(" ", strip=True)) if title_link else lines[0]
            if not title or is_low_value_title(title):
                continue
            raw_url = normalize_link(current_url, title_link.get("href") if title_link else None) or current_url
            status_text = clean_text((container.select_one("a.sk span") or container.select_one("a.sk") or "").get_text(" ", strip=True))
            branch_text = clean_text((item.select_one(".adds .ad") or "").get_text(" ", strip=True))
            target_text = clean_text((item.select_one(".adds .as") or "").get_text(" ", strip=True)).lstrip("#")
            row: dict[str, Any] = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": branch_text or (lines[1] if len(lines) > 1 else target.branch),
                "category": "",
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status_text,
                "fee": "",
                "period": "",
                "apply_period": "",
                "schedule_raw": "",
                "target": target_text or (clean_text(lines[2].lstrip("#")) if len(lines) > 2 else ""),
                "description": clean_text(item.get_text(" ", strip=True)),
                "raw_fields": {"lines": lines, "parser": "ydp_reserve_list"},
            }
            if raw_url and detail_pages < 30:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    for tr in detail_soup.select("table tr"):
                        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
                        cells = [cell for cell in cells if cell]
                        if not cells:
                            continue
                        if cells[0] == "\uACFC\uC815\uBA85" and len(cells) > 1:
                            row["title"] = cells[1]
                        elif cells[0] == "\uAD50\uC721\uC7A5\uC18C" and len(cells) > 1:
                            row["branch"] = cells[1]
                            if len(cells) > 3:
                                row["instructor"] = cells[3]
                        elif cells[0] == "\uC811\uC218\uBC29\uC2DD" and len(cells) > 1:
                            row["application_method_raw"] = cells[1]
                            if len(cells) > 3:
                                row["target"] = cells[3].lstrip("#")
                        elif cells[0] == "\uC218\uAC15\uB8CC" and len(cells) > 1:
                            row["fee"] = cells[1]
                            if len(cells) > 3:
                                row["material_fee"] = cells[3]
                        elif cells[0] == "\uC811\uC218\uAE30\uAC04" and len(cells) > 1:
                            row["apply_period"] = normalize_yymmdd_range(" ~ ".join(cells[1:]))
                        elif cells[0] == "\uAD50\uC721\uC7A5\uC18C" and len(cells) > 1:
                            row["period"] = normalize_yymmdd_range(" ~ ".join(cells[1:]))
                        elif cells[0] == "\uAC15\uC758\uC694\uC77C" and len(cells) > 1:
                            row["schedule_raw"] = normalize_ydp_schedule(" ".join(cells[1:]))
                        elif cells[0] == "\uC815\uC6D0" and len(cells) > 1:
                            row["capacity"] = clean_text(" ".join(cells[1:]))
                        elif cells[0] in {"\uAC15\uC758\uAC1C\uC694", "\uC218\uAC15\uC2E0\uCCAD\uC720\uC758\uC0AC\uD56D"}:
                            row["description"] = clean_text(" ".join(cells[1:])) or row["description"]
                except Exception as exc:
                    logger.debug("YDP detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
        pagination_detected = pagination_detected or page_has_pagination
        if page_rows == 0:
            break
        if not page_has_pagination:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ydp_reserve_list", meta


def ice_library_branch_name(soup: BeautifulSoup, target: CrawlTarget) -> str:
    title = clean_text(soup.title.get_text(" ", strip=True) if soup.title else "")
    if title:
        candidate = clean_text(title.split(">", 1)[0])
        candidate = clean_text(candidate.replace("?몄쿇愿묒뿭?쒓탳?≪껌", ""))
        if candidate:
            return candidate
    return target.branch


def ice_library_footer_address(soup: BeautifulSoup) -> str:
    text = clean_text((soup.select_one(".address") or soup.select_one("#footer") or soup).get_text(" ", strip=True))
    match = re.search(r"주소\s*:\s*(?:\(\s*)?\d{5}\s*\)?\s*(.+?)(?:\s*대표전화|\s*FAX|\s*Copyright|\s*$)", text)
    if match:
        return clean_text(match.group(1))
    match = re.search(r"인천\s+[^\s]+구\s+.+?(?=\s*(?:대표전화|FAX|Copyright|$))", text)
    return clean_text(match.group(0)) if match else ""


def ice_library_item_pairs(item: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in item.select(".con2 li"):
        label_node = li.select_one("label")
        if not label_node:
            continue
        label = clean_text(label_node.get_text(" ", strip=True)).rstrip(":")
        label_text = clean_text(label_node.get_text(" ", strip=True))
        value = clean_text(li.get_text(" ", strip=True))
        value = clean_text(value.replace(label_text, "", 1)).lstrip(":").strip()
        if label:
            pairs[label] = value
    return pairs


def ice_library_detail_url(base_url: str, item: Any) -> str:
    link = item.select_one("a.detail-btn[keyvalue1][keyvalue2][keyvalue3], a.detail-btn[keyValue1][keyValue2][keyValue3]")
    if not link:
        link = item.select_one("a.toggle-btn[keyvalue1][keyvalue2][keyvalue3], a.toggle-btn[keyValue1][keyValue2][keyValue3]")
    if not link:
        return base_url
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    menu_idx = clean_text((query.get("menu_idx") or [""])[0])
    params = {
        "group_idx": clean_text(link.get("keyvalue1") or link.get("keyValue1")),
        "category_idx": clean_text(link.get("keyvalue2") or link.get("keyValue2")),
        "teach_idx": clean_text(link.get("keyvalue3") or link.get("keyValue3")),
    }
    if menu_idx:
        params["menu_idx"] = menu_idx
    return urljoin(base_url, f"{parsed.path.rsplit('/index.do', 1)[0]}/detail.do?{urlencode(params)}")


def ice_library_application_url(base_url: str, item: Any) -> str:
    link = item.select_one(".stat a.add[keyvalue1], .stat a.add[keyValue1]")
    if not link:
        return ice_library_detail_url(base_url, item)
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    menu_idx = clean_text((query.get("menu_idx") or [""])[0])
    params = {
        "editMode": "ADD",
        "homepage_id": clean_text(link.get("keyvalue1") or link.get("keyValue1")),
        "group_idx": clean_text(link.get("keyvalue2") or link.get("keyValue2")),
        "category_idx": clean_text(link.get("keyvalue3") or link.get("keyValue3")),
        "teach_idx": clean_text(link.get("keyvalue4") or link.get("keyValue4")),
        "large_category_idx": clean_text(link.get("keyvalue5") or link.get("keyValue5")),
        "apply_status": clean_text(link.get("apply_status")),
    }
    if menu_idx:
        params["menu_idx"] = menu_idx
    return urljoin(base_url, f"{parsed.path.rsplit('/index.do', 1)[0]}/student/edit.do?{urlencode(params)}")


def ice_library_detail_fields(s: requests.Session, detail_url: str, timeout: int) -> dict[str, str]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    pairs = pairs_from_tables(soup)
    period = normalize_mixed_date_range(clean_text(pairs.get("강의기간(*)") or pairs.get("강의기간")))
    day_text = clean_text(pairs.get("강의요일"))
    time_text = clean_text(pairs.get("강의시간"))
    schedule = clean_text(" ".join(part for part in [day_text, time_text] if part))
    return {
        "category": clean_text(pairs.get("교육과정")),
        "description": clean_text(pairs.get("강의 설명") or pairs.get("강의설명")),
        "period": period,
        "schedule_raw": schedule,
        "apply_period": normalize_mixed_date_range(clean_text(pairs.get("접수일시") or pairs.get("접수기간"))),
        "target": clean_text(pairs.get("교육대상")),
        "venue_name": clean_text(pairs.get("강의장소")),
        "room": clean_text(pairs.get("강의장소")),
        "instructor": clean_text(pairs.get("강사명")),
        "material_note": clean_text(pairs.get("준비물")),
        "capacity": clean_text(pairs.get("현재 참여 / 모집") or pairs.get("모집정원")),
        "department": clean_text(pairs.get("담당부서 및 전화번호") or pairs.get("문의")),
    }


def collect_ice_library_teach_detail(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    branch = ice_library_branch_name(soup, target)
    branch_code = clean_text(urlparse(target.url).path.strip("/").split("/", 1)[0])
    address = ice_library_footer_address(soup)
    rows: list[dict[str, Any]] = []
    detail_pages = 0

    for item in soup.select(".item"):
        category = clean_text((item.select_one(".ca") or {}).get_text(" ", strip=True) if item.select_one(".ca") else "")
        title = clean_text((item.select_one("a.toggle-btn:not(.btn)") or {}).get_text(" ", strip=True) if item.select_one("a.toggle-btn:not(.btn)") else "")
        if not title or is_low_value_title(title):
            continue
        pairs = ice_library_item_pairs(item)
        period, schedule = split_period_and_schedule(pairs.get("강의기간", ""))
        status = clean_text((item.select_one(".stat a") or {}).get_text(" ", strip=True) if item.select_one(".stat a") else "") or status_from_lines(
            [clean_text(line) for line in item.get_text("\n", strip=True).splitlines()]
        )
        detail_url = ice_library_detail_url(target.url, item)
        application_url = ice_library_application_url(target.url, item)
        detail: dict[str, str] = {}
        if detail_url != target.url:
            try:
                detail = ice_library_detail_fields(s, detail_url, timeout=timeout)
                detail_pages += 1
            except Exception as exc:
                logger.debug("ICE library detail fetch failed %s: %s", detail_url, exc)

        row = {
            "provider": target.provider,
            "provider_course_id": stable_course_id(target.provider, detail_url, title, branch),
            "title": title,
            "branch": branch,
            "branch_code": branch_code,
            "category": detail.get("category") or category,
            "raw_url": detail_url,
            "application_url": application_url,
            "status": status,
            "fee": "",
            "period": clean_text(detail.get("period") or period),
            "apply_period": clean_text(detail.get("apply_period") or pairs.get("접수기간", "")),
            "schedule_raw": clean_text(detail.get("schedule_raw") or schedule),
            "target": clean_text(detail.get("target") or pairs.get("교육대상", "")),
            "capacity": clean_text(detail.get("capacity") or pairs.get("모집인원", "") or pairs.get("접수현황", "")),
            "instructor": clean_text(detail.get("instructor") or pairs.get("강사명", "")),
            "venue_name": clean_text(detail.get("venue_name") or branch),
            "room": clean_text(detail.get("room", "")),
            "address": address,
            "venue_address": address,
            "phone": clean_text(detail.get("department", "")),
            "material_note": clean_text(detail.get("material_note", "")),
            "description": clean_text(detail.get("description") or pairs.get("상세내용", "") or item.get_text(" ", strip=True)),
            "collection_category": "도서관",
            "domain_category": "도서관",
            "operator_type": "교육청 도서관",
            "source_group": "library",
            "collection_type": "static_html",
            "program_type": "강좌",
            "application_type": "ONLINE_RESERVATION",
            "reservation_available": status in {"수강신청", "대기자신청", "접수중"},
            "raw_fields": {"pairs": pairs, "detail_url": detail_url, "parser": "ice_library_teach_detail"},
        }
        rows.append(row)

    meta = {
        "pages": 1,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "pagination_detected": bool(soup.select(".pagination, .paging")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ice_library_teach_detail", meta


def collect_ice_library_teach(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    return collect_ice_library_teach_detail(target, timeout=timeout, max_pages=max_pages)


def collect_ice_library_teach_legacy(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    soup = fetch_soup(s, target.url, timeout=timeout)
    labels = {"접수기간", "모집인원", "접수현황", "강의기간", "모집대상", "강사명", "학년제한", "상세내용"}

    for item in soup.select(".item"):
        lines = [clean_text(line) for line in item.get_text("\n", strip=True).splitlines() if clean_text(line)]
        if len(lines) < 4:
            continue
        category = lines[0]
        title = lines[1]
        if not title or is_low_value_title(title):
            continue
        pairs = sequence_lines_to_pairs(lines, labels)
        period, schedule = split_period_and_schedule(pairs.get("강의기간", ""))
        status = status_from_lines(lines)
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, target.url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "category": category,
                "raw_url": target.url,
                "application_url": target.url,
                "status": status,
                "fee": "",
                "period": period,
                "apply_period": pairs.get("접수기간", ""),
                "schedule_raw": schedule,
                "target": pairs.get("모집대상", ""),
                "capacity": pairs.get("모집인원", "") or pairs.get("접수현황", ""),
                "instructor": pairs.get("강사명", ""),
                "description": pairs.get("상세내용", "") or clean_text(item.get_text(" ", strip=True)),
                "raw_fields": {"pairs": pairs, "lines": lines, "parser": "ice_library_teach"},
            }
        )

    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": bool(soup.select(".pagination, .paging")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ice_library_teach", meta


def gbelib_branch_name(soup: BeautifulSoup, fallback: str) -> str:
    title = clean_text(soup.title.get_text(" ", strip=True) if soup.title else "")
    if ">" in title:
        candidate = clean_text(title.split(">", 1)[0])
        if candidate:
            return candidate
    og_title = soup.select_one("meta[property='og:title']")
    candidate = clean_text(og_title.get("content") if og_title else "")
    return candidate or fallback


def gbelib_footer_address(soup: BeautifulSoup) -> str:
    text = clean_text(soup.get_text(" ", strip=True))
    match = re.search(r"\(?\s*\d{5}\)?\s*([^전화팩스]+)", text)
    if match:
        return clean_text(match.group(1))
    match = re.search(r"경북\s+\S+\s+\S+\s+[^전화팩스]+", text)
    return clean_text(match.group(0)) if match else ""


def gbelib_item_pairs(item: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in item.select("li"):
        label_node = li.select_one("label")
        if not label_node:
            continue
        label = clean_text(label_node.get_text(" ", strip=True)).rstrip(":")
        value = clean_text(li.get_text(" ", strip=True))
        label_text = clean_text(label_node.get_text(" ", strip=True))
        value = clean_text(value.replace(label_text, "", 1)).lstrip(":").strip()
        if label:
            pairs[label] = value
    return pairs


def gbelib_teach_status(item: Any, pairs: dict[str, str]) -> str:
    action_text = clean_text(" ".join(a.get_text(" ", strip=True) for a in item.select("a.add, a.cancel, .stat a")))
    source = clean_text(" ".join([action_text, pairs.get("접수현황", "")]))
    if any(token in source for token in ("수강신청", "신청가능", "접수중")):
        return "접수중"
    if any(token in source for token in ("신청대기", "접수대기", "접수예정")):
        return "접수예정"
    if any(token in source for token in ("대기자", "대기신청")):
        return "대기접수"
    if any(token in source for token in ("마감", "신청완료")):
        return "마감"
    return status_from_lines([source]) or ""


def gbelib_teach_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    pairs = pairs_from_tables(soup)
    description = clean_text(pairs.get("강의 설명") or pairs.get("강의설명"))
    period = normalize_mixed_date_range(clean_text(pairs.get("강의기간(*)") or pairs.get("강의기간")))
    time_text = clean_text(pairs.get("강의시간"))
    day_text = clean_text(pairs.get("강의요일"))
    schedule = clean_text(f"{day_text} {time_text}") if day_text and time_text else time_text or day_text
    address = gbelib_footer_address(soup)
    return {
        "category": clean_text(pairs.get("교육과정")),
        "period": period,
        "schedule_raw": schedule,
        "apply_period": normalize_mixed_date_range(clean_text(pairs.get("접수일시") or pairs.get("접수기간"))),
        "target": clean_text(pairs.get("교육대상") or pairs.get("모집대상")),
        "fee": "무료",
        "venue_name": clean_text(pairs.get("강의장소")),
        "venue_address": address,
        "address": address,
        "instructor": clean_text(pairs.get("강사명")),
        "material_note": clean_text(pairs.get("준비물 및 재료비") or pairs.get("준비물")),
        "capacity": clean_text(pairs.get("현재 참여 / 모집") or pairs.get("모집정원")),
        "description": description,
        "raw_detail_pairs": pairs,
    }


def gbelib_teach_urls(s: requests.Session, target: CrawlTarget, timeout: int) -> list[str]:
    soup = fetch_soup(s, target.url, timeout=timeout)
    parsed = urlparse(target.url)
    prefix = parsed.path.split("/module/teach/", 1)[0]
    urls = [target.url]
    for link in soup.select("a[href*='/module/teach/index.do']"):
        href = link.get("href")
        if not href:
            continue
        absolute = normalize_link(target.url, href)
        parsed_link = urlparse(absolute)
        if parsed_link.netloc != parsed.netloc:
            continue
        if not parsed_link.path.startswith(prefix + "/module/teach/"):
            continue
        query = parse_qs(parsed_link.query)
        if not query.get("searchCate1"):
            continue
        urls.append(absolute)
    return list(dict.fromkeys(urls))


def collect_gbelib_library_teach(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    pages = 0
    pagination_detected = False
    discovered_urls = gbelib_teach_urls(s, target, timeout)
    page_limit = max(1, max_pages)

    for list_url in discovered_urls:
        parsed = urlparse(list_url)
        query = parse_qs(parsed.query)
        menu_idx = clean_text((query.get("menu_idx") or [""])[0])
        search_cate = clean_text((query.get("searchCate1") or [""])[0])
        search_age = clean_text((query.get("searchAge") or [""])[0])
        base_query = {key: values[-1] for key, values in query.items() if values}

        for page in range(1, page_limit + 1):
            page_query = dict(base_query)
            page_query["viewPage"] = str(page)
            page_url = parsed._replace(query=urlencode(page_query)).geturl()
            soup = fetch_soup(s, page_url, timeout=timeout)
            pages += 1
            branch = gbelib_branch_name(soup, target.branch)
            address = gbelib_footer_address(soup)
            page_rows: list[dict[str, Any]] = []

            for item in soup.select("#list_mode .item, .item"):
                title_node = item.select_one("a.detail-btn:not(.btn), .op_title a.name")
                title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
                if not title or title == "?곸꽭蹂닿린" or is_low_value_title(title):
                    continue
                detail_node = item.select_one("a.detail-btn")
                group_idx = clean_text(detail_node.get("keyvalue1") if detail_node else "")
                category_idx = clean_text(detail_node.get("keyvalue2") if detail_node else "")
                teach_idx = clean_text(detail_node.get("keyvalue3") if detail_node else "")
                large_category_idx = clean_text(detail_node.get("keyvalue4") if detail_node else search_cate)
                category = clean_text((item.select_one(".ca") or {}).get_text(" ", strip=True) if item.select_one(".ca") else "")
                pairs = gbelib_item_pairs(item)
                detail_url = ""
                if teach_idx:
                    detail_params = {
                        "group_idx": group_idx,
                        "category_idx": category_idx,
                        "teach_idx": teach_idx,
                        "large_category_idx": large_category_idx,
                        "menu_idx": menu_idx,
                        "searchCate1": search_cate,
                    }
                    if search_age:
                        detail_params["searchAge"] = search_age
                    detail_url = urljoin(list_url, f"{parsed.path.rsplit('/', 1)[0]}/detail.do?{urlencode(detail_params)}")
                row = {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, teach_idx or list_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "branch_code": parsed.path.split("/", 2)[1] if parsed.path.startswith("/") else branch,
                    "preserve_branch": True,
                    "category": category,
                    "raw_url": detail_url or page_url,
                    "application_url": detail_url or page_url,
                    "status": gbelib_teach_status(item, pairs),
                    "fee": "",
                    "period": normalize_mixed_date_range(pairs.get("수강기간", "")),
                    "apply_period": normalize_mixed_date_range(pairs.get("접수일시", "") or pairs.get("접수기간", "")),
                    "schedule_raw": clean_text(pairs.get("요일/시간", "")),
                    "target": clean_text(pairs.get("교육대상", "")),
                    "venue_name": clean_text(pairs.get("장소", "")),
                    "venue_address": address,
                    "address": address,
                    "capacity": clean_text(pairs.get("모집인원", "") or pairs.get("접수현황", "")),
                    "instructor": clean_text(pairs.get("\uAC15\uC0AC\uBA85")),
                    "material_note": clean_text(pairs.get("준비물 및 재료비", "") or pairs.get("준비물", "")),
                    "description": clean_text(item.get_text(" ", strip=True)),
                    "raw_fields": {
                        "parser": "gbelib_library_teach",
                        "list_url": list_url,
                        "pairs": pairs,
                        "menu_idx": menu_idx,
                        "searchCate1": search_cate,
                    },
                }
                if detail_url and detail_pages < detail_limit:
                    try:
                        row = merge_course_rows(row, gbelib_teach_detail_fields(s, detail_url, timeout))
                        detail_pages += 1
                    except Exception as exc:
                        logger.debug("gbelib detail fetch failed %s: %s", detail_url, exc)
                page_rows.append(row)

            rows.extend(page_rows)
            pagination_detected = pagination_detected or bool(soup.select(".paginate, .paging, .pagination, a[href*='viewPage=']"))
            if not page_rows:
                break
            if len(page_rows) < 10:
                break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(discovered_urls),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "gbelib_library_teach", meta


