def normalize_uljin_korean_date_range(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    full_matches = re.findall(
        r"(\d{4})\s*년\s*(\d{1,2})\s*월\s*(\d{1,2})\s*일(?:\s*(\d{1,2})\s*시\s*(\d{1,2})\s*분?)?",
        text,
    )
    if full_matches:
        def fmt_full(match: tuple[str, str, str, str, str]) -> str:
            year, month, day, hour, minute = match
            date_part = f"{int(year):04d}-{int(month):02d}-{int(day):02d}"
            return f"{date_part} {int(hour):02d}:{int(minute):02d}" if hour and minute else date_part

        start = fmt_full(full_matches[0])
        end = fmt_full(full_matches[-1])
        return f"{start} ~ {end}" if start != end else start
    ymd_matches = re.findall(r"(\d{4})[./-](\d{1,2})[./-](\d{1,2})(?:\s+(\d{1,2}):(\d{2}))?", text)
    if ymd_matches:
        def fmt_ymd(match: tuple[str, str, str, str, str]) -> str:
            year, month, day, hour, minute = match
            date_part = f"{int(year):04d}-{int(month):02d}-{int(day):02d}"
            return f"{date_part} {int(hour):02d}:{minute}" if hour and minute else date_part

        start = fmt_ymd(ymd_matches[0])
        end = fmt_ymd(ymd_matches[-1])
        return f"{start} ~ {end}" if start != end else start
    return normalize_month_day_range(text)


def normalize_uljin_schedule(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    text = re.sub(r"\b매주\b", "", text)
    text = re.sub(r"\s+", " ", text)
    match = re.search(
        r"([월화수목금토일](?:\s*[,ㆍ~]\s*[월화수목금토일])*)\s*(?:요일)?\s*\(?\s*(\d{1,2}:\d{2})\s*[~-]\s*(\d{1,2}:\d{2})\s*\)?",
        text,
    )
    if match:
        return clean_text(f"{match.group(1)} {match.group(2)} ~ {match.group(3)}")
    return text


def split_uljin_library_title(value: Any) -> tuple[str, str]:
    text = clean_text(value)
    if not text:
        return "", ""
    text = re.sub(r"^\[\]\s*", "", text)
    bracket = re.match(r"^\[([^\]]+)\]\s*(.+)$", text)
    if bracket:
        return clean_text(bracket.group(1)), clean_text(bracket.group(2))
    for branch in ULJIN_LIBRARY_BRANCHES:
        if text.startswith(branch):
            return branch, clean_text(text[len(branch) :])
    return "", text


def uljin_text_with_image_alts(node: BeautifulSoup | None) -> str:
    if not node:
        return ""
    parts: list[str] = []
    text = clean_text(node.get_text(" ", strip=True))
    if text:
        parts.append(text)
    for image in node.find_all("img"):
        alt = clean_text(image.get("alt"))
        if alt:
            parts.append(alt)
    return clean_text(" ".join(parts))


def parse_uljin_library_detail(s: requests.Session, detail_url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    box = soup.select_one("#edusatbox")
    if not box:
        return {}
    title_text = clean_text((box.select_one(".tit") or "").get_text(" ", strip=True))
    branch, title = split_uljin_library_title(title_text)
    pairs = pairs_from_definition_lists(box)
    pairs.update({key: value for key, value in pairs_from_tables(box).items() if value})
    editor = box.select_one(".webeditor")
    image = (editor.find("img") if editor else None) or box.find("img")
    image_url = normalize_link(detail_url, image.get("src")) if image and image.get("src") else ""
    fee_text = clean_text(pairs.get("수강료"))
    material_fee_text = clean_text(pairs.get("교재비") or pairs.get("재료비"))
    if "재료비" in fee_text:
        material_fee_text = material_fee_text or fee_text
        if "무료" in fee_text or fee_text.startswith("재료비"):
            fee_text = "무료"
    period = normalize_uljin_korean_date_range(pairs.get("강의기간") or pairs.get("행사기간"))
    schedule = normalize_uljin_schedule(pairs.get("강의일시") or pairs.get("행사일시")) or period
    return {
        "title": title,
        "branch": branch or "울진군통합도서관",
        "target": clean_text(pairs.get("교육대상") or pairs.get("참가대상") or pairs.get("대상")),
        "capacity": clean_text(pairs.get("모집인원")),
        "fee": fee_text or "무료",
        "material_fee": material_fee_text,
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "instructor": clean_text(pairs.get("강사명")),
        "status": clean_text(pairs.get("상태") or pairs.get("접수상태")),
        "apply_period": normalize_uljin_korean_date_range(pairs.get("접수기간")),
        "period": period,
        "schedule_raw": schedule,
        "room": clean_text(pairs.get("강의실") or pairs.get("행사장소")),
        "venue_name": clean_text(pairs.get("행사장소")),
        "description": clean_text(pairs.get("행사설명")) or uljin_text_with_image_alts(editor),
        "image_url": image_url,
        "raw_fields": {"pairs": pairs, "parser": "uljin_library_edusat"},
    }


def collect_uljin_library_programs(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    discovered_links = 0
    seen_list_urls: set[str] = set()

    start_soup = fetch_soup(s, target.url, timeout=timeout)
    pages += 1
    list_urls: list[str] = []
    for link in start_soup.find_all("a", href=True):
        label = clean_text(link.get_text(" ", strip=True))
        href = link.get("href")
        if "sh_edu_lib=" in href and label in ULJIN_LIBRARY_BRANCHES:
            list_url = normalize_link(target.url, href)
            if list_url and list_url not in seen_list_urls:
                seen_list_urls.add(list_url)
                list_urls.append(list_url)
    canonical_course_url = normalize_link(
        target.url,
        f"/content/edusat/list.php?sh_edu_lib={quote('울진남부도서관')}",
    )
    if canonical_course_url and canonical_course_url not in seen_list_urls:
        seen_list_urls.add(canonical_course_url)
        list_urls.append(canonical_course_url)
    if target.url not in seen_list_urls:
        seen_list_urls.add(target.url)
        list_urls.insert(0, target.url)
    for extra_path in ("/content/edusat3/list.php", "/content/edusat4/list.php"):
        extra_url = normalize_link(target.url, extra_path)
        if extra_url and extra_url not in seen_list_urls:
            seen_list_urls.add(extra_url)
            list_urls.append(extra_url)

    for list_url in list_urls[: max(1, max_pages)]:
        soup = start_soup if list_url == target.url else fetch_soup(s, list_url, timeout=timeout)
        if list_url != target.url:
            pages += 1
        table = soup.select_one("table.edutable2") or soup.select_one("table")
        if not table:
            continue
        for tr in table.select("tbody tr"):
            cells = [cell for cell in tr.find_all("td")]
            if len(cells) < 2:
                continue
            row_text = clean_text(tr.get_text(" ", strip=True))
            if not row_text or "寃?됰맂" in row_text:
                continue
            title_link = next((a for a in cells[0].find_all("a", href=True) if "view.php" in a.get("href", "")), None)
            raw_title = clean_text(title_link.get_text(" ", strip=True) if title_link else cells[0].get_text(" ", strip=True))
            branch_from_title, clean_title = split_uljin_library_title(raw_title)
            if not clean_title or is_low_value_title(clean_title):
                continue
            raw_url = normalize_link(list_url, title_link.get("href")) if title_link else list_url
            method_parts = [
                clean_text(image.get("alt"))
                for image in (cells[2].find_all("img") if len(cells) > 2 else [])
                if clean_text(image.get("alt"))
            ]
            row: dict[str, Any] = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, clean_title, branch_from_title),
                "title": clean_title,
                "branch": branch_from_title or (target.branch if "?" not in clean_text(target.branch) else "울진군통합도서관") or "울진군통합도서관",
                "category": "도서관",
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": clean_text(cells[-1].get_text(" ", strip=True)),
                "fee": "",
                "period": "",
                "apply_period": normalize_month_day_range(cells[1].get_text(" ", strip=True)) if len(cells) > 1 else "",
                "schedule_raw": "",
                "target": "",
                "capacity": clean_text(cells[3].get_text(" ", strip=True)) if len(cells) > 3 else "",
                "application_method_raw": ", ".join(method_parts),
                "description": "",
                "raw_fields": {"list_url": list_url, "list_text": row_text, "parser": "uljin_library_edusat"},
            }
            if raw_url:
                try:
                    detail = parse_uljin_library_detail(s, raw_url, timeout)
                    detail_pages += 1
                    for key, value in detail.items():
                        if key == "raw_fields":
                            merged = dict(row.get("raw_fields") or {})
                            merged.update(value)
                            row[key] = merged
                        elif value:
                            row[key] = value
                except Exception as exc:
                    logger.debug("Uljin library detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
        discovered_links += len(table.find_all("a", href=True))

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": discovered_links,
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "uljin_library_edusat", meta


def text_with_image_alts(node: Any) -> str:
    if not node:
        return ""
    clone = BeautifulSoup(str(node), "lxml")
    for image in clone.find_all("img"):
        alt = clean_text(image.get("alt"))
        if alt:
            image.replace_with(f" {alt} ")
    return clean_text(clone.get_text(" ", strip=True))


def gne_library_list_url(target_url: str, soup: BeautifulSoup) -> str:
    parsed = urlparse(target_url)
    if parsed.path.endswith("/usr_gne/lec_list.es"):
        return target_url
    preferred_tokens = (
        "\ud3c9\uc0dd\ud559\uc2b5\uc218\uac15\uc2e0\uccad",
        "\ud604\ud669 \ubc0f \uc2e0\uccad",
        "\uc628\ub77c\uc778\uac15\uc88c\uc2e0\uccad",
        "\uc218\uac15\uc2e0\uccad",
    )
    for link in soup.find_all("a", href=True):
        text = clean_text(link.get_text(" ", strip=True))
        href = normalize_link(target_url, link.get("href"))
        if not href:
            continue
        if any(token in text for token in preferred_tokens):
            return href
    return target_url


def gne_clean_title(value: str) -> str:
    title = clean_text(value)
    title = re.sub(r"\[(?:\uc77c\ud68c\uc131\ud2b9\uac15|\ubb34\ub8cc|\uc720\ub8cc)\]", " ", title)
    title = re.sub(r"\s+", " ", title)
    return clean_text(title)


def gne_extract_after_label(text: str, label: str, stop_labels: tuple[str, ...]) -> str:
    text = clean_text(text)
    if not text:
        return ""
    label_core = label.lstrip("\u318d")
    stop_pattern = "|".join(r"\u318d?\s*" + re.escape(stop.lstrip("\u318d")) + r"\s*:" for stop in stop_labels if stop != label)
    pattern = r"\u318d?\s*" + re.escape(label_core) + r"\s*:\s*(.*?)(?=" + stop_pattern + r"|$)"
    match = re.search(pattern, text)
    return clean_text(match.group(1)) if match else ""


def gne_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    labels = {
        "\uac15\uc88c\uba85",
        "\uad50\uc721\ub300\uc0c1",
        "\uc9c4\ud589\uc0c1\ud0dc",
        "\uac15\uc0ac",
        "\ucd08\ube59\uac15\uc0ac",
        "\ub2f4\ub2f9\uc790\uba85",
        "\ub2f4\ub2f9\uc790 \uc5f0\ub77d\ucc98",
        "\ubaa8\uc9d1\uae30\uac04",
        "\uad50\uc721\uae30\uac04",
        "\uc811\uc218\ubc29\ubc95",
        "\uad50\uc721\uc77c\uc2dc",
        "\ubaa8\uc9d1\uc778\uc6d0",
        "\uc628\ub77c\uc778\uc811\uc218",
        "\ud6c4\ubcf4",
        "\uac15\uc758\uc7a5\uc18c",
        "\uc7ac\ub8cc\ube44",
        "\uc218\uac15\ub8cc",
        "\uac15\uc758\uc18c\uac1c",
    }
    pairs: dict[str, str] = {}
    for row in soup.select("table.tstyle_view tr"):
        cells = row.find_all(["th", "td"])
        index = 0
        while index + 1 < len(cells):
            key = clean_text(text_with_image_alts(cells[index])).lstrip("*").replace("\n", " ")
            value = text_with_image_alts(cells[index + 1])
            if key in labels and value:
                pairs[key] = value
                index += 2
            else:
                index += 1
    return pairs


def collect_gne_library_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    start_soup = fetch_soup(s, target.url, timeout=timeout)
    list_url = gne_library_list_url(target.url, start_soup)
    if list_url != target.url:
        list_soup = fetch_soup(s, list_url, timeout=timeout)
        list_url = getattr(list_soup, "_feed", None) and list_url or list_url
    else:
        list_soup = start_soup
    if not urlparse(list_url).path.endswith("/usr_gne/lec_list.es") and urlparse(list_url).path.endswith("/menu.es"):
        response = s.get(list_url, timeout=timeout, verify=False)
        response.raise_for_status()
        list_url = response.url
        list_soup = BeautifulSoup(response.text, "lxml")

    parsed = urlparse(list_url)
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    stop_labels = ("\ubaa8\uc9d1\uae30\uac04", "\ud559\uc2b5\uae30\uac04", "\uad50\uc721\uc694\uc77c/\uc2dc\uac04")

    for page in range(1, max_pages + 1):
        query = parse_qs(parsed.query)
        query["page"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = list_soup if page == 1 else fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table.tstyle_list tbody tr"):
            cells = tr.find_all("td", recursive=False)
            if len(cells) < 6:
                continue
            category = clean_text(cells[0].get_text(" ", strip=True))
            title_cell = cells[1]
            link = title_cell.find("a", href=True)
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            title_text = text_with_image_alts(title_cell)
            title_text = re.split(r"\s*\u318d\ubaa8\uc9d1\uae30\uac04\s*:", title_text, maxsplit=1)[0]
            title = gne_clean_title(title_text)
            if not title or is_low_value_title(title):
                continue
            detail_text = text_with_image_alts(title_cell)
            apply_period = gne_extract_after_label(detail_text, "\u318d\ubaa8\uc9d1\uae30\uac04", stop_labels)
            period = gne_extract_after_label(detail_text, "\u318d\ud559\uc2b5\uae30\uac04", stop_labels)
            schedule = gne_extract_after_label(detail_text, "\u318d\uad50\uc721\uc694\uc77c/\uc2dc\uac04", stop_labels)
            status = ""
            status_image = cells[5].find("img")
            if status_image:
                status = clean_text(status_image.get("alt"))
            if not status:
                status = clean_text(cells[5].get_text(" ", strip=True)).replace("\uc0c1\uc138\ubcf4\uae30", "")
            method = ", ".join(
                clean_text(image.get("alt"))
                for image in cells[4].find_all("img")
                if clean_text(image.get("alt"))
            )
            fee = "\ubb34\ub8cc" if "\ubb34\ub8cc" in text_with_image_alts(title_cell) else ""
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url if status and "\ubaa8\uc9d1" in status else "",
                "status": status,
                "fee": fee,
                "period": period,
                "apply_period": apply_period,
                "schedule_raw": schedule,
                "target": "",
                "capacity": text_with_image_alts(cells[3]),
                "application_method_raw": method,
                "description": "",
                "raw_fields": {"parser": "gne_library_lec_list", "list_text": detail_text},
            }
            if detail_pages < detail_limit and raw_url:
                try:
                    s.headers.update({"Referer": current_url})
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    pairs = gne_detail_pairs(detail_soup)
                    detail = {
                        "title": gne_clean_title(pairs.get("\uac15\uc88c\uba85", "")),
                        "target": pairs.get("\uad50\uc721\ub300\uc0c1", ""),
                        "status": pairs.get("\uc9c4\ud589\uc0c1\ud0dc", ""),
                        "instructor": pairs.get("\ucd08\ube59\uac15\uc0ac") or pairs.get("\uac15\uc0ac", ""),
                        "apply_period": pairs.get("\ubaa8\uc9d1\uae30\uac04", ""),
                        "period": pairs.get("\uad50\uc721\uae30\uac04", ""),
                        "schedule_raw": pairs.get("\uad50\uc721\uc77c\uc2dc", ""),
                        "capacity": pairs.get("\ubaa8\uc9d1\uc778\uc6d0", "") or row["capacity"],
                        "venue_name": pairs.get("\uac15\uc758\uc7a5\uc18c", ""),
                        "material_fee": pairs.get("\uc7ac\ub8cc\ube44", ""),
                        "fee": pairs.get("\uc218\uac15\ub8cc", ""),
                        "description": pairs.get("\uac15\uc758\uc18c\uac1c", ""),
                        "raw_detail_pairs": pairs,
                    }
                    row = merge_course_rows(row, detail)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("gne detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": bool(rows) and pages >= max_pages,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "gne_library_lec_list", meta


def jne_branch_from_title(soup: BeautifulSoup, fallback: str) -> str:
    title = clean_text(soup.title.get_text(" ", strip=True)) if soup.title else ""
    if ":" in title:
        branch = clean_text(title.rsplit(":", 1)[-1])
        if branch:
            return branch
    return fallback


def collect_jne_library_lecture(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    branch = target.branch

    for page in range(1, max_pages + 1):
        query = parse_qs(parsed.query)
        query["nPage"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        if page == 1:
            branch = jne_branch_from_title(soup, target.branch)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["td", "th"])]
            if len(cells) < 7 or cells[0] in {"?곕쾲", ""} or not re.fullmatch(r"\d+", cells[0] or ""):
                continue
            link = tr.find("a", href=True)
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            offset = 1 if len(cells) >= 8 and not cells[1] else 0
            title = cells[1 + offset]
            target_text = cells[2 + offset] if len(cells) > 2 + offset else ""
            raw_period = cells[3 + offset] if len(cells) > 3 + offset else ""
            apply_period = cells[4 + offset] if len(cells) > 4 + offset else ""
            capacity = cells[5 + offset] if len(cells) > 5 + offset else ""
            status = cells[6 + offset] if len(cells) > 6 + offset else ""
            period, schedule = split_period_and_schedule(raw_period)
            capacity_current, capacity_total = parse_capacity_pair(capacity)
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "category": "\ub3c4\uc11c\uad00",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": "\ubb34\ub8cc",
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule or raw_period,
                    "target": target_text,
                    "capacity_current": capacity_current,
                    "capacity_total": capacity_total,
                    "description": clean_text(" ".join(cells[1 + offset : 7 + offset])),
                    "raw_fields": {"cells": cells, "parser": "jne_library_lecture_table"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='nPage=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "jne_library_lecture_table", meta


def collect_jne_library_education(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    branch = target.branch

    for page in range(1, max_pages + 1):
        query = parse_qs(parsed.query)
        query["nPage"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        if page == 1:
            branch = jne_branch_from_title(soup, target.branch)
        pages += 1
        page_rows = 0

        for tr in soup.select("table tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["td", "th"])]
            if len(cells) < 6 or not re.fullmatch(r"\d+", cells[0] or ""):
                continue
            link = tr.find("a", href=True)
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            title = cells[1]
            apply_period = cells[2]
            period = cells[3]
            capacity = cells[4]
            status = cells[5]
            capacity_current, capacity_total = parse_capacity_pair(capacity)
            wait_current = None
            wait_total = None
            wait_match = re.search(r"\(\s*(\d{1,5})\s*/\s*(\d{1,5})\s*\)", capacity.replace(",", ""))
            if wait_match:
                wait_current = int(wait_match.group(1))
                wait_total = int(wait_match.group(2))

            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "category": "\ub3c5\uc11c\ubb38\ud654\ud589\uc0ac",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": "\ubb34\ub8cc",
                    "period": period,
                    "apply_period": apply_period,
                    "capacity_current": capacity_current,
                    "capacity_total": capacity_total,
                    "waitlist_current": wait_current,
                    "waitlist_total": wait_total,
                    "description": clean_text(" ".join(cells[1:6])),
                    "raw_fields": {"cells": cells, "parser": "jne_library_education_table"},
                }
            )
            page_rows += 1

        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='nPage=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "jne_library_education_table", meta


def chuncheon_e_types(url: str) -> list[str]:
    query = parse_qs(urlparse(url).query)
    e_type = clean_text((query.get("e_type") or [""])[0])
    return [e_type] if e_type else ["jung", "dan", "etc"]


def post_soup(s: requests.Session, url: str, data: dict[str, Any], timeout: int) -> BeautifulSoup:
    response = s.post(url, data=data, timeout=timeout, verify=False)
    response.raise_for_status()
    if not response.encoding or response.encoding.lower() == "iso-8859-1":
        response.encoding = response.apparent_encoding
    return BeautifulSoup(response.text, "lxml")


def collect_chuncheon_lifelong(target: CrawlTarget, timeout: int, max_pages: int, detail_limit: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    root_url = "https://clc.chuncheon.go.kr"
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    for e_type in chuncheon_e_types(target.url):
        gisu_url = f"{root_url}/site/edu/edu_gisu_list.do?e_type={e_type}"
        soup = fetch_soup(s, gisu_url, timeout=timeout)
        pages += 1
        gisu_rows: list[dict[str, str]] = []
        for tr in soup.select("table.tbl_bbs tbody tr"):
            cells = tr.find_all("td", recursive=False)
            if len(cells) < 4:
                continue
            link = cells[0].find("a")
            onclick = clean_text(link.get("onclick") if link else "")
            match = re.search(r"fn_classList\('([^']+)'\)", onclick)
            gisu_id = match.group(1) if match else ""
            if not gisu_id:
                continue
            gisu_rows.append(
                {
                    "gisu_id": gisu_id,
                    "gisu_name": clean_text(cells[0].get_text(" ", strip=True)),
                    "apply_period": text_with_image_alts(cells[1]),
                    "period": text_with_image_alts(cells[2]),
                    "status": text_with_image_alts(cells[3]),
                }
            )
        for gisu in gisu_rows[:max_pages]:
            list_soup = post_soup(
                s,
                f"{root_url}/site/edu/edu_class_list.do",
                {"e_type": e_type, "yy": gisu["gisu_id"]},
                timeout,
            )
            pages += 1
            for tr in list_soup.select("table.tbl_bbs tbody tr"):
                cells = tr.find_all("td", recursive=False)
                if len(cells) < 6:
                    continue
                title_link = cells[1].find("a")
                title = clean_text(title_link.get_text(" ", strip=True) if title_link else cells[1].get_text(" ", strip=True))
                if not title or is_low_value_title(title):
                    continue
                onclick = clean_text(title_link.get("onclick") if title_link else "")
                match = re.search(r"fn_classView\('([^']+)'\)", onclick)
                class_no = match.group(1) if match else stable_course_id(target.provider, gisu["gisu_id"], title, target.branch)
                raw_url = f"{root_url}/site/edu/edu_class_view.do?e_type={e_type}&yy={gisu['gisu_id']}&class_no={class_no}"
                method = clean_text((cells[1].select_one(".label") or {}).get_text(" ", strip=True) if cells[1].select_one(".label") else "")
                row = {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, f"{gisu['gisu_id']}:{class_no}", title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "category": clean_text(cells[0].get_text(" ", strip=True)),
                    "raw_url": raw_url,
                    "application_url": raw_url if "\uc2e0\uccad" in text_with_image_alts(cells[5]) and "\ub9c8\uac10" not in text_with_image_alts(cells[5]) else "",
                    "status": text_with_image_alts(cells[5]),
                    "fee": "",
                    "period": gisu["period"],
                    "apply_period": gisu["apply_period"],
                    "schedule_raw": text_with_image_alts(cells[2]),
                    "target": text_with_image_alts(cells[3]),
                    "capacity": text_with_image_alts(cells[4]),
                    "application_method_raw": method,
                    "description": "",
                    "raw_fields": {"parser": "chuncheon_lifelong", "e_type": e_type, "gisu": gisu, "class_no": class_no},
                }
                if detail_pages < detail_limit and class_no:
                    try:
                        detail_soup = post_soup(
                            s,
                            f"{root_url}/site/edu/edu_class_view.do",
                            {"e_type": e_type, "yy": gisu["gisu_id"], "class_no": class_no},
                            timeout,
                        )
                        pairs = pairs_from_tables(detail_soup)
                        detail = {
                            "category": pairs.get("\ubd84\uc57c", ""),
                            "application_method_raw": pairs.get("\uad50\uc721\ubc29\ubc95", "") or row["application_method_raw"],
                            "title": pairs.get("\uac15\uc88c\uba85", ""),
                            "capacity": pairs.get("\uc811\uc218\ud604\ud669", "") or row["capacity"],
                            "target": pairs.get("\ub300\uc0c1\uc790", "") or row["target"],
                            "apply_period": pairs.get("\uc811\uc218\uae30\uac04", "") or row["apply_period"],
                            "period": pairs.get("\uad50\uc721\uae30\uac04", "") or row["period"],
                            "schedule_raw": pairs.get("\uad50\uc721\uc2dc\uac04", "") or row["schedule_raw"],
                            "fee": pairs.get("\uc218\uac15\ub8cc", ""),
                            "material_fee": pairs.get("\uc7ac\ub8cc\ube44", ""),
                            "instructor": pairs.get("\uac15\uc0ac\uba85", ""),
                            "description": pairs.get("\uad50\uc721\ub0b4\uc6a9", ""),
                            "raw_detail_pairs": pairs,
                        }
                        row = merge_course_rows(row, detail)
                        detail_pages += 1
                    except Exception as exc:
                        logger.debug("chuncheon detail fetch failed %s: %s", raw_url, exc)
                rows.append(row)

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "chuncheon_lifelong", meta


def collect_suseong_learningtalk(target: CrawlTarget, timeout: int, max_pages: int, detail_limit: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    detail_urls: list[str] = []
    if "/front/education/details.do" in target.url:
        detail_urls.append(target.url)
    for link in soup.find_all("a", href=True):
        href = normalize_link(target.url, link.get("href"))
        if href and "/front/education/details.do" in href and href not in detail_urls:
            detail_urls.append(href)
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    for raw_url in detail_urls[: max(max_pages * 5, detail_limit, 1)]:
        try:
            detail_soup = soup if raw_url == target.url else fetch_soup(s, raw_url, timeout=timeout)
            pairs = pairs_from_tables(detail_soup)
            title = clean_text(pairs.get("\uac15\uc88c\uba85"))
            if not title or is_low_value_title(title):
                continue
            branch = clean_text(pairs.get("\uad50\uc721\uae30\uad00")) or target.branch
            status = clean_text(pairs.get("\uc2e0\uccad\uc0c1\ud0dc") or pairs.get("\uc624\ud504\ub77c\uc778\ubaa8\uc9d1\uc0c1\ud0dc"))
            method = clean_text(pairs.get("\uc811\uc218\ubc29\ubc95"))
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "category": clean_text(" > ".join(part for part in [pairs.get("\uac15\uc88c\ubd84\ub958"), pairs.get("\ub0b4\uc6a9\ubd84\ub958"), pairs.get("\ub0b4\uc6a9\ubcc4 \ubd84\ub958")] if clean_text(part))),
                "raw_url": raw_url,
                "application_url": raw_url if "\uc2e0\uccad\uc911" in status else "",
                "status": status,
                "fee": pairs.get("\uc218\uac15\ub8cc", ""),
                "material_fee": pairs.get("\uc7ac\ub8cc\ube44", ""),
                "period": pairs.get("\uad50\uc721\uae30\uac04", ""),
                "apply_period": pairs.get("\uc2e0\uccad\uae30\uac04", ""),
                "schedule_raw": pairs.get("\uad50\uc721\uc2dc\uac04", ""),
                "target": pairs.get("\uad50\uc721\ub300\uc0c1", ""),
                "capacity": pairs.get("\ubaa8\uc9d1\uc778\uc6d0", ""),
                "venue_name": pairs.get("\uad50\uc721\uc7a5\uc18c", ""),
                "venue_address": pairs.get("\uc8fc\uc18c", ""),
                "instructor": pairs.get("\uac15\uc0ac", ""),
                "application_method_raw": method,
                "description": pairs.get("\uac15\uc88c\uc18c\uac1c", ""),
                "raw_fields": {"parser": "suseong_learningtalk", "pairs": pairs},
            }
            rows.append(row)
            detail_pages += 1
        except Exception as exc:
            logger.debug("suseong detail fetch failed %s: %s", raw_url, exc)
        if detail_pages >= detail_limit and "/front/education/details.do" not in target.url:
            break

    meta = {
        "pages": 1,
        "detail_pages": detail_pages,
        "discovered_links": len(detail_urls),
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "suseong_learningtalk", meta


def extract_jongno_edu_target(description: Any) -> str:
    text = clean_text(description)
    if not text:
        return ""
    match = re.search(r"(\d{1,3}\s*(?:세\s*이상|개월\s*이상|이상)\s*(?:구민|성인|어린이|주민)?)", text)
    if match:
        return clean_text(match.group(1))
    match = re.search(r"(?:대상|교육대상|모집대상)\s*[:：]?\s*([^.\n]+)", text)
    return clean_text(match.group(1)) if match else ""


def normalize_jongno_detail_period(value: Any) -> tuple[str, str]:
    text = clean_text(value).replace("∼", "~").replace("～", "~").replace("-", "~")
    dotted = re.search(
        r"(\d{1,2})[.]\s*(\d{1,2})\s*~\s*(\d{1,2})[.]\s*(\d{1,2})(.*)",
        text,
    )
    if dotted:
        year = datetime.now().year
        period = (
            f"{year}-{int(dotted.group(1)):02d}-{int(dotted.group(2)):02d}"
            f" ~ {year}-{int(dotted.group(3)):02d}-{int(dotted.group(4)):02d}"
        )
        return period, clean_text(dotted.group(5))
    normalized = normalize_korean_month_day_range(text)
    return split_period_and_schedule(normalized)


def collect_jongno_edu_apply(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        if page > 1:
            query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
            if len(cells) < 7 or not cells[0].isdigit():
                continue
            title = cells[2]
            if not title or is_low_value_title(title):
                continue
            period_text, schedule = split_period_and_schedule(normalize_korean_month_day_range(cells[4]))
            if not schedule:
                schedule_match = re.search(r"([?뷀솕?섎ぉ湲덊넗??]+\s*\d{1,2}:\d{2}\s*~\s*\d{1,2}:\d{2})", cells[4])
                schedule = clean_text(schedule_match.group(1)) if schedule_match else ""
            apply_period = normalize_korean_month_day_range(cells[3])
            form = tr.find("form")
            form_values = {
                clean_text(input_node.get("name")): clean_text(input_node.get("value"))
                for input_node in form.select("input")
                if clean_text(input_node.get("name"))
            } if form else {}
            edu_open_cd = form_values.get("edu_open_cd") or cells[0]
            raw_url = urljoin(current_url, f"eduApplyview.do?edu_open_cd={edu_open_cd}")

            detail_pairs: dict[str, str] = {}
            if edu_open_cd:
                try:
                    response = s.post(
                        urljoin(current_url, "eduApplyview.do"),
                        data={"edu_open_cd": edu_open_cd, "pageIndex": str(page)},
                        timeout=timeout,
                    )
                    response.raise_for_status()
                    if not response.encoding or response.encoding.lower() == "iso-8859-1":
                        response.encoding = response.apparent_encoding
                    detail_pairs = pairs_from_tables(BeautifulSoup(response.text, "lxml"))
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("jongno edu detail fetch failed %s: %s", edu_open_cd, exc)

            detail_period, detail_schedule = normalize_jongno_detail_period(detail_pairs.get("교육기간"))
            detail_apply_period = normalize_mixed_date_range(detail_pairs.get("접수기간"))
            if detail_apply_period == "~":
                detail_apply_period = ""
            capacity_current, capacity_total = parse_capacity_pair(detail_pairs.get("정원") or cells[5])
            if capacity_current is None or capacity_total is None:
                list_current, list_total = parse_capacity_pair(cells[5])
                capacity_current = capacity_current if capacity_current is not None else list_current
                capacity_total = capacity_total if capacity_total is not None else list_total
            description = detail_pairs.get("내용") or clean_text(tr.get_text(" ", strip=True))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, detail_pairs.get("교육장소") or cells[1]),
                    "title": title,
                    "branch": detail_pairs.get("교육장소") or cells[1],
                    "category": "구민정보화교육",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": detail_pairs.get("상태") or cells[6],
                    "fee": detail_pairs.get("수강료") or "무료",
                    "material_fee": detail_pairs.get("교재비"),
                    "period": detail_period or period_text,
                    "apply_period": detail_apply_period or apply_period,
                    "schedule_raw": detail_schedule or schedule,
                    "target": extract_jongno_edu_target(description),
                    "capacity": detail_pairs.get("정원") or cells[5],
                    "capacity_current": capacity_current,
                    "capacity_total": capacity_total,
                    "venue_name": detail_pairs.get("교육장소") or cells[1],
                    "phone": detail_pairs.get("교육문의"),
                    "description": description,
                    "raw_fields": {"cells": cells, "detail_pairs": detail_pairs, "parser": "jongno_edu_apply"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "jongno_edu_apply", meta


def jongno_reserv_status(value: str) -> str:
    text = clean_text(value)
    if "접수중" in text:
        return "접수중"
    if "준비" in text or "예정" in text:
        return "접수예정"
    if "마감" in text or "종료" in text:
        return "접수마감"
    return normalize_status(text) or text


def jongno_reserv_card_pairs(card: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not hasattr(card, "select"):
        return pairs
    for dl in card.select(".bot-area dl"):
        key = clean_text(dl.select_one("dt").get_text(" ", strip=True) if dl.select_one("dt") else "")
        key = re.sub(r"\s+", "", key).rstrip(":：")
        value = clean_text(dl.select_one("dd").get_text(" ", strip=True) if dl.select_one("dd") else "")
        if key and value:
            pairs[key] = value
    return pairs


def jongno_reserv_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    title_node = soup.select_one(".tit-area h3, .view-title, h3.vw-tit2, #container h3")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    pairs = pairs_from_definition_lists(soup)
    period = normalize_mixed_date_range(pairs.get("교육기간", ""))
    apply_period = normalize_mixed_date_range(pairs.get("신청기간", ""))
    weekday = clean_text(pairs.get("요일"))
    edu_time = clean_text(pairs.get("교육시간"))
    schedule = clean_text(" ".join(part for part in [weekday, edu_time] if part))
    capacity_total = parse_capacity_number(pairs.get("모집인원"))
    return {
        "title": title,
        "status": jongno_reserv_status(pairs.get("진행상태", "")),
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": schedule,
        "fee": clean_text(pairs.get("수강료")),
        "target": clean_text(pairs.get("신청대상")),
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "capacity": clean_text(pairs.get("모집인원")),
        "capacity_total": capacity_total,
        "room": clean_text(pairs.get("장소")),
        "venue_name": clean_text(pairs.get("장소")),
        "description": clean_text(soup.select_one("#container").get_text(" ", strip=True) if soup.select_one("#container") else ""),
        "raw_detail_pairs": pairs,
    }


def collect_jongno_reserv_deadline(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    seen: set[str] = set()
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    base_query.setdefault("viewType", ["2"])
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        if page > 1:
            query["pageIndex"] = [str(page)]
        current_url = parsed._replace(path="/reserv/alllist.do", query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        cards = soup.select("ul.mgs-line > li")
        if not cards:
            break
        page_rows = 0
        for card in cards:
            link = card.select_one("a[href*='/reserv/detail.do']")
            title_node = card.select_one(".tit")
            title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
            if not link or not title or is_low_value_title(title):
                continue
            raw_url = normalize_link(current_url, link.get("href")) or current_url
            pg_id = clean_text((parse_qs(urlparse(raw_url).query).get("pgId") or [""])[0])
            if pg_id and pg_id in seen:
                continue
            if pg_id:
                seen.add(pg_id)
            pairs = jongno_reserv_card_pairs(card)
            status = jongno_reserv_status(card.select_one(".cp").get_text(" ", strip=True) if card.select_one(".cp") else "")
            detail: dict[str, Any] = {}
            if raw_url and detail_pages < detail_limit:
                try:
                    detail = jongno_reserv_detail_fields(s, raw_url, timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("jongno reserv detail fetch failed %s: %s", raw_url, exc)
            final_title = clean_text(detail.get("title")) or title
            room = clean_text(detail.get("room")) or clean_text(pairs.get("장소"))
            branch = room or target.branch
            final_status = clean_text(detail.get("status")) or status
            capacity_total = detail.get("capacity_total")
            if capacity_total is None:
                capacity_total = parse_capacity_number(pairs.get("모집"))
            row = {
                "provider": target.provider,
                "provider_course_id": pg_id or stable_course_id(target.provider, raw_url, final_title, branch),
                "title": final_title,
                "branch": branch,
                "branch_code": stable_provider(target.provider[:32], branch),
                "category": "종로구 통합예약",
                "raw_url": raw_url,
                "application_url": raw_url if final_status in {"접수중", "접수예정"} else "",
                "status": final_status,
                "period": clean_text(detail.get("period")) or normalize_mixed_date_range(pairs.get("기간", "")),
                "apply_period": clean_text(detail.get("apply_period")) or normalize_mixed_date_range(pairs.get("신청기간", "")),
                "schedule_raw": clean_text(detail.get("schedule_raw")) or normalize_mixed_date_range(pairs.get("기간", "")),
                "target": clean_text(detail.get("target")),
                "fee": clean_text(detail.get("fee")) or clean_text(pairs.get("수강료")),
                "capacity": clean_text(detail.get("capacity")) or clean_text(pairs.get("모집")),
                "capacity_total": capacity_total,
                "room": room,
                "venue_name": clean_text(detail.get("venue_name")) or room,
                "description": clean_text(detail.get("description")) or clean_text(card.get_text(" ", strip=True)),
                "application_method_raw": clean_text(detail.get("application_method_raw")),
                "raw_fields": {
                    "parser": "jongno_reserv_deadline_list+detail",
                    "pg_id": pg_id,
                    "page_url": current_url,
                    "list_pairs": pairs,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select("a[href^='javascript:linkPage'], a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "jongno_reserv_deadline_list+detail", meta


def jongno_jachi_status(value: Any) -> str:
    text = clean_text(value)
    if "접수중" in text:
        return "접수중"
    if "방문접수" in text:
        return "방문접수"
    if "대기" in text or "예정" in text:
        return "접수예정"
    if "마감" in text or "종료" in text:
        return "접수마감"
    return normalize_status(text) or text


def jongno_jachi_capacity(value: Any) -> tuple[str, Optional[int], Optional[int]]:
    text = clean_text(value)
    parts: list[str] = []
    current_total = 0
    capacity_total = 0
    found = False
    for label, total, current in re.findall(r"([가-힣]+접수)\s*정원\s*:\s*(\d+)\s*명\s*/\s*접수\s*:\s*(\d+)\s*명", text):
        found = True
        total_int = int(total)
        current_int = int(current)
        capacity_total += total_int
        current_total += current_int
        parts.append(f"{label} {current_int}/{total_int}")
    if found:
        return clean_text(" / ".join(parts)), current_total, capacity_total
    current, total = parse_capacity_pair(text)
    return text, current, total


def jongno_jachi_page_url(base_url: str, page: int) -> str:
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    if page > 1:
        query["pageNo"] = [str(page)]
    else:
        query.pop("pageNo", None)
    return parsed._replace(path="/Program/Default.aspx", query=urlencode(query, doseq=True)).geturl()


def jongno_jachi_detail_pairs(dd: Any) -> dict[str, str]:
    table = dd.select_one("table.table_list") if hasattr(dd, "select_one") else None
    return pairs_from_tables(table) if table else {}


def collect_jongno_jachi_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    seen: set[str] = set()
    pagination_detected = False

    for page in range(1, max(1, max_pages) + 1):
        current_url = jongno_jachi_page_url(target.url, page)
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        nav = soup.select_one("dl#navi")
        if not nav:
            break
        dts = nav.find_all("dt", recursive=False)
        page_rows = 0
        for index, dt in enumerate(dts, start=1):
            summary_table = dt.select_one("table.table_list")
            if not summary_table:
                continue
            summary_cells = [
                clean_text(cell.get_text(" ", strip=True))
                for cell in summary_table.select_one("tr").find_all(["th", "td"])
            ] if summary_table.select_one("tr") else []
            if len(summary_cells) < 8 or not summary_cells[0].isdigit():
                continue
            answer_id = f"answer{index}"
            dd = nav.find("dd", id=answer_id)
            detail_pairs = jongno_jachi_detail_pairs(dd) if dd else {}
            raw_url = f"{current_url}#{answer_id}"
            course_no = summary_cells[0]
            category = summary_cells[1]
            target_text = clean_text(detail_pairs.get("교육대상") or summary_cells[2])
            raw_title = clean_text(detail_pairs.get("강좌명") or summary_cells[3])
            branch_area = clean_text(detail_pairs.get("자치회관"))
            branch = f"{branch_area} 자치회관" if branch_area else "종로구 자치회관"
            title = clean_text(re.sub(r"^\[[^\]]+\]\s*", "", raw_title)) or raw_title
            if not title or is_low_value_title(title):
                continue
            key = f"{page}:{course_no}:{title}:{branch}"
            if key in seen:
                continue
            seen.add(key)
            status = jongno_jachi_status(summary_cells[7])
            period = normalize_month_day_range(summary_cells[6])
            apply_period = normalize_mixed_date_range(detail_pairs.get("접수기간") or normalize_month_day_range(summary_cells[5]))
            schedule = clean_text(detail_pairs.get("교육기간/시간"))
            capacity, capacity_current, capacity_total = jongno_jachi_capacity(
                clean_text(" ".join(part for part in [detail_pairs.get("온라인접수"), detail_pairs.get("방문접수")] if part))
            )
            description = clean_text(
                " ".join(
                    part
                    for part in [
                        detail_pairs.get("강좌소개"),
                        detail_pairs.get("수업준비물"),
                        detail_pairs.get("문의전화"),
                    ]
                    if part
                )
            )
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, key, title, branch),
                "title": title,
                "branch": branch,
                "branch_code": stable_provider(target.provider[:32], branch),
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url if status in {"접수중", "접수예정", "방문접수"} else "",
                "status": status,
                "fee": clean_text(detail_pairs.get("수강료") or "").replace("￦", "").strip(),
                "period": period,
                "apply_period": apply_period,
                "schedule_raw": schedule,
                "target": target_text,
                "instructor": clean_text(detail_pairs.get("강사명") or summary_cells[4]),
                "capacity": capacity,
                "capacity_current": capacity_current,
                "capacity_total": capacity_total,
                "room": clean_text(detail_pairs.get("교육장소")),
                "venue_name": clean_text(detail_pairs.get("교육장소") or branch),
                "phone": clean_text(detail_pairs.get("문의전화")),
                "description": description or clean_text(dd.get_text(" ", strip=True) if dd else ""),
                "application_method_raw": status,
                "program_type": "강좌",
                "collection_category": "체육/스포츠",
                "domain_category": "체육/스포츠",
                "source_group": "sports_facility",
                "operator_type": "지자체/공공기관",
                "collection_type": "static_html",
                "raw_fields": {
                    "parser": "jongno_jachi_program_list",
                    "page_url": current_url,
                    "summary_cells": summary_cells,
                    "detail_pairs": detail_pairs,
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select("a[href*='pageNo=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "jongno_jachi_program_list", meta


def guri_reserve_status(value: str) -> str:
    text = clean_text(value)
    if "접수중" in text or "대기자접수" in text:
        return "접수중"
    if "예정" in text:
        return "접수예정"
    if "마감" in text or "종료" in text:
        return "접수마감"
    return normalize_status(text) or text


def guri_capacity(value: str) -> tuple[Optional[int], Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value)
    main = re.search(r"신청\s*(\d+)\s*명\s*/\s*모집정원\s*(\d+)\s*명", text)
    if not main:
        main = re.search(r"(\d+)\s*/\s*(\d+)", text)
    wait = re.search(r"대기신청\s*(\d+)\s*명\s*/\s*대기정원\s*(\d+)\s*명", text)
    return (
        int(main.group(1)) if main else None,
        int(main.group(2)) if main else None,
        int(wait.group(1)) if wait else None,
        int(wait.group(2)) if wait else None,
    )


def guri_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    title = clean_text(soup.select_one(".title_area .tit_text").get_text(" ", strip=True) if soup.select_one(".title_area .tit_text") else "")
    status = clean_text(soup.select_one(".title_area .acc_btn").get_text(" ", strip=True) if soup.select_one(".title_area .acc_btn") else "")
    pairs = pairs_from_tables(soup)
    current, total, wait_current, wait_total = guri_capacity(pairs.get("접수현황", ""))
    fee = clean_text(pairs.get("수강료"))
    if fee in {"0", "0원"}:
        fee = "무료"
    period = bucheon_reservation_datetime_range(pairs.get("교육기간", ""))
    schedule = clean_text(pairs.get("교육시간"))
    return {
        "title": title,
        "status": guri_reserve_status(status),
        "apply_period": bucheon_reservation_datetime_range(pairs.get("접수기간", "")),
        "period": period,
        "schedule_raw": schedule,
        "application_method_raw": clean_text(pairs.get("신청방법")),
        "target": clean_text(pairs.get("교육대상")),
        "capacity": clean_text(pairs.get("접수현황")),
        "capacity_current": current,
        "capacity_total": total,
        "waitlist_current": wait_current,
        "waitlist_total": wait_total,
        "room": clean_text(pairs.get("교육장")),
        "venue_name": clean_text(pairs.get("교육장")),
        "instructor": clean_text(pairs.get("강사명")),
        "fee": fee,
        "phone": clean_text(pairs.get("문의전화")),
        "description": clean_text(" ".join(part for part in [pairs.get("강의소개"), pairs.get("유의사항")] if part)),
        "raw_detail_pairs": pairs,
    }


def collect_guri_user_course_list(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    base_query.setdefault("pageUnit", ["15"])
    seen: set[str] = set()
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["pageIndex"] = [str(page)]
        page_url = parsed._replace(path="/reserve/selectGuriUserCourseList.do", query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        table = soup.select_one("table")
        if not table:
            break
        page_rows = 0
        for tr in table.select("tbody tr"):
            cells = tr.find_all("td", recursive=False)
            if len(cells) < 8:
                continue
            link = cells[1].find("a", href=True)
            title = clean_text(link.get_text(" ", strip=True) if link else cells[1].get_text(" ", strip=True))
            if not link or not title:
                continue
            raw_url = normalize_link(page_url, link.get("href")) or page_url
            course_id = clean_text((parse_qs(urlparse(raw_url).query).get("lctreRcritKey") or [""])[0])
            if course_id and course_id in seen:
                continue
            if course_id:
                seen.add(course_id)
            period_cell = clean_text(cells[2].get_text(" ", strip=True))
            dates = re.findall(r"\d{4}-\d{2}-\d{2}\s*~\s*\d{4}-\d{2}-\d{2}", period_cell)
            apply_period = bucheon_reservation_datetime_range(dates[0]) if len(dates) >= 1 else ""
            period = bucheon_reservation_datetime_range(dates[1]) if len(dates) >= 2 else ""
            schedule = clean_text(cells[3].get_text(" ", strip=True))
            current, total, wait_current, wait_total = guri_capacity(cells[5].get_text(" ", strip=True))
            detail: dict[str, Any] = {}
            if raw_url and detail_pages < detail_limit:
                try:
                    detail = guri_detail_fields(s, raw_url, timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("guri course detail fetch failed %s: %s", raw_url, exc)
            final_title = clean_text(detail.get("title")) or title
            room = clean_text(detail.get("room"))
            branch = room or target.branch
            final_status = clean_text(detail.get("status")) or guri_reserve_status(cells[7].get_text(" ", strip=True))
            row = {
                "provider": target.provider,
                "provider_course_id": course_id or stable_course_id(target.provider, raw_url, final_title, branch),
                "title": final_title,
                "branch": branch,
                "branch_code": stable_provider(target.provider[:32], branch),
                "category": "구리시 교육강좌",
                "raw_url": raw_url,
                "application_url": raw_url if final_status in {"접수중", "접수예정"} else "",
                "status": final_status,
                "period": clean_text(detail.get("period")) or period,
                "apply_period": clean_text(detail.get("apply_period")) or apply_period,
                "schedule_raw": clean_text(detail.get("schedule_raw")) or schedule,
                "target": clean_text(detail.get("target")),
                "fee": clean_text(detail.get("fee")),
                "capacity": clean_text(detail.get("capacity")) or clean_text(cells[5].get_text(" ", strip=True)),
                "capacity_current": detail.get("capacity_current") if detail.get("capacity_current") is not None else current,
                "capacity_total": detail.get("capacity_total") if detail.get("capacity_total") is not None else total,
                "waitlist_current": detail.get("waitlist_current") if detail.get("waitlist_current") is not None else wait_current,
                "waitlist_total": detail.get("waitlist_total") if detail.get("waitlist_total") is not None else wait_total,
                "room": room,
                "venue_name": clean_text(detail.get("venue_name")) or room,
                "phone": clean_text(detail.get("phone")),
                "instructor": clean_text(detail.get("instructor")),
                "description": clean_text(detail.get("description")) or clean_text(tr.get_text(" ", strip=True)),
                "application_method_raw": clean_text(detail.get("application_method_raw")) or clean_text(cells[6].get_text(" ", strip=True)),
                "raw_fields": {
                    "parser": "guri_user_course_list+detail",
                    "course_id": course_id,
                    "page_url": page_url,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination a[href], .paging a[href], a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "guri_user_course_list+detail", meta


SDM_LIFELONG_LIST_URL = "https://www.sdm.go.kr/lll/user/lectureinfo/lectureInfoList.do?itemCd1=04&page=1"
SDM_LIFELONG_LABELS = {
    "교육대상",
    "교육기간",
    "교육장소",
    "교육요일",
    "수강료",
    "접수기간",
    "신청방법",
    "신청현황",
    "강의내용",
    "교육기관 안내",
    "기관명",
    "교육장명",
    "위치",
    "문의전화",
    "강사 소개",
    "강사명",
    "이메일",
    "강사소개",
    "목록",
}


def sdm_lifelong_pairs_from_lines(lines: list[str]) -> dict[str, str]:
    pairs: dict[str, str] = {}
    index = 0
    while index < len(lines):
        label = clean_text(lines[index])
        if label not in SDM_LIFELONG_LABELS:
            index += 1
            continue
        values: list[str] = []
        index += 1
        while index < len(lines):
            candidate = clean_text(lines[index])
            if candidate in SDM_LIFELONG_LABELS:
                break
            if candidate:
                values.append(candidate)
            index += 1
        pairs[label] = clean_text(" ".join(values))
    return pairs


def sdm_lifelong_detail_fields(s: requests.Session, detail_url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    pairs = sdm_lifelong_pairs_from_lines(lines_from_soup(soup))
    description = clean_text(pairs.get("강의내용"))
    material_note = ""
    material_match = re.search(r"재료비\s*[:：]\s*([^<]+?)(?=\s+(?:교육기관 안내|<강의내용>|강의내용|$))", description)
    if material_match:
        material_note = clean_text(material_match.group(1))
    return {
        "period": normalize_mixed_date_range(pairs.get("교육기간", "")),
        "schedule_raw": clean_text(pairs.get("교육요일")),
        "target": clean_text(pairs.get("교육대상")),
        "fee": clean_text(pairs.get("수강료")),
        "room": clean_text(pairs.get("교육장소") or pairs.get("교육장명")),
        "venue_name": clean_text(pairs.get("교육장소") or pairs.get("교육장명")),
        "phone": clean_text(pairs.get("문의전화")),
        "instructor": clean_text(pairs.get("강사명")),
        "application_method_raw": clean_text(pairs.get("신청방법")),
        "material_note": material_note,
        "description": description,
        "raw_detail_pairs": pairs,
    }


def collect_sdm_lifelong_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    parsed = urlparse(SDM_LIFELONG_LIST_URL)
    base_query = parse_qs(parsed.query)
    branch = target.branch or "서대문구 평생학습관"

    for page in range(1, max(1, max_pages) + 1):
        query = dict(base_query)
        query["page"] = [str(page)]
        page_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
            if len(cells) < 6 or not cells[0].isdigit():
                continue
            link = tr.find("a", href=True)
            title = clean_text(link.get_text(" ", strip=True) if link else cells[2])
            raw_url = normalize_link(page_url, link.get("href") if link else "")
            if not title or not raw_url:
                continue
            detail: dict[str, Any] = {}
            if detail_pages < detail_limit:
                try:
                    detail = sdm_lifelong_detail_fields(s, raw_url, timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("sdm lifelong detail fetch failed %s: %s", raw_url, exc)
            period = clean_text(detail.get("period")) or normalize_mixed_date_range(cells[3])
            apply_period = normalize_mixed_date_range(cells[3])
            fee = clean_text(detail.get("fee"))
            description = clean_text(detail.get("description")) or clean_text(" ".join(cells))
            capacity_current, capacity_total = parse_capacity_pair(cells[4])
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "branch_code": target.provider,
                "raw_url": raw_url,
                "application_url": raw_url if "접수" in cells[5] and "완료" not in cells[5] else "",
                "status": cells[5],
                "period": period,
                "apply_period": apply_period,
                "schedule_raw": clean_text(detail.get("schedule_raw")),
                "target": clean_text(detail.get("target")) or cells[1],
                "fee": fee,
                "room": clean_text(detail.get("room")),
                "venue_name": clean_text(detail.get("venue_name")) or branch,
                "phone": clean_text(detail.get("phone")),
                "instructor": clean_text(detail.get("instructor")),
                "capacity": cells[4],
                "capacity_current": capacity_current,
                "capacity_total": capacity_total,
                "application_method_raw": clean_text(detail.get("application_method_raw")),
                "material_note": clean_text(detail.get("material_note")),
                "description": description,
                "raw_fields": {
                    "parser": "sdm_lifelong_lecture_list",
                    "cells": cells,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                    "page_url": page_url,
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='page=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "sdm_lifelong_lecture_list+detail", meta


def geumcheon_normalize_date_text(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    text = text.split("※", 1)[0]
    text = re.sub(r"(\d{4})[.](\d{1,2})[.](\d{1,2})", lambda m: f"{m.group(1)}-{int(m.group(2)):02d}-{int(m.group(3)):02d}", text)
    text = re.sub(r"(\d{4}-\d{2}-\d{2})\([^)]*\)", r"\1", text)
    text = re.sub(r"\s*~\s*", " ~ ", text)
    return clean_text(text)


def geumcheon_description_from_soup(soup: BeautifulSoup) -> str:
    lines = lines_from_soup(soup)
    start = next((index for index, line in enumerate(lines) if line in {"상세정보", "강의소개", "교육안내"}), -1)
    end = next((index for index, line in enumerate(lines) if line == "목록" and (start < 0 or index > start)), len(lines))
    if start >= 0 and end > start:
        return clean_text(" ".join(lines[start + 1 : end]))
    return clean_text(" ".join(lines[:120]))


def geumcheon_detail_fields(s: requests.Session, detail_url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    pairs = pairs_from_tables(soup)
    capacity = clean_text(pairs.get("정원"))
    capacity_total = parse_capacity_number(capacity)
    applicant_text = clean_text(soup.get_text(" ", strip=True))
    applicant_match = re.search(r"신청자\s*:\s*(\d+)\s*/\s*(\d+)\s*명", applicant_text)
    capacity_current = int(applicant_match.group(1)) if applicant_match else None
    if capacity_total is None and applicant_match:
        capacity_total = int(applicant_match.group(2))
    room = clean_text(pairs.get("강의장소"))
    venue_address = ""
    address_match = re.search(r"(\d{5}\s+.+)$", room)
    if address_match:
        venue_address = clean_text(address_match.group(1))
        room = clean_text(room[: address_match.start()])
    return {
        "category": clean_text(pairs.get("강좌영역")),
        "status_text": clean_text(pairs.get("강좌상태")),
        "apply_period": geumcheon_normalize_date_text(pairs.get("신청기간")),
        "period": geumcheon_normalize_date_text(pairs.get("교육기간")),
        "schedule_raw": clean_text(pairs.get("강의시간")),
        "application_method_raw": clean_text(pairs.get("수강신청방법")),
        "fee": clean_text(pairs.get("수강료")),
        "room": room,
        "venue_name": room,
        "venue_address": venue_address,
        "target": clean_text(pairs.get("수강대상")),
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "provider_organizer": clean_text(pairs.get("주최")),
        "phone": clean_text(pairs.get("문의")),
        "description": geumcheon_description_from_soup(soup),
        "raw_detail_pairs": pairs,
    }


def geumcheon_status(value: str) -> str:
    text = clean_text(value).replace(" ", "")
    if any(token in text for token in ("모집중", "접수중")):
        return "접수중"
    if any(token in text for token in ("모집대기", "교육대기", "접수대기")):
        return "접수예정"
    if any(token in text for token in ("모집마감", "접수마감", "마감")):
        return "접수마감"
    return clean_text(value)


def collect_geumcheon_reserve_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    branch = target.branch or "금천구 통합예약"

    for page in range(1, max(1, max_pages) + 1):
        query = dict(base_query)
        query["pageIndex"] = [str(page)]
        page_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
            if len(cells) < 7:
                continue
            link = tr.select_one(".p-subject a[href], a[href*='edcLctreView']")
            title = clean_text(link.get_text(" ", strip=True) if link else "")
            raw_url = normalize_link(page_url, link.get("href") if link else "")
            if not title or not raw_url:
                continue
            venue = clean_text((tr.select_one(".p-subject p") or {}).get_text(" ", strip=True) if tr.select_one(".p-subject p") else "")
            status_text = cells[0]
            target_text = cells[2]
            date_text = cells[3]
            apply_match = re.search(r"신청\s*:\s*([^교육]+?)(?=\s*교육\s*:|$)", date_text)
            period_match = re.search(r"교육\s*:\s*(.+)", date_text)
            list_apply_period = geumcheon_normalize_date_text(apply_match.group(1) if apply_match else "")
            list_period = geumcheon_normalize_date_text(period_match.group(1) if period_match else date_text)
            capacity_current, capacity_total = parse_capacity_pair(cells[4])
            fee = clean_text(cells[5])
            detail: dict[str, Any] = {}
            if detail_pages < detail_limit:
                try:
                    detail = geumcheon_detail_fields(s, raw_url, timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("geumcheon detail fetch failed %s: %s", raw_url, exc)
            detail_status = clean_text(detail.get("status_text"))
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "branch_code": target.provider,
                "category": clean_text(detail.get("category")),
                "raw_url": raw_url,
                "application_url": raw_url if "모집 중" in status_text or "모집중" in detail_status else "",
                "status": geumcheon_status(detail_status or status_text),
                "period": clean_text(detail.get("period")) or list_period,
                "apply_period": clean_text(detail.get("apply_period")) or list_apply_period,
                "schedule_raw": clean_text(detail.get("schedule_raw")),
                "target": clean_text(detail.get("target")) or target_text,
                "fee": clean_text(detail.get("fee")) or fee,
                "room": clean_text(detail.get("room")) or venue,
                "venue_name": clean_text(detail.get("venue_name")) or venue,
                "venue_address": clean_text(detail.get("venue_address")),
                "phone": clean_text(detail.get("phone")),
                "capacity": clean_text(detail.get("capacity")) or cells[4],
                "capacity_current": detail.get("capacity_current") if detail.get("capacity_current") is not None else capacity_current,
                "capacity_total": detail.get("capacity_total") if detail.get("capacity_total") is not None else capacity_total,
                "application_method_raw": clean_text(detail.get("application_method_raw")) or clean_text(cells[6]),
                "description": clean_text(detail.get("description")) or clean_text(" ".join(cells)),
                "raw_fields": {
                    "parser": "geumcheon_reserve_lecture_list+detail",
                    "cells": cells,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                    "page_url": page_url,
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, .p-pagination, a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "geumcheon_reserve_lecture_list+detail", meta


def saha_library_title_parts(value: str) -> dict[str, str]:
    text = clean_text(value)
    pattern = (
        r"(?P<title>.*?)\s*도\s*서\s*관\s*:\s*"
        r"(?P<branch>.*?)\s*접수기간\s*:\s*"
        r"(?P<apply>\d{4}-\d{2}-\d{2}\s*~\s*\d{4}-\d{2}-\d{2})\s*"
        r"학습기간\s*:\s*(?P<period>\d{4}-\d{2}-\d{2}\s*~\s*\d{4}-\d{2}-\d{2})"
    )
    match = re.search(pattern, text)
    if not match:
        return {"title": text}
    return {key: clean_text(part) for key, part in match.groupdict().items()}


def saha_library_capacity(value: str) -> tuple[Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value).replace(",", "")
    match = re.search(r"(\d+)\s*/\s*(\d+)\s*/\s*(\d+)", text)
    if match:
        return int(match.group(1)), int(match.group(2)), int(match.group(3))
    current, total = parse_capacity_pair(text)
    return current, None, total


def saha_library_status(value: str) -> str:
    text = clean_text(value)
    if "접수중" in text:
        return "접수중"
    if "대기" in text:
        return "접수예정"
    if any(token in text for token in ("마감", "종강", "종료")):
        return "접수마감"
    return text


def saha_library_branch_code(provider: str, branch: str) -> str:
    slug = re.sub(r"[^A-Za-z0-9가-힣]+", "_", branch).strip("_")[:32]
    digest = hashlib.sha1(f"{provider}|{branch}".encode("utf-8")).hexdigest()[:8].upper()
    return f"{slug}_{digest}"[:50] if slug else f"{provider}_{digest}"[:50]


def collect_saha_library_lectures(target: CrawlTarget, timeout: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    branch_fallback = clean_text(target.branch) or "사하구 작은도서관"

    for tr in soup.select("table tbody tr"):
        cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
        if len(cells) < 6:
            continue
        parts = saha_library_title_parts(cells[0])
        title = clean_text(parts.get("title"))
        if not title or is_low_value_title(title):
            continue
        branch = clean_text(parts.get("branch")) or branch_fallback
        apply_period = clean_text(parts.get("apply"))
        period = clean_text(parts.get("period"))
        capacity_current, waitlist_current, capacity_total = saha_library_capacity(cells[1])
        status = saha_library_status(cells[5])
        description = clean_text(
            " | ".join(
                part
                for part in (
                    title,
                    f"도서관: {branch}",
                    f"접수기간: {apply_period}",
                    f"학습기간: {period}",
                    f"대상: {cells[2]}",
                    f"정원: {cells[1]}",
                )
                if part
            )
        )
        row = {
            "provider": target.provider,
            "provider_course_id": stable_course_id(target.provider, target.url, title, branch),
            "title": title,
            "branch": branch,
            "branch_code": saha_library_branch_code(target.provider, branch),
            "category": "작은도서관 프로그램",
            "raw_url": target.url,
            "application_url": target.url if status in {"접수중", "접수예정"} else "",
            "status": status,
            "period": period,
            "apply_period": apply_period,
            "schedule_raw": period,
            "target": cells[2],
            "capacity": cells[1],
            "capacity_current": capacity_current,
            "capacity_total": capacity_total,
            "waitlist_current": waitlist_current,
            "application_method_raw": cells[3],
            "fee": cells[4],
            "venue_name": branch,
            "description": description,
            "raw_fields": {"parser": "saha_library_lecture_table", "cells": cells},
        }
        rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})

    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "saha_library_lecture_table", meta


def ganghwa_lifelong_status(value: str) -> str:
    text = clean_text(value).replace("[", " ").replace("]", " ")
    if "접수중" in text:
        return "접수중"
    if any(token in text for token in ("접수마감", "마감", "종료", "폐강")):
        return "접수마감"
    if any(token in text for token in ("대기", "준비", "예정")):
        return "접수예정"
    return text


def ganghwa_lifelong_periods(value: str) -> tuple[str, str, str]:
    text = clean_text(value)
    apply_match = re.search(r"접수\s*:\s*(.*?)(?=\s*-\s*교육\s*:|$)", text)
    period_match = re.search(r"교육\s*:\s*(.*)$", text)
    apply_raw = clean_text(apply_match.group(1) if apply_match else "")
    period_raw = clean_text(period_match.group(1) if period_match else text)
    methods = " ".join(dict.fromkeys(re.findall(r"([가-힣]+)\s*\(", apply_raw)))
    return normalize_mixed_date_range(apply_raw), normalize_mixed_date_range(period_raw), clean_text(methods)


def ganghwa_lifelong_capacity(value: str) -> Optional[int]:
    text = clean_text(value).replace(",", "")
    match = re.search(r"(\d{1,5})", text)
    return int(match.group(1)) if match else None


def ganghwa_lifelong_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    pairs = pairs_from_definition_lists(soup)
    description = ""
    detail_table = soup.select_one("table")
    if detail_table:
        detail_cells = detail_table.find_all("td")
        if detail_cells:
            description = clean_text(detail_cells[0].get_text(" ", strip=True))
    capacity_total = ganghwa_lifelong_capacity(pairs.get("모집인원", ""))
    return {
        "category": clean_text(pairs.get("분야")),
        "target": clean_text(pairs.get("교육대상")),
        "room": clean_text(pairs.get("교육장소")),
        "venue_name": clean_text(pairs.get("교육기관")),
        "venue_address": clean_text(pairs.get("교육장소")),
        "period": normalize_mixed_date_range(pairs.get("교육기간", "")),
        "apply_period": normalize_mixed_date_range(pairs.get("접수기간", "")),
        "schedule_raw": clean_text(pairs.get("교육요일/시간")),
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "capacity_total": capacity_total,
        "phone": clean_text(pairs.get("문의전화")),
        "description": description,
        "raw_detail_pairs": pairs,
    }


def collect_ganghwa_lifelong_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    list_url = normalize_link(target.url, "/open_content/main/lecture/lecture.do?act=list") or target.url
    parsed = urlparse(list_url)
    base_query = parse_qs(parsed.query)
    base_query["act"] = ["list"]

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["nowPage"] = [str(page)]
        page_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            title_cell = tr.select_one("th.title") or tr.find("th")
            link = title_cell.select_one("p.lecture a[href], a[href]") if title_cell else None
            title = clean_text(link.get_text(" ", strip=True) if link else "")
            if not title or is_low_value_title(title):
                continue
            time_node = title_cell.select_one("p.time") if title_cell else None
            schedule_raw = clean_text(time_node.get_text(" ", strip=True) if time_node else "").strip("()")
            if not schedule_raw:
                schedule_match = re.search(r"\(([^()]*\d{1,2}:\d{2}[^()]*)\)\s*$", title)
                if schedule_match:
                    schedule_raw = clean_text(schedule_match.group(1))
                    title = clean_text(title[: schedule_match.start()])
            raw_url = normalize_link(page_url, link.get("href") if link else "") or page_url
            branch = clean_text((tr.select_one("td.place") or {}).get_text(" ", strip=True) if tr.select_one("td.place") else "")
            fee = clean_text((tr.select_one("td.price") or {}).get_text(" ", strip=True) if tr.select_one("td.price") else "")
            date_text = clean_text((tr.select_one("td.date") or {}).get_text(" ", strip=True) if tr.select_one("td.date") else "")
            state_text = clean_text((tr.select_one("td.state") or {}).get_text(" ", strip=True) if tr.select_one("td.state") else "")
            apply_period, period, application_method = ganghwa_lifelong_periods(date_text)
            status = ganghwa_lifelong_status(state_text)
            detail: dict[str, Any] = {}
            if raw_url and detail_pages < detail_limit:
                try:
                    detail = ganghwa_lifelong_detail_fields(s, raw_url, timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("ganghwa lifelong detail fetch failed %s: %s", raw_url, exc)
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": clean_text(detail.get("venue_name")) or branch or target.branch,
                "branch_code": stable_provider(target.provider[:32], clean_text(detail.get("venue_name")) or branch or target.branch),
                "category": clean_text(detail.get("category")) or "평생교육",
                "raw_url": raw_url,
                "application_url": raw_url if status in {"접수중", "접수예정"} else "",
                "status": status,
                "period": clean_text(detail.get("period")) or period,
                "apply_period": clean_text(detail.get("apply_period")) or apply_period,
                "schedule_raw": clean_text(detail.get("schedule_raw")) or schedule_raw,
                "target": clean_text(detail.get("target")),
                "fee": clean_text(detail.get("fee")) or fee,
                "room": clean_text(detail.get("room")),
                "venue_name": clean_text(detail.get("venue_name")) or branch,
                "venue_address": clean_text(detail.get("venue_address")),
                "capacity_total": detail.get("capacity_total"),
                "application_method_raw": clean_text(detail.get("application_method_raw")) or application_method,
                "phone": clean_text(detail.get("phone")),
                "description": clean_text(detail.get("description")) or clean_text(" ".join([title, branch, fee, date_text, state_text])),
                "raw_fields": {
                    "parser": "ganghwa_lifelong_lecture_table+detail",
                    "list_page_url": page_url,
                    "date_text": date_text,
                    "state_text": state_text,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1

        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='nowPage=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ganghwa_lifelong_lecture_table+detail", meta


def collect_sangju_reserve_list(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    labels = {"분류", "시설명", "운영기간", "주소", "접수기간", "정원", "안내"}
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for section in soup.select("#reserveList section, .list3 section"):
            lines = [clean_text(line) for line in section.get_text("\n", strip=True).splitlines() if clean_text(line)]
            number_index = next((index for index, line in enumerate(lines) if line.isdigit()), -1)
            if number_index < 0 or number_index + 1 >= len(lines):
                continue
            title = lines[number_index + 1]
            if not title or is_low_value_title(title):
                continue
            pairs = sequence_lines_to_pairs(lines, labels)
            detail_id = ""
            detail_link = section.find("a", onclick=re.compile(r"reserveList\.detail"))
            if detail_link:
                match = re.search(r"detail\('([^']+)'\)", clean_text(detail_link.get("onclick")))
                detail_id = match.group(1) if match else ""
            raw_url = f"{current_url}#reserve-{detail_id}" if detail_id else current_url
            status = lines[0] if number_index > 0 and status_has_course_state(lines[0]) else status_from_lines(lines)
            if not status and lines:
                status = lines[-1]
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": clean_text(pairs.get("시설명")) or target.branch,
                    "category": clean_text(pairs.get("교육과정") or pairs.get("분류")),
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": "",
                    "period": clean_text(pairs.get("교육기간") or pairs.get("운영기간")),
                    "apply_period": clean_text(pairs.get("접수일시") or pairs.get("접수기간")),
                    "schedule_raw": "",
                    "target": "",
                    "capacity": clean_text(pairs.get("정원")),
                    "capacity_current": clean_text(pairs.get("신청현황")),
                    "venue_address": clean_text(pairs.get("주소")),
                    "description": clean_text(section.get_text(" ", strip=True)),
                    "raw_fields": {"pairs": pairs, "lines": lines, "parser": "sangju_reserve_list"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pager, .pagination, .paging, a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "sangju_reserve_list", meta


def collect_naju_course_reception(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        if page > 1:
            query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
            if len(cells) < 6 or not cells[0].isdigit() or "媛쒖꽕??媛뺤쥖" in " ".join(cells):
                continue
            info = cells[1]
            title = clean_text(re.split(r"강\s*사\s*명\s*:", info)[0])
            if not title or is_low_value_title(title):
                continue
            instructor_match = re.search(r"강\s*사\s*명\s*:\s*(.*?)(?=신청기간\s*:|$)", info)
            apply_match = re.search(r"신청기간\s*:\s*(.*?)(?=교육기간\s*:|$)", info)
            period_match = re.search(r"교육기간\s*:\s*(.*)$", info)
            view_link = tr.find("a", href=re.compile(r"mode=view"))
            reserve_link = tr.find("a", href=re.compile(r"mode=reserve_form"))
            raw_url = normalize_link(current_url, view_link.get("href") if view_link else None) or current_url
            application_url = normalize_link(current_url, reserve_link.get("href") if reserve_link else None) or raw_url
            row: dict[str, Any] = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, cells[2]),
                "title": title,
                "branch": cells[2],
                "category": "",
                "raw_url": raw_url,
                "application_url": application_url,
                "status": cells[5].replace("접수하기", "").strip(),
                "fee": cells[4],
                "period": clean_text(period_match.group(1)) if period_match else "",
                "apply_period": clean_text(apply_match.group(1)) if apply_match else "",
                "schedule_raw": "",
                "target": "",
                "capacity": cells[3],
                "instructor": clean_text(instructor_match.group(1)) if instructor_match else "",
                "description": clean_text(tr.get_text(" ", strip=True)),
                "raw_fields": {"cells": cells, "parser": "naju_course_reception"},
            }
            if raw_url and detail_pages < 30:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    pairs = pairs_from_tables(detail_soup)
                    row["target"] = clean_text(pairs.get("교육대상")) or row["target"]
                    row["category"] = clean_text(pairs.get("교육분류")) or row["category"]
                    row["venue_name"] = clean_text(pairs.get("교육장소")) or row["branch"]
                    row["description"] = clean_text(pairs.get("강좌소개") or pairs.get("강의계획") or row["description"])
                except Exception as exc:
                    logger.debug("Naju detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "naju_course_reception", meta


def collect_bsbukgu_reservation(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
