def collect_cwg_lctre_search(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query, keep_blank_values=True)
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    no_current_data = False

    for page in range(1, max_pages + 1):
        if page == 1:
            current_url = target.url
        else:
            query["pageIndex"] = [str(page)]
            current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_text = clean_text(soup.get_text(" ", strip=True))
        no_current_data = no_current_data or "등록된 강좌가 없습니다" in page_text or bool(re.search(r"총\s+0\s*건", page_text))
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='pageIndex=']"))
        page_rows = 0

        for tr in soup.select("table tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
            if len(cells) < 9 or "등록된 강좌가 없습니다" in " ".join(cells):
                continue
            link = tr.find("a", href=True)
            title = clean_text(link.get_text(" ", strip=True) if link else cells[1])
            if not title or is_low_value_title(title):
                continue
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            status = cells[-1]
            schedule = cells[7] if len(cells) > 7 else ""
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "category": "평생교육",
                "raw_url": raw_url,
                "application_url": raw_url if "접수" in status and "마감" not in status else "",
                "status": status,
                "fee": cells[3] if len(cells) > 3 else "",
                "period": "",
                "apply_period": "",
                "schedule_raw": schedule,
                "target": "",
                "capacity": clean_text(" / ".join(part for part in [cells[5] if len(cells) > 5 else "", cells[6] if len(cells) > 6 else ""] if part)),
                "instructor": cells[2] if len(cells) > 2 else "",
                "application_method_raw": cells[4] if len(cells) > 4 else "",
                "description": clean_text(tr.get_text(" ", strip=True)),
                "raw_fields": {"cells": cells, "parser": "cwg_lctre_search_table"},
            }
            rows.append(row)
            page_rows += 1

        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "no_current_data": no_current_data and not rows,
        "no_current_reason": "no_open_courses" if no_current_data and not rows else "",
    }
    return dedupe_rows(rows), "cwg_lctre_search_table", meta


HNYOUTH_BASE_URL = "https://online.hnyouth.kr/HnYouth/"
HNYOUTH_LIST_URL = "https://online.hnyouth.kr/HnYouth/s_center/jLecture_Search_List_202406.ajax.php"
HNYOUTH_DETAIL_URL = "https://online.hnyouth.kr/HnYouth/s_center/pro_view.php"
HNYOUTH_BRANCH_NAME = "?섎궓?쒖껌?뚮뀈?섎젴愿"
HNYOUTH_BRANCH_ADDRESS = "寃쎄린???섎궓??議곗젙?濡?111"
HNYOUTH_BRANCH_PHONE = "031-760-5800"
HNYOUTH_FORM_KEYS = (
    "sales_code",
    "event_name",
    "g_code",
    "s_code",
    "b_code",
    "center_id",
    "page",
    "ntitle",
    "cx_id",
    "month_qty",
    "unit_price",
    "tot",
    "target_code",
)


def parse_hnyouth_go_link(onclick: Any) -> dict[str, str]:
    text = clean_text(onclick)
    if not text:
        return {}
    args = [unquote_plus(value) for value in re.findall(r"'([^']*)'", text)]
    return {key: args[index] for index, key in enumerate(HNYOUTH_FORM_KEYS) if index < len(args)}


def hnyouth_status(main_status: Any, action_status: Any) -> str:
    text = clean_text(" ".join(part for part in [main_status, action_status] if clean_text(part)))
    if "마감" in text:
        return "접수마감"
    if "대기" in text:
        return "대기접수"
    if "준비" in text:
        return "접수예정"
    if "접수" in text and "불가" not in text:
        return "접수중"
    return text or "접수상태 미정"


def hnyouth_label_value(text: str, label: str, stop_labels: tuple[str, ...]) -> str:
    stop_pattern = "|".join(re.escape(stop) for stop in stop_labels)
    pattern = re.escape(label) + r"\s*(.*?)(?=\s*(?:" + stop_pattern + r")\s|$)"
    match = re.search(pattern, text)
    return clean_text(match.group(1)) if match else ""


def hnyouth_longest_section(text: str, label: str, stop_labels: tuple[str, ...]) -> str:
    stop_pattern = "|".join(re.escape(stop) for stop in stop_labels)
    pattern = re.escape(label) + r"\s*(.*?)(?=\s*(?:" + stop_pattern + r")\s|$)"
    matches = [clean_text(match) for match in re.findall(pattern, text) if clean_text(match)]
    if not matches:
        return ""
    return max(matches, key=len)


def hnyouth_hidden_groups(soup: BeautifulSoup) -> list[dict[str, str]]:
    values = [
        clean_text(input_tag.get("value"))
        for input_tag in soup.select("input[type='hidden']")
        if not clean_text(input_tag.get("name")) and clean_text(input_tag.get("value"))
    ]
    groups: list[dict[str, str]] = []
    for index in range(0, len(values), 9):
        group = values[index : index + 9]
        if len(group) < 8 or not re.fullmatch(r"\d{8}", group[2] or ""):
            continue
        groups.append(
            {
                "capacity_total": group[0],
                "capacity_current": group[1],
                "apply_start": format_yyyymmdd(group[2]),
                "apply_end": format_yyyymmdd(group[3]),
                "apply_time_start": format_hhmm(group[4]),
                "apply_time_end": format_hhmm(group[5]),
                "class_start": format_yyyymmdd(group[6]),
                "progress_percent": group[7],
                "row_index": group[8] if len(group) > 8 else "",
            }
        )
    return groups


def parse_hnyouth_detail(
    s: requests.Session,
    form_params: dict[str, str],
    timeout: int,
) -> dict[str, Any]:
    if not form_params:
        return {}
    payload = {key: form_params.get(key, "") for key in HNYOUTH_FORM_KEYS}
    payload.update({"xtype": "J", "n_type": "program"})
    response = s.post(HNYOUTH_DETAIL_URL, data=payload, headers={"Referer": HNYOUTH_LIST_URL}, timeout=timeout)
    response.raise_for_status()
    if not response.encoding or response.encoding.lower() == "iso-8859-1":
        response.encoding = response.apparent_encoding
    soup = BeautifulSoup(response.text, "lxml")
    text = clean_text(soup.get_text(" ", strip=True))
    if "잘못된 접근" in text:
        return {}

    period = hnyouth_label_value(text, "강습기간", ("강습시간", "수강요금", "목록가기"))
    schedule = hnyouth_label_value(text, "강습시간", ("수강요금", "목록가기", "접수불가", "접수중"))
    fee = hnyouth_label_value(text, "수강요금", ("목록가기", "접수불가", "접수중", "준비물", "비고"))
    material_note = hnyouth_label_value(text, "준비물", ("비고", "강좌내용", "강좌소개"))
    note = hnyouth_label_value(text, "비고", ("강좌내용", "강좌소개", "강좌신청안내"))
    description = hnyouth_longest_section(text, "강좌소개", ("강좌신청안내", "환불규정안내", "TOP"))
    room = hnyouth_label_value(text, "강습장소", ("강습기간", "강습시간", "수강요금"))

    image_url = ""
    for image in soup.select("img"):
        src = clean_text(image.get("src"))
        if not src or src.startswith("data:") or "no_img" in src.lower():
            continue
        image_url = normalize_link(HNYOUTH_DETAIL_URL, src)
        if image_url:
            break

    return {
        "period": period,
        "schedule_raw": schedule,
        "fee": fee,
        "material_note": material_note,
        "description": clean_text(" ".join(part for part in [description, note] if part)),
        "room": room,
        "image_url": image_url,
        "raw_fields": {
            "detail_text_sample": text[:1000],
            "detail_parser": "hnyouth_detail_post",
        },
    }


def collect_hnyouth_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.verify = False
    s.headers.update({"Referer": HNYOUTH_BASE_URL, "Origin": "https://online.hnyouth.kr"})
    s.get(HNYOUTH_BASE_URL, timeout=timeout)

    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    no_current_data = False
    no_current_reason = ""
    for page in range(1, max_pages + 1):
        response = s.post(
            HNYOUTH_LIST_URL,
            data={"item1": "02", "item2": "", "target": "", "area": "02", "page": str(page), "tot": "T"},
            timeout=timeout,
        )
        response.raise_for_status()
        if not response.encoding or response.encoding.lower() == "iso-8859-1":
            response.encoding = response.apparent_encoding
        soup = BeautifulSoup(response.text, "lxml")
        page_text = clean_text(soup.get_text(" ", strip=True))
        if "현재 수강신청 기간이 아닙니다" in page_text:
            no_current_data = True
            no_current_reason = "not_application_period"
        pages += 1
        pagination_detected = pagination_detected or bool(soup.select(".ds_pagination a[href*='page=']"))
        hidden_groups = hnyouth_hidden_groups(soup)
        page_rows = 0

        for row_index, tr in enumerate(soup.select("tr.jone, tr.tt, tr.cc:not(.xx)")):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td", recursive=False)]
            if len(cells) < 10:
                continue
            link = tr.find("a", onclick=True)
            form_params = parse_hnyouth_go_link(link.get("onclick") if link else "")
            title = clean_text(form_params.get("ntitle")) or clean_text((link or tr).get_text(" ", strip=True))
            if not title or is_low_value_title(title):
                continue

            hidden = hidden_groups[row_index] if row_index < len(hidden_groups) else {}
            course_code = clean_text(form_params.get("sales_code")) or (tr.get("class") or [""])[0]
            raw_url = HNYOUTH_DETAIL_URL + "?" + urlencode(
                {
                    "sales_code": course_code,
                    "center_id": form_params.get("center_id") or "02",
                    "target_code": form_params.get("target_code") or "",
                }
            )
            status = hnyouth_status(cells[8], cells[9])
            schedule_raw = clean_text(cells[4].replace("~", " ~ "))
            sessions_match = re.search(r"(\d{1,3})\s*회", title)
            apply_period = ""
            if hidden.get("apply_start") and hidden.get("apply_end"):
                apply_period = f"{hidden['apply_start']} ~ {hidden['apply_end']}"
                if hidden.get("apply_time_start") and hidden.get("apply_time_end"):
                    apply_period += f" {hidden['apply_time_start']} ~ {hidden['apply_time_end']}"

            row = {
                "provider": target.provider,
                "provider_course_id": course_code or stable_course_id(target.provider, raw_url, title, HNYOUTH_BRANCH_NAME),
                "title": title,
                "branch": HNYOUTH_BRANCH_NAME,
                "branch_code": "HN_YOUTH_CENTER",
                "preserve_branch": True,
                "address": HNYOUTH_BRANCH_ADDRESS,
                "phone": HNYOUTH_BRANCH_PHONE,
                "branch_url": HNYOUTH_BASE_URL,
                "category": clean_text(form_params.get("event_name")) or cells[1],
                "raw_url": raw_url,
                "application_url": raw_url,
                "application_method_raw": "온라인 수강신청",
                "reservation_available": status in {"접수중", "대기접수"},
                "status": status,
                "fee": cells[6],
                "sessions": int(sessions_match.group(1)) if sessions_match else 0,
                "schedule_raw": schedule_raw,
                "target": cells[3],
                "capacity": cells[7],
                "capacity_total": hidden.get("capacity_total"),
                "capacity_current": hidden.get("capacity_current"),
                "apply_period": apply_period,
                "room": cells[0],
                "venue_address": HNYOUTH_BRANCH_ADDRESS,
                "description": clean_text(" ".join(part for part in [title, cells[1], cells[3], schedule_raw] if part)),
                "program_type": "강좌",
                "raw_fields": {
                    "cells": cells,
                    "form_params": form_params,
                    "hidden": hidden,
                    "parser": "hnyouth_lecture_ajax",
                },
            }
            rows.append(row)
            page_rows += 1

        if page_rows == 0 or not soup.select(f".ds_pagination a[href*='page={page + 1}'], .ds_pagination a[data-value='{page + 1}']"):
            break

    detail_pages = 0
    detail_cap = len(rows) if detail_limit > 0 else 0
    for row in rows[:detail_cap]:
        try:
            detail = parse_hnyouth_detail(s, row.get("raw_fields", {}).get("form_params", {}), timeout=timeout)
        except Exception as exc:
            logger.debug("hnyouth detail fetch failed %s: %s", row.get("provider_course_id"), exc)
            continue
        if not detail:
            continue
        detail_pages += 1
        detail_raw = detail.pop("raw_fields", {})
        row_raw = row.setdefault("raw_fields", {})
        row_raw.update(detail_raw)
        for key, value in detail.items():
            if value:
                row[key] = value

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "no_current_data": no_current_data and not rows,
        "no_current_reason": no_current_reason if no_current_data and not rows else "",
    }
    return dedupe_rows(rows), "hnyouth_lecture_ajax+detail", meta


def collect_icdonggu_future_edu(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    for item in soup.select(".eduList > li, .board_list .eduList > li"):
        title_node = item.select_one(".tit")
        title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
        if not title or is_low_value_title(title):
            continue
        tags = [clean_text(node.get_text(" ", strip=True)) for node in item.select(".cate .tag_state")]
        status = next((tag for tag in reversed(tags) if status_has_course_state(tag) or tag in {"신청예정", "대기접수"}), "")
        category = tags[0] if tags else ""
        time_group = tags[1] if len(tags) > 1 else ""
        spot = clean_text((item.select_one(".spot") or item).get_text(" ", strip=True)).strip("[]")
        pairs = labeled_pairs_from_named_spans(item, "span.q")
        raw_url = onclick_location_url(target.url, item) or target.url
        image = item.find("img")
        image_url = normalize_link(target.url, image.get("src") if image else None)
        schedule_match = re.search(r"(\d{1,2}\s*월\s*\d{1,2}\s*일\s*\([^)]+\)\s*\d{1,2}:\d{2}|\d{1,2}:\d{2})", title)
        schedule = clean_text(" ".join(part for part in [time_group, schedule_match.group(1) if schedule_match else ""] if part))
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, spot or target.branch),
                "title": title,
                "branch": spot or target.branch,
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "fee": clean_text(pairs.get("수강료") or pairs.get("교육비")),
                "period": normalize_mixed_date_range(pairs.get("수강기간", "") or pairs.get("교육기간", "")),
                "apply_period": normalize_mixed_date_range(pairs.get("접수일시", "") or pairs.get("접수기간", "")),
                "schedule_raw": schedule,
                "target": clean_text(pairs.get("교육대상") or pairs.get("수강대상")),
                "capacity": clean_text(pairs.get("정원")),
                "image_url": image_url,
                "description": clean_text(item.get_text(" ", strip=True)),
                "raw_fields": {"pairs": pairs, "tags": tags, "parser": "icdonggu_future_edu"},
            }
        )
    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": bool(soup.select(".pagination, .paging, .page")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "icdonggu_future_edu", meta


def collect_yeonje_lecture_list(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    list_url = target.url.replace("/edu/contents.do", "/edu/lecture/list.do")
    parsed = urlparse(list_url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False
    for page in range(1, max_pages + 1):
        query = dict(base_query)
        if page > 1:
            query["page"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for item in soup.select(".edu_items"):
            title_node = item.select_one(".lecture_tit a")
            title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
            title = re.sub(r"^No\.\s*\d+\s*", "", title)
            if not title or is_low_value_title(title):
                continue
            pairs: dict[str, str] = {}
            for dl in item.select(".lecture_ul dl"):
                dt = dl.find("dt")
                dd = dl.find("dd")
                key = normalize_korean_label(dt.get_text(" ", strip=True) if dt else "")
                value = clean_text(dd.get_text(" ", strip=True) if dd else "")
                if key:
                    pairs[key] = value
            data_keyset = clean_text(title_node.get("data-keyset") if title_node else "")
            idx_match = re.search(r"lecIdx['\"]?\s*:\s*['\"]?(\d+)", data_keyset)
            lec_idx = idx_match.group(1) if idx_match else ""
            raw_url = current_url
            if lec_idx:
                raw_url = normalize_link(current_url, f"view.do?mId={(base_query.get('mId') or ['0701010000'])[0]}&lecIdx={lec_idx}")
            status = clean_text(pairs.get("상태"))
            current_capacity, total_capacity = parse_capacity_pair(pairs.get("모집/신청"))
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, pairs.get("교육기관") or target.branch),
                "title": title,
                "branch": clean_text(pairs.get("교육기관")) or target.branch,
                "raw_url": raw_url,
                "application_url": raw_url if "온라인" in pairs.get("접수방법", "") or "접수중" in status else "",
                "status": status,
                "fee": "",
                "period": normalize_mixed_date_range(pairs.get("수강기간", "") or pairs.get("교육기간", "")),
                "apply_period": normalize_mixed_date_range(pairs.get("접수일시", "") or pairs.get("접수기간", "")),
                "schedule_raw": "",
                "target": "",
                "capacity": total_capacity,
                "capacity_current": current_capacity,
                "application_method_raw": clean_text(pairs.get("접수방법")),
                "description": clean_text(item.get_text(" ", strip=True)),
                "raw_fields": {"pairs": pairs, "parser": "yeonje_lecture_list", "lec_idx": lec_idx},
            }
            if raw_url and detail_pages < 30:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    detail_pairs = pairs_from_tables(detail_soup)
                    detail_capacity_current, detail_capacity_total = parse_capacity_pair(detail_pairs.get("교육정원"))
                    description_node = detail_soup.select_one(".pad10a")
                    row["branch"] = clean_text(detail_pairs.get("학습기관")) or row["branch"]
                    row["category"] = clean_text(detail_pairs.get("사업명")) or row.get("category", "")
                    row["status"] = clean_text(detail_pairs.get("상태")) or row["status"]
                    row["fee"] = clean_text(detail_pairs.get("수강료"))
                    row["material_fee"] = clean_text(detail_pairs.get("추가비용"))
                    row["period"] = normalize_mixed_date_range(detail_pairs.get("학습기간", "")) or row["period"]
                    row["apply_period"] = normalize_mixed_date_range(detail_pairs.get("접수기간", "")) or row["apply_period"]
                    row["schedule_raw"] = clean_text(detail_pairs.get("교육시간"))
                    row["target"] = clean_text(detail_pairs.get("교육대상"))
                    row["instructor"] = clean_instructor_name(detail_pairs.get("강사명"))
                    row["room"] = clean_text(detail_pairs.get("교육장소"))
                    row["venue_name"] = clean_text(detail_pairs.get("교육장소"))
                    row["capacity"] = detail_capacity_total or row["capacity"]
                    row["capacity_current"] = detail_capacity_current or row["capacity_current"]
                    row["application_method_raw"] = clean_text(detail_pairs.get("접수방법")) or row["application_method_raw"]
                    row["application_url"] = raw_url if "접수중" in row["status"] or "온라인" in row["application_method_raw"] else ""
                    row["description"] = clean_text(
                        description_node.get_text(" ", strip=True) if description_node else detail_soup.get_text(" ", strip=True)
                    )[:1200]
                    row["raw_fields"] = {
                        "pairs": pairs,
                        "detail_pairs": detail_pairs,
                        "parser": "yeonje_lecture_list",
                        "lec_idx": lec_idx,
                    }
                except Exception as exc:
                    logger.debug("Yeonje detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, .page, .paginate"))
        if page_rows == 0:
            break
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "yeonje_lecture_list", meta


SASANG_APPLY_LIST_URL = (
    "https://www.sasang.go.kr/user/apply/list.sasang"
    "?menuCd=DOM_000001003016000000&contentsSid=1650&cpath=%2Fyeyak"
)


def sasang_int(value: Any) -> str:
    match = re.search(r"\d{1,6}", clean_text(value).replace(",", ""))
    return match.group(0) if match else ""


def sasang_detail_sections(soup: BeautifulSoup) -> dict[str, str]:
    sections: dict[str, str] = {}
    for section in soup.select(".edu_vtype .infor_con"):
        heading = clean_text(section.select_one("h2.title").get_text(" ", strip=True) if section.select_one("h2.title") else "")
        if not heading:
            continue
        value = clean_text(section.get_text(" ", strip=True))
        if value.startswith(heading):
            value = clean_text(value[len(heading) :])
        sections[heading] = value
    return sections


def sasang_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    info_scope = soup.select_one(".edu_vtype .infor") or soup
    pairs = labeled_pairs_from_named_spans(info_scope, "span.name")
    status = clean_text((soup.select_one(".edu_vtype .stat") or soup.select_one(".stat") or soup).get_text(" ", strip=True))
    title_node = soup.select_one(".edu_vtype .bbs_infor dt")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    if status and title.startswith(status):
        title = clean_text(title[len(status) :])
    sections = sasang_detail_sections(soup)
    description = clean_text(" ".join(sections.get(key, "") for key in ("과정개요", "학습목표", "기타사항") if sections.get(key)))
    material_note = clean_text(pairs.get("준비물"))
    return {
        "title": title,
        "category": clean_text(pairs.get("교육과정")),
        "target": clean_text(pairs.get("교육대상")),
        "status": status,
        "fee": clean_text(pairs.get("수강료")),
        "material_fee": extract_material_fee_amount(material_note),
        "material_note": material_note,
        "period": normalize_mixed_date_range(pairs.get("수강기간", "") or pairs.get("교육기간", "")),
        "apply_period": normalize_mixed_date_range(pairs.get("접수일시", "") or pairs.get("접수기간", "")),
        "schedule_raw": clean_text(pairs.get("요일/시간") or pairs.get("교육시간")),
        "branch": clean_text(pairs.get("교육기관")),
        "room": clean_text(pairs.get("교육장소")),
        "venue_name": clean_text(pairs.get("교육장소")),
        "capacity_total": sasang_int(pairs.get("인터넷모집") or pairs.get("모집인원")),
        "capacity_current": sasang_int(pairs.get("현재신청자수")),
        "waitlist_total": sasang_int(pairs.get("대기자모집")),
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "phone": clean_text(pairs.get("문의전화")),
        "instructor": clean_text(pairs.get("강사명")),
        "description": description or clean_text(" ".join(sections.values())),
        "instructor_description": clean_text(sections.get("강사소개")),
        "raw_detail_pairs": pairs,
        "raw_detail_sections": sections,
    }


def sasang_prefer_branch(branch: str, room: str, fallback: str) -> str:
    branch = clean_text(branch)
    room = clean_text(room)
    if branch and branch not in {"전체", "기타", "교육기관"}:
        return branch
    match = re.search(r"([가-힣A-Za-z0-9·\s]+?(?:도서관|박물관|학습관|센터|복지관|구청|마을|광장))", room)
    if match:
        return clean_text(match.group(1))
    return branch or clean_text(fallback)


def sasang_branch_address(branch: str, room: str) -> str:
    text = clean_text(" ".join(part for part in [branch, room] if part))
    address_map = {
        "주례어린이도서관": "부산광역시 사상구 주례로 110",
        "평생학습관": "부산광역시 사상구 학감대로 242",
        "생활사박물관": "부산광역시 사상구 낙동대로1258번길 36",
        "보건소": "부산광역시 사상구 학감대로 242",
        "사상도서관": "부산광역시 사상구 덕상로 2번길 9",
    }
    for name, address in address_map.items():
        if name in text:
            return address
    return ""


def sasang_page_url(parsed: Any, base_query: dict[str, list[str]], page: int) -> str:
    query = dict(base_query)
    query["pageIndex"] = [str(page)]
    return parsed._replace(query=urlencode(query, doseq=True)).geturl()


def collect_sasang_apply_list(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 0,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    if not parsed.path.endswith("/user/apply/list.sasang"):
        parsed = urlparse(SASANG_APPLY_LIST_URL)
        base_query = parse_qs(parsed.query)
    if not clean_text((base_query.get("searchStartDate") or [""])[0]):
        today = datetime.now().date()
        base_query["searchDateType"] = ["eduDate"]
        base_query["searchStartDate"] = [today.isoformat()]
        base_query["searchEndate"] = [(today + timedelta(days=370)).isoformat()]
    pagination_detected = False
    detail_pages = 0
    total_count = 0
    for page in range(1, max_pages + 1):
        current_url = sasang_page_url(parsed, base_query, page)
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        board_text = clean_text(soup.select_one(".boardPage").get_text(" ", strip=True) if soup.select_one(".boardPage") else "")
        count_match = re.search(r"珥앷쾶?쒕Ъ\s*:\s*(\d+)", board_text.replace(",", ""))
        if count_match:
            total_count = max(total_count, int(count_match.group(1)))
        page_rows = 0
        for item in soup.select(".bbs_edu > ul > li"):
            title_node = item.select_one(".tit a")
            title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
            if not title or is_low_value_title(title):
                continue
            category = clean_text((item.select_one(".divKind") or item).get_text(" ", strip=True))
            target_text = clean_text((item.select_one(".divPart") or item).get_text(" ", strip=True))
            status = clean_text((item.select_one(".stat") or item).get_text(" ", strip=True))
            pairs = labeled_pairs_from_named_spans(item, "span.name")
            onclick = clean_text(title_node.get("onclick") if title_node else "")
            call = re.search(r"url_chk\((.*?)\)", onclick)
            raw_url = current_url
            if call:
                args = re.findall(r"'([^']*)'", call.group(1))
                if len(args) >= 3:
                    raw_url = normalize_link(
                        current_url,
                        f"/user/apply/view.sasang?menuCd={args[0]}&couIdx={args[1]}&pageIndex={args[2]}",
                    )
            capacity_current, capacity_total = parse_capacity_pair(pairs.get("모집인원"))
            schedule = clean_text(pairs.get("시간"))
            material_fee = extract_material_fee_amount(schedule)
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, pairs.get("운영기관") or target.branch),
                "title": title,
                "branch": clean_text(pairs.get("운영기관")) or target.branch,
                "branch_url": parsed._replace(query=urlencode(base_query, doseq=True)).geturl(),
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url if status in {"접수중", "접수대기"} else "",
                "status": status,
                "fee": "",
                "material_fee": material_fee,
                "period": normalize_mixed_date_range(pairs.get("수강기간", "") or pairs.get("교육기간", "")),
                "apply_period": normalize_mixed_date_range(pairs.get("접수일시", "") or pairs.get("접수기간", "")),
                "schedule_raw": schedule,
                "target": target_text,
                "room": clean_text(pairs.get("장소")),
                "venue_name": clean_text(pairs.get("장소")),
                "preserve_branch": True,
                "capacity": capacity_total,
                "capacity_current": capacity_current,
                "application_method_raw": clean_text(pairs.get("접수방법")),
                "description": clean_text(item.get_text(" ", strip=True)),
                "collection_category": "怨듦났?덉빟",
                "domain_category": "怨듦났?덉빟",
                "source_group": "public_reservation",
                "operator_type": "吏?먯껜/怨듦났湲곌?",
                "collection_type": "static_html",
                "raw_fields": {"pairs": pairs, "parser": "sasang_apply_list", "onclick": onclick},
            }
            if detail_limit > 0 and detail_pages < detail_limit and raw_url:
                try:
                    detail = sasang_detail_fields(s, raw_url, timeout)
                    detail_pages += 1
                    detail_branch = sasang_prefer_branch(detail.get("branch", ""), detail.get("venue_name", ""), row["branch"])
                    detail_address = sasang_branch_address(detail_branch, detail.get("venue_name", ""))
                    row.update(
                        {
                            "title": detail.get("title") or row["title"],
                            "branch": detail_branch,
                            "address": detail_address,
                            "category": detail.get("category") or row["category"],
                            "status": detail.get("status") or row["status"],
                            "fee": detail.get("fee") or row["fee"],
                            "material_fee": detail.get("material_fee") or row["material_fee"],
                            "material_note": detail.get("material_note") or "",
                            "period": detail.get("period") or row["period"],
                            "apply_period": detail.get("apply_period") or row["apply_period"],
                            "schedule_raw": detail.get("schedule_raw") or row["schedule_raw"],
                            "target": detail.get("target") or row["target"],
                            "room": detail.get("room") or row["room"],
                            "venue_name": detail.get("venue_name") or row["venue_name"],
                            "venue_address": detail_address,
                            "capacity": detail.get("capacity_total") or row["capacity"],
                            "capacity_total": detail.get("capacity_total") or "",
                            "capacity_current": detail.get("capacity_current") or row["capacity_current"],
                            "waitlist_total": detail.get("waitlist_total") or "",
                            "application_method_raw": detail.get("application_method_raw") or row["application_method_raw"],
                            "phone": detail.get("phone") or "",
                            "instructor": detail.get("instructor") or "",
                            "description": detail.get("description") or row["description"],
                        }
                    )
                    row["provider_course_id"] = stable_course_id(target.provider, raw_url, row["title"], row["branch"])
                    row["raw_fields"] = {
                        "pairs": pairs,
                        "detail_pairs": detail.get("raw_detail_pairs") or {},
                        "detail_sections": detail.get("raw_detail_sections") or {},
                        "parser": "sasang_apply_list+detail",
                        "onclick": onclick,
                    }
                except Exception as exc:
                    logger.debug("Sasang detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".boardPage, .pagination, .paging, .page"))
        if page_rows == 0:
            break
        if total_count and page * 8 >= total_count:
            break
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "total_count": total_count,
    }
    parser_name = "sasang_apply_list+detail" if detail_pages else "sasang_apply_list"
    return dedupe_rows(rows), parser_name, meta


def yangju_page_url(parsed: Any, base_query: dict[str, list[str]], page: int) -> str:
    query = dict(base_query)
    query["pageIndex"] = [str(page)]
    return parsed._replace(query=urlencode(query, doseq=True)).geturl()


def yangju_split_period_cell(value: Any) -> tuple[str, str]:
    text = clean_text(value)
    apply_period = ""
    course_period = ""
    apply_match = re.search(r"접수\s*[:：]?\s*(.*?)(?=\s*교육\s*[:：]?|$)", text)
    course_match = re.search(r"교육\s*[:：]?\s*(.+)$", text)
    if apply_match:
        apply_period = normalize_mixed_date_range(apply_match.group(1))
    if course_match:
        course_period = normalize_mixed_date_range(course_match.group(1))
    return apply_period, course_period


def yangju_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in soup.select(".education_request li.clearfix"):
        key = clean_text(item.select_one("em").get_text(" ", strip=True) if item.select_one("em") else "")
        value_node = item.select_one("p")
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if key:
            pairs[key] = value
    return pairs


def yangju_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    scope = soup.select_one(".education_request") or soup
    pairs = yangju_detail_pairs(scope)
    title = clean_text(scope.select_one(".titlebox .title").get_text(" ", strip=True) if scope.select_one(".titlebox .title") else "")
    status = clean_text(scope.select_one(".titlebox .state").get_text(" ", strip=True) if scope.select_one(".titlebox .state") else "")
    apply_url = ""
    apply_link = scope.select_one('a[href*="selectEduApplcntAgreView"]')
    if apply_link:
        apply_url = normalize_link(url, apply_link.get("href"))
    description_parts = []
    for key in ("강의개요", "유의사항"):
        value = pairs.get(key)
        if value:
            description_parts.append(f"{key}: {value}")
    material_note = clean_text(pairs.get("교재 및 참고자료"))
    capacity_current, capacity_total = parse_capacity_pair(pairs.get("모집인원"))
    waitlist_total = None
    waitlist_match = re.search(r"대기\s*[:：]?\s*(?:\d{1,5}\s*/\s*)?(\d{1,5})", pairs.get("모집인원", ""))
    if waitlist_match:
        waitlist_total = int(waitlist_match.group(1))
    return {
        "title": title,
        "branch": clean_text(pairs.get("교육기관")),
        "venue_name": clean_text(pairs.get("교육장소")),
        "room": clean_text(pairs.get("강의실")) or clean_text(pairs.get("교육장소")),
        "category": clean_text(pairs.get("교육과정")),
        "target": clean_text(pairs.get("교육대상")),
        "status": status,
        "fee": clean_text(pairs.get("수강료")),
        "material_note": material_note,
        "material_fee": extract_material_fee_amount(material_note),
        "apply_period": normalize_mixed_date_range(pairs.get("접수일시", "") or pairs.get("접수기간", "")),
        "period": normalize_mixed_date_range(pairs.get("수강기간", "") or pairs.get("교육기간", "")),
        "weekday": clean_text(pairs.get("교육요일")),
        "capacity_total": capacity_total,
        "capacity_current": capacity_current,
        "waitlist_total": waitlist_total,
        "instructor": clean_instructor_name(pairs.get("강사명")),
        "phone": clean_text(pairs.get("전화번호")),
        "application_url": apply_url,
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "description": clean_text(" ".join(description_parts)),
        "raw_detail_pairs": pairs,
    }


YANGJU_BRANCH_ADDRESSES = {
    "장흥자생수목원": "경기도 양주시 장흥면 권율로 83",
    "양주시청": "경기도 양주시 부흥로 1533",
    "양주시립민복진미술관": "경기도 양주시 장흥면 권율로 192",
    "임시환경사업소": "경기도 양주시 평화로 1920",
    "양주시속편한일자리센터": "경기도 양주시 광적면 지섬로 162",
}


def yangju_branch_address(branch: Any) -> str:
    branch_text = clean_text(branch)
    for key, address in YANGJU_BRANCH_ADDRESSES.items():
        if key in branch_text:
            return address
    return ""


def collect_yangju_edu_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 0,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    discovered_links = 0
    pagination_detected = False
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    detail_budget = max(detail_limit, 100) if detail_limit > 0 else 0
    for page in range(1, max_pages + 1):
        current_url = yangju_page_url(parsed, base_query, page)
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .page"))
        table = soup.select_one("table.list_table") or soup.select_one("table")
        if not table:
            break
        page_rows = 0
        for tr in table.select("tbody tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
            if len(cells) < 8:
                continue
            title_link = tr.select_one('a[href*="eduLctreWebView"]')
            title = clean_text(title_link.get_text(" ", strip=True) if title_link else cells[1])
            if not title or is_low_value_title(title):
                continue
            raw_url = normalize_link(current_url, title_link.get("href") if title_link else None) or current_url
            apply_link = tr.select_one('a[href*="selectEduApplcntAgreView"]')
            apply_url = normalize_link(current_url, apply_link.get("href") if apply_link else None)
            apply_period, course_period = yangju_split_period_cell(cells[3])
            _, course_end = parse_date_range(course_period)
            if course_end and course_end < datetime.now().date():
                continue
            capacity_current, capacity_total = parse_capacity_pair(cells[5])
            waitlist_total = None
            waitlist_match = re.search(r"대기\s*[:：]?\s*\(?\s*\d{1,5}\s*/\s*(\d{1,5})", cells[5])
            if waitlist_match:
                waitlist_total = int(waitlist_match.group(1))
            status = cells[7]
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "branch_url": current_url,
                "category": "",
                "raw_url": raw_url,
                "application_url": apply_url if status in {"접수중", "접수대기"} else "",
                "reservation_available": status in {"접수중", "접수대기"},
                "status": status,
                "fee": cells[6],
                "period": course_period,
                "apply_period": apply_period,
                "schedule_raw": cells[4],
                "target": "",
                "capacity": cells[5],
                "capacity_total": capacity_total,
                "capacity_current": capacity_current,
                "waitlist_total": waitlist_total,
                "application_method_raw": cells[2],
                "collection_category": "공공예약",
                "domain_category": "공공예약",
                "source_group": "public_reservation",
                "operator_type": "지자체/공공기관",
                "collection_type": "static_html",
                        "program_type": "\uAC15\uC88C",
                "preserve_branch": True,
                "raw_fields": {
                    "list_cells": cells,
                    "parser": "yangju_edu_lecture_list",
                },
            }
            if detail_budget > 0 and detail_pages < detail_budget and raw_url:
                try:
                    detail = yangju_detail_fields(s, raw_url, timeout)
                    detail_pages += 1
                    detail_branch = detail.get("branch") or row["branch"]
                    detail_address = yangju_branch_address(detail_branch)
                    row.update(
                        {
                            "title": detail.get("title") or row["title"],
                            "branch": detail_branch,
                            "address": detail_address,
                            "venue_address": detail_address,
                            "venue_name": detail.get("venue_name") or detail_branch,
                            "room": detail.get("room") or "",
                            "category": detail.get("category") or row["category"],
                            "target": detail.get("target") or row["target"],
                            "status": detail.get("status") or row["status"],
                            "fee": detail.get("fee") or row["fee"],
                            "material_note": detail.get("material_note") or "",
                            "material_fee": detail.get("material_fee") or "",
                            "period": detail.get("period") or row["period"],
                            "apply_period": detail.get("apply_period") or row["apply_period"],
                            "capacity_total": detail.get("capacity_total") or row["capacity_total"],
                            "capacity_current": row.get("capacity_current") or detail.get("capacity_current"),
                            "waitlist_total": detail.get("waitlist_total") or row["waitlist_total"],
                            "instructor": detail.get("instructor") or "",
                            "phone": detail.get("phone") or "",
                            "application_url": detail.get("application_url") or row["application_url"],
                            "application_method_raw": detail.get("application_method_raw") or row["application_method_raw"],
                            "description": detail.get("description") or "",
                        }
                    )
                    if detail.get("weekday") and detail["weekday"] not in row["schedule_raw"]:
                        row["schedule_raw"] = clean_text(f"{detail['weekday']} {row['schedule_raw']}")
                    row["provider_course_id"] = stable_course_id(target.provider, raw_url, row["title"], row["branch"])
                    row["raw_fields"] = {
                        "list_cells": cells,
                        "detail_pairs": detail.get("raw_detail_pairs") or {},
                        "parser": "yangju_edu_lecture_list+detail",
                    }
                except Exception as exc:
                    logger.debug("Yangju detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
            discovered_links += 1
        if page_rows == 0:
            break
    parser_name = "yangju_edu_lecture_list+detail" if detail_pages else "yangju_edu_lecture_list"
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": discovered_links,
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), parser_name, meta


def collect_daejeon_donggu_edu(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    parsed = urlparse(target.url)
    if not parsed.path.endswith("/selectUserEduList.do"):
        parsed = urlparse("https://www.donggu.go.kr/lll/www/selectUserEduList.do?key=733&pageUnit=20")
    base_query = parse_qs(parsed.query)
    pagination_detected = False
    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["page"] = [str(page)]
        query.setdefault("pageUnit", ["20"])
        current_url = parsed._replace(path="/lll/www/selectUserEduList.do", query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table.edu_list_table tbody tr"):
            cells = tr.find_all("td")
            if len(cells) < 7:
                continue
            title_node = tr.select_one(".edu_tit")
            title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
            if not title or is_low_value_title(title):
                continue
            onclick = clean_text((tr.find("a", onclick=True) or {}).get("onclick"))
            id_match = re.search(r"fn_goView\(['\"]?(\d+)", onclick)
            sch_id = id_match.group(1) if id_match else ""
            detail_query = dict(query)
            if sch_id:
                detail_query["schId"] = [sch_id]
            raw_url = parsed._replace(path="/lll/www/selectUserEduView.do", query=urlencode(detail_query, doseq=True)).geturl()
            location = clean_text((cells[1].find_all("span")[-1].get_text(" ", strip=True) if cells[1].find_all("span") else ""))
            branch = clean_text(cells[2].get_text(" ", strip=True)) or target.branch
            target_text = re.sub(r"^모집대상\s*[:：]?\s*", "", clean_text(cells[3].get_text(" ", strip=True)))
            date_pairs = labeled_pairs_from_named_spans(cells[4], "em")
            capacity_current, capacity_total = parse_capacity_pair(cells[5].get_text(" ", strip=True))
            fee = clean_text(cells[6].get_text(" ", strip=True)).replace("수강료", "").strip()
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": clean_text(cells[0].get_text(" ", strip=True)),
                "fee": fee,
                "period": normalize_yymmdd_range(date_pairs.get("교육기간", "")),
                "apply_period": normalize_yymmdd_range(date_pairs.get("신청기간", "")),
                "schedule_raw": "",
                "target": target_text,
                "room": location,
                "venue_name": location,
                "capacity": capacity_total,
                "capacity_current": capacity_current,
                "description": clean_text(tr.get_text(" ", strip=True)),
                "raw_fields": {"parser": "daejeon_donggu_edu", "sch_id": sch_id, "date_pairs": date_pairs},
            }
            if raw_url and detail_pages < 30:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    detail_pairs = pairs_from_tables(detail_soup)
                    detail_capacity_current, detail_capacity_total = parse_capacity_pair(detail_pairs.get("접수인원"))
                    row["category"] = clean_text(detail_pairs.get("강의분류"))
                    row["target"] = clean_text(detail_pairs.get("교육대상")) or row["target"]
                    row["status"] = status_from_lines(lines_from_soup(detail_soup)) or row["status"]
                    row["period"] = normalize_mixed_date_range(detail_pairs.get("교육기간", "")) or row["period"]
                    row["apply_period"] = normalize_mixed_date_range(detail_pairs.get("신청기간", "")) or row["apply_period"]
                    row["schedule_raw"] = clean_text(detail_pairs.get("교육시간"))
                    row["room"] = clean_text(detail_pairs.get("교육장소")) or row["room"]
                    row["venue_name"] = row["room"]
                    row["venue_address"] = clean_text(re.sub(r"^\[[^\]]+\]\s*", "", detail_pairs.get("교육장소주소", "")))
                    row["capacity"] = detail_capacity_total or row["capacity"]
                    row["capacity_current"] = detail_capacity_current or row["capacity_current"]
                    row["target_age_raw"] = clean_text(detail_pairs.get("수강가능연령"))
                    row["material_note"] = clean_text(detail_pairs.get("재료비설명"))
                    row["instructor"] = clean_instructor_name(detail_pairs.get("강사"))
                    row["description"] = clean_text(detail_pairs.get("강의내용") or detail_soup.get_text(" ", strip=True))[:1200]
                    row["raw_fields"] = {
                        "parser": "daejeon_donggu_edu",
                        "sch_id": sch_id,
                        "date_pairs": date_pairs,
                        "detail_pairs": detail_pairs,
                    }
                except Exception as exc:
                    logger.debug("Daejeon Donggu detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='fn_egov_link_page']"))
        if page_rows == 0:
            break
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "daejeon_donggu_edu", meta


def collect_bupyeong_lecture_list(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    parsed = urlparse(target.url)
    if not parsed.path.endswith("/lecturelll/lectureList.do"):
        parsed = urlparse("https://www.icbp.go.kr/lecturelll/lectureList.do?sitediv=lll&cd=lll")
    base_query = parse_qs(parsed.query)
    pagination_detected = False
    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["nowPage"] = [str(page)]
        current_url = parsed._replace(path="/lecturelll/lectureList.do", query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for item in soup.select(".lecList > li"):
            link = item.select_one(".tit a[href]")
            title = clean_text(link.get_text(" ", strip=True) if link else "")
            title = re.sub(r"^접수마감", "", title).strip()
            if not title or is_low_value_title(title):
                continue
            pairs = labeled_pairs_from_named_spans(item, "span.wfont")
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": clean_text((item.select_one(".tag_state") or item).get_text(" ", strip=True)),
                "fee": "",
                "material_fee": "",
                "period": normalize_mixed_date_range(pairs.get("수강기간", "") or pairs.get("교육기간", "")),
                "apply_period": normalize_mixed_date_range(pairs.get("접수일시", "") or pairs.get("접수기간", "")),
                "schedule_raw": "",
                "target": "",
                "room": clean_text(pairs.get("교육장소")),
                "venue_name": clean_text(pairs.get("교육장소")),
                "description": clean_text(item.get_text(" ", strip=True)),
                "raw_fields": {"parser": "bupyeong_lecture_list", "pairs": pairs},
            }
            if raw_url and detail_pages < 30:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    detail_pairs = pairs_from_definition_lists(detail_soup)
                    period, schedule = split_period_and_schedule(detail_pairs.get("교육기간", ""))
                    fee_text = clean_text(detail_pairs.get("수강료"))
                    material_match = re.search(r"재료비\s*[:：]?\s*([^)]+)", fee_text)
                    row["target"] = clean_text(detail_pairs.get("교육대상"))
                    row["fee"] = clean_text(re.split(r"\(?재료비", fee_text)[0])
                    row["material_fee"] = clean_text(material_match.group(1)) if material_match else row["material_fee"]
                    row["period"] = period or row["period"]
                    row["schedule_raw"] = schedule
                    row["apply_period"] = normalize_mixed_date_range(detail_pairs.get("접수기간", "")) or row["apply_period"]
                    row["room"] = clean_text(detail_pairs.get("교육장소")) or row["room"]
                    row["venue_name"] = row["room"]
                    row["capacity"] = clean_text(detail_pairs.get("신청정원"))
                    row["application_method_raw"] = clean_text(detail_pairs.get("접수방법"))
                    row["instructor"] = clean_instructor_name(detail_pairs.get("강사"))
                    image = detail_soup.select_one(".photo img")
                    row["image_url"] = normalize_link(raw_url, image.get("src") if image else None)
                    row["description"] = clean_text(detail_pairs.get("안내") or detail_soup.get_text(" ", strip=True))[:1200]
                    row["raw_fields"] = {"parser": "bupyeong_lecture_list", "pairs": pairs, "detail_pairs": detail_pairs}
                except Exception as exc:
                    logger.debug("Bupyeong detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='nowPage=']"))
        if page_rows == 0:
            break
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "bupyeong_lecture_list", meta


def collect_ulsan_yes_lecture(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, "https://yes.ulsan.go.kr/lecture", timeout=timeout)
    rows: list[dict[str, Any]] = []
    for item in soup.select(".content_wrap"):
        title_node = item.select_one("h4.blue")
        status_node = title_node.select_one(".ing") if title_node else None
        status = clean_text(status_node.get_text(" ", strip=True) if status_node else "")
        if status_node:
            status_node.extract()
        title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
        if not title or is_low_value_title(title):
            continue
        branch = clean_text((item.select_one(".list_tit h4") or item).get_text(" ", strip=True)) or target.branch
        pairs: dict[str, str] = {}
        for li in item.select("ul.list li"):
            text = clean_text(li.get_text(" ", strip=True))
            if ":" not in text:
                continue
            key, value = text.split(":", 1)
            pairs[normalize_korean_label(key)] = clean_text(value)
        link = item.select_one(".reservation a[href]")
        raw_url = normalize_link(target.url, link.get("href") if link else None) or target.url
        schedule_text = clean_text(pairs.get("교육시간"))
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "fee": clean_text(pairs.get("수강료")),
                "period": normalize_yymmdd_range(schedule_text),
                "apply_period": "",
                "schedule_raw": schedule_text,
                "target": clean_text(pairs.get("교육대상")),
                "capacity": clean_text(pairs.get("정원")),
                "application_method_raw": clean_text(pairs.get("접수방법")),
                "contact": clean_text(pairs.get("문의처")),
                "description": clean_text(item.get_text(" ", strip=True)),
                "raw_fields": {"parser": "ulsan_yes_lecture", "pairs": pairs},
            }
        )
    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": bool(soup.select(".pagination, .paging")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ulsan_yes_lecture", meta


ULSAN_BUKGU_LECTURE_URL = "https://crs.ubimc.or.kr/yeyak/new_lecture/lecture"
ULSAN_BUKGU_BRANCH = "울산북구공공시설예약서비스"


def ulsan_bukgu_branch_code(url: str) -> str:
    params = parse_qs(urlparse(url).query)
    return clean_text((params.get("mem_id") or [""])[0])


def ulsan_bukgu_facility_links(soup: BeautifulSoup, base_url: str) -> list[tuple[str, str]]:
    links: list[tuple[str, str]] = []
    seen: set[str] = set()
    for link in soup.select("a[href*='new_lecture/lecture'][href*='mem_id=']"):
        absolute = normalize_link(base_url, link.get("href"))
        branch_code = ulsan_bukgu_branch_code(absolute)
        if not absolute or not branch_code or branch_code in seen:
            continue
        branch = clean_text(link.get_text(" ", strip=True)) or branch_code
        links.append((branch, absolute))
        seen.add(branch_code)
    return links


def ulsan_bukgu_subject_pairs(subject: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in subject.select("p"):
        label_node = item.select_one("span")
        if not label_node:
            continue
        label_text = clean_text(label_node.get_text(" ", strip=True)).rstrip(":：")
        value = clean_text(item.get_text(" ", strip=True).replace(label_node.get_text(" ", strip=True), "", 1))
        value = clean_text(value.lstrip(":："))
        if label_text:
            pairs[normalize_korean_label(label_text)] = value
    return pairs


def ulsan_bukgu_fee_text(node: BeautifulSoup | None) -> str:
    text = clean_text(node.get_text(" ", strip=True) if node else "")
    if not text:
        return ""
    if re.search(r"\d[\d,]*\s*원", text) or "무료" in text:
        return text
    match = re.search(r"\d[\d,]*", text)
    return f"{match.group(0)}원" if match else text


def ulsan_bukgu_table_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for row in soup.select("table.table_st2 tr"):
        header = clean_text((row.select_one("th") or "").get_text(" ", strip=True) if row.select_one("th") else "")
        value = clean_text((row.select_one("td") or "").get_text(" ", strip=True) if row.select_one("td") else "")
        if header:
            pairs[normalize_korean_label(header)] = value
    return pairs


def collect_ulsan_bukgu_detail(s: requests.Session, raw_url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, raw_url, timeout=timeout)
    pairs = ulsan_bukgu_table_pairs(soup)
    info_text = clean_text((soup.select_one(".info_area") or "").get_text(" ", strip=True) if soup.select_one(".info_area") else "")
    address = ""
    contact = ""
    address_match = re.search(r"주소\s*[:：]\s*(.*?)(?=문의전화\s*[:：]|$)", info_text)
    if address_match:
        address = clean_text(address_match.group(1))
    contact_match = re.search(r"문의전화\s*[:：]\s*([0-9-]+)", info_text)
    if contact_match:
        contact = clean_text(contact_match.group(1))
    room = clean_text((soup.select_one(".info_area .s_tit2") or "").get_text(" ", strip=True) if soup.select_one(".info_area .s_tit2") else "")
    status = ""
    status_match = re.search(r"(접수\s*준비중|접수중|접수마감|강습중|마감|폐강)[^.\n]*", soup.get_text("\n", strip=True))
    if status_match:
        status = clean_text(status_match.group(0))
    description = clean_text((soup.select_one(".tab_cont#tab2") or "").get_text(" ", strip=True) if soup.select_one(".tab_cont#tab2") else "")
    image_url = ""
    image = soup.select_one(".photo_cont img[src]")
    if image:
        candidate = normalize_link(raw_url, image.get("src"))
        if candidate and "noimage" not in candidate.lower():
            image_url = candidate
    return {
        "target": clean_text(pairs.get("강습대상")),
        "capacity": clean_text(pairs.get("정원")),
        "apply_period": normalize_yymmdd_range(pairs.get("신규회원모집기간", "")),
        "period": normalize_yymmdd_range(pairs.get("강습기간", "")),
        "schedule_raw": clean_text(pairs.get("강습시간")),
        "fee": ulsan_bukgu_fee_text(soup.select_one("table.table_st2 td .t_orange") or soup.select_one("table.table_st2 td")),
        "instructor": clean_text(pairs.get("강사")),
        "venue_name": room,
        "room": room,
        "venue_address": address,
        "address": address,
        "contact": contact,
        "status": status,
        "description": description,
        "image_url": image_url,
        "raw_fields": {"detail_parser": "ulsan_bukgu_lecture_detail", "detail_pairs": pairs},
    }


def collect_ulsan_bukgu_lecture(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    first_url = target.url if "/new_lecture/lecture" in urlparse(target.url).path else ULSAN_BUKGU_LECTURE_URL
    first_soup = fetch_soup(s, first_url, timeout=timeout)
    facility_links = ulsan_bukgu_facility_links(first_soup, first_url)
    if not facility_links:
        facility_links = [(target.branch or ULSAN_BUKGU_BRANCH, first_url)]

    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = len(facility_links) > 1
    for branch, list_url in facility_links[: max(1, max_pages)]:
        soup = first_soup if pages == 0 and list_url == first_url else fetch_soup(s, list_url, timeout=timeout)
        pages += 1
        branch_code = ulsan_bukgu_branch_code(list_url) or re.sub(r"[^A-Za-z0-9가-힣]+", "_", branch).strip("_")[:50]
        for row_node in soup.select("table.table_list tbody tr"):
            subject = row_node.select_one("td.subject")
            link = subject.select_one("a[href]") if subject else row_node.select_one("a[href]")
            raw_url = normalize_link(list_url, link.get("href") if link else None) or list_url
            title = clean_text((subject.select_one("p.tit") if subject else None).get_text(" ", strip=True) if subject and subject.select_one("p.tit") else "")
            title = title or clean_text(link.get_text(" ", strip=True) if link else "")
            if not title or is_low_value_title(title):
                continue
            pairs = ulsan_bukgu_subject_pairs(subject) if subject else {}
            status = clean_text((row_node.select_one("td.state") or "").get_text(" ", strip=True) if row_node.select_one("td.state") else "")
            status = status or clean_text((row_node.select_one("td.person") or "").get_text(" ", strip=True) if row_node.select_one("td.person") else "")
            reservation_available = "접수중" in status and "마감" not in status
            period = normalize_yymmdd_range(pairs.get("강습기간", ""))
            schedule = clean_text(pairs.get("강습시간"))
            category = clean_text((row_node.select_one("td.devide") or "").get_text(" ", strip=True) if row_node.select_one("td.devide") else "")
            fee = ulsan_bukgu_fee_text(row_node.select_one("td.pay"))
            description = clean_text(row_node.get_text(" ", strip=True))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "branch_code": branch_code,
                    "preserve_branch": True,
                    "category": category,
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "application_type": "ONLINE_RESERVATION",
                    "reservation_available": reservation_available,
                    "status": status,
                    "fee": fee,
                    "period": period,
                    "apply_period": "",
                    "schedule_raw": schedule,
                    "target": "",
                    "capacity": "",
                    "program_type": "강좌",
                    "description": description,
                    "domain_category": clean_text(target.extra.get("domain_category") or "공공예약"),
                    "collection_category": clean_text(target.extra.get("collection_category") or "공공예약"),
                    "source_group": clean_text(target.extra.get("source_group") or "public_reservation"),
                    "operator_type": clean_text(target.extra.get("operator_type") or "지자체/공공기관"),
                    "collection_type": "static_html+detail_html",
                    "raw_fields": {
                        "parser": "ulsan_bukgu_lecture_list",
                        "list_url": list_url,
                        "pairs": pairs,
                    },
                }
            )

    detail_pages = 0
    for row in rows[: max(0, detail_limit)]:
        raw_url = clean_text(row.get("raw_url"))
        if not raw_url or raw_url == clean_text(row.get("list_url")):
            continue
        try:
            row.update(merge_course_rows(row, collect_ulsan_bukgu_detail(s, raw_url, timeout=timeout)))
            detail_pages += 1
        except Exception as exc:
            logger.debug("Ulsan Bukgu detail fetch failed %s: %s", raw_url, exc)

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(facility_links),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ulsan_bukgu_lecture_list+detail", meta


ULSAN_EDU_BOOKING_LIST_URL = "https://use.go.kr/booking/user/reservation/Edu/BD_selectReservationMngList.do"
ULSAN_EDU_BOOKING_DETAIL_URL = "https://use.go.kr/booking/user/reservation/Edu/BD_selectReservationMng.do"


def normalize_ulsan_booking_datetime_range(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""

    def repl(match: re.Match[str]) -> str:
        year = int(match.group(1))
        month = int(match.group(2))
        day = int(match.group(3))
        time_text = clean_text(match.group(4))
        return f"{year:04d}-{month:02d}-{day:02d}" + (f" {time_text}" if time_text else "")

    text = re.sub(r"(\d{4})\s*년\s*(\d{1,2})\s*월\s*(\d{1,2})\s*일\s*(\d{1,2}:\d{2})?", repl, text)
    text = re.sub(r"\s+-\s+", " ~ ", text)
    return clean_text(text)


def ulsan_booking_info_pairs(item: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in item.select("ul.info > li"):
        label_node = li.select_one(".tit")
        if not label_node:
            continue
        label_text = clean_text(label_node.get_text(" ", strip=True))
        value = clean_text(li.get_text(" ", strip=True).replace(label_text, "", 1))
        if label_text:
            pairs[label_text] = value
    return pairs


def parse_ulsan_booking_onclick(onclick: Any) -> str:
    text = clean_text(onclick)
    match = re.search(r"opViewReservation\(\s*'([^']+)'", text)
    return clean_text(match.group(1)) if match else ""


def extract_ulsan_detail_section(text: str) -> str:
    lines = [clean_text(line) for line in text.splitlines() if clean_text(line)]
    stop_labels = {"위치정보", "유의사항", "예약현황", "목록", "TOP"}
    for index, line in enumerate(lines):
        if line == "소개":
            values: list[str] = []
            for value in lines[index + 1 :]:
                if value in stop_labels:
                    break
                values.append(value)
            return clean_text(" ".join(values))
    return ""


def collect_ulsan_booking_detail(
    s: requests.Session,
    raw_url: str,
    timeout: int,
) -> dict[str, Any]:
    response = s.get(raw_url, verify=False, timeout=timeout)
    response.raise_for_status()
    if not response.encoding or response.encoding.lower() == "iso-8859-1":
        response.encoding = response.apparent_encoding
    soup = BeautifulSoup(response.text, "lxml")
    text = soup.get_text("\n", strip=True)
    description = extract_ulsan_detail_section(text)
    material_note = ""
    if description:
        material_lines = [
            clean_text(part)
            for part in re.split(r"[.\n]", description)
            if any(keyword in part for keyword in ("준비물", "재료", "재료비", "교재비"))
        ]
        material_note = clean_text(" ".join(material_lines))
    image_url = ""
    for image in soup.select("img"):
        src = clean_text(image.get("src"))
        if not src or "logo" in src.lower() or "footer" in src.lower() or "banner" in src.lower():
            continue
        candidate = normalize_link(raw_url, src)
        if candidate:
            image_url = candidate
            break
    return {
        "description": description,
        "material_note": material_note,
        "image_url": image_url,
        "raw_fields": {"detail_parser": "ulsan_edu_booking_detail", "detail_text_sample": clean_text(text)[:1000]},
    }


def collect_ulsan_edu_booking(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False

    for page in range(1, max_pages + 1):
        response = s.get(
            ULSAN_EDU_BOOKING_LIST_URL,
            params={"type": "Edu", "q_currPage": str(page)},
            verify=False,
            timeout=timeout,
        )
        response.raise_for_status()
        if not response.encoding or response.encoding.lower() == "iso-8859-1":
            response.encoding = response.apparent_encoding
        soup = BeautifulSoup(response.text, "lxml")
        pages += 1
        items = soup.select(".prgr-booking-list ul.list > li.item")
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[onclick*='opMovePage']"))
        page_rows = 0
        for item in items:
            link = item.select_one("a[onclick*='opViewReservation']")
            reservation_id = parse_ulsan_booking_onclick(link.get("onclick") if link else "")
            title = clean_text((item.select_one(".tit_wrap .title") or item).get_text(" ", strip=True))
            if not reservation_id or not title or is_low_value_title(title):
                continue
            pairs = ulsan_booking_info_pairs(item)
            status = clean_text((item.select_one(".tit_wrap .status") or "").get_text(" ", strip=True) if item.select_one(".tit_wrap .status") else "")
            branch = clean_text(pairs.get("기관")) or target.branch
            apply_period = normalize_ulsan_booking_datetime_range(pairs.get("신청기간"))
            period = normalize_ulsan_booking_datetime_range(pairs.get("운영기간"))
            venue = clean_text(pairs.get("장소"))
            raw_url = ULSAN_EDU_BOOKING_DETAIL_URL + "?" + urlencode({"q_rsvtRegSn": reservation_id})
            image = item.select_one("img")
            image_url = normalize_link(ULSAN_EDU_BOOKING_LIST_URL, image.get("src") if image else None)
            row = {
                "provider": target.provider,
                "provider_course_id": reservation_id,
                "title": title,
                "branch": branch,
                "branch_code": branch,
                "category": "평생교육",
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "fee": "",
                "period": period,
                "apply_period": apply_period,
                "schedule_raw": period,
                "target": clean_text(pairs.get("대상") or pairs.get("교육대상") or pairs.get("이용대상")),
                "capacity": clean_text(pairs.get("모집인원")),
                "venue_name": venue,
                "venue_address": venue if re.search(r"\(\d{5}\)|[가-힣]+(?:로|길)\s*\d+", venue) else "",
                "contact": clean_text(pairs.get("문의전화")),
                "application_method_raw": clean_text(pairs.get("접수방법") or pairs.get("신청방법") or pairs.get("접수구분")),
                "image_url": image_url,
                "description": clean_text(item.get_text(" ", strip=True)),
                "domain_category": clean_text(target.extra.get("domain_category") or "평생학습"),
                "collection_category": clean_text(target.extra.get("collection_category") or "평생학습"),
                "source_group": clean_text(target.extra.get("source_group") or "lifelong_learning"),
                "operator_type": clean_text(target.extra.get("operator_type") or "지자체/공공기관"),
                "collection_type": clean_text(target.extra.get("collection_type") or "static_html"),
                "raw_fields": {"parser": "ulsan_edu_booking_list", "pairs": pairs, "reservation_id": reservation_id},
            }
            rows.append(row)
            page_rows += 1
        if page_rows == 0 or not soup.select(f"a[onclick*='opMovePage({page + 1})']"):
            break

    detail_pages = 0
    if detail_limit > 0:
        for row in rows[:detail_limit]:
            try:
                detail = collect_ulsan_booking_detail(s, clean_text(row.get("raw_url")), timeout=timeout)
            except Exception as exc:
                logger.debug("ulsan edu booking detail fetch failed %s: %s", row.get("provider_course_id"), exc)
                continue
            detail_raw = detail.pop("raw_fields", {})
            row.setdefault("raw_fields", {}).update(detail_raw)
            for key, value in detail.items():
                if value:
                    row[key] = value
            detail_pages += 1

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ulsan_edu_booking_list+detail", meta


MOKPO_LIFELONG_LIST_URL = "https://lifelong.mokpo.go.kr/lecture/lecture_list_program.php?me_id=sub222"


def collect_mokpo_lifelong_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    list_url = target.url
    parsed = urlparse(list_url)
    if parsed.netloc.endswith("lifelong.mokpo.go.kr") and parsed.path in {"", "/"}:
        list_url = MOKPO_LIFELONG_LIST_URL
        parsed = urlparse(list_url)
    base_query = parse_qs(parsed.query)
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        if page > 1:
            query["page"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, .pg_wrap, a[href*='page=']"))

        for tr in soup.select("table tbody tr"):
            cells = tr.find_all("td", recursive=False)
            if len(cells) < 7:
                continue
            texts = [clean_text(cell.get_text(" ", strip=True)) for cell in cells]
            branch = texts[0]
            link = cells[1].find("a", href=True)
            title = clean_text(link.get_text(" ", strip=True) if link else texts[1])
            if not title or is_low_value_title(title):
                continue
            raw_url = urljoin(current_url, link.get("href") if link else "") if link else current_url
            row: dict[str, Any] = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch or "목포시 평생학습포털",
                "category": "평생학습",
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": texts[6],
                "fee": texts[5],
                "period": normalize_mixed_date_range(texts[3]),
                "apply_period": normalize_mixed_date_range(texts[4]),
                "schedule_raw": "",
                "instructor": texts[2],
                "description": clean_text(tr.get_text(" ", strip=True)),
                "domain_category": clean_text(target.extra.get("domain_category") or "평생학습"),
                "collection_category": clean_text(target.extra.get("collection_category") or "평생학습"),
                "source_group": clean_text(target.extra.get("source_group") or "lifelong_learning"),
                "operator_type": clean_text(target.extra.get("operator_type") or "지자체/공공기관"),
                "collection_type": clean_text(target.extra.get("collection_type") or "static_html"),
                "raw_fields": {"parser": "mokpo_lifelong_table_detail", "cells": texts},
            }

            if raw_url and detail_pages < detail_limit:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    pairs = pairs_from_tables(detail_soup)
                    current_capacity, total_capacity = parse_capacity_pair(pairs.get("접수/정원"))
                    detail_title = clean_text(pairs.get("강좌명"))
                    detail_branch = clean_text(pairs.get("교육기관"))
                    row["title"] = detail_title or row["title"]
                    row["branch"] = detail_branch or row["branch"]
                    row["category"] = clean_text(pairs.get("분야") or pairs.get("강의분야")) or row["category"]
                    row["status"] = clean_text(pairs.get("강좌상태")) or row["status"]
                    row["fee"] = clean_text(pairs.get("수강료")) or row["fee"]
                    row["material_fee"] = clean_text(pairs.get("재료비"))
                    row["period"] = normalize_mixed_date_range(pairs.get("교육기간", "")) or row["period"]
                    row["apply_period"] = normalize_mixed_date_range(pairs.get("신청기간", "")) or row["apply_period"]
                    row["schedule_raw"] = clean_text(pairs.get("교육일시")) or row["schedule_raw"]
                    row["target"] = clean_text(pairs.get("교육대상"))
                    row["capacity"] = clean_text(pairs.get("접수/정원"))
                    row["capacity_current"] = current_capacity
                    row["capacity_total"] = total_capacity
                    row["venue_name"] = clean_text(pairs.get("교육장소"))
                    row["contact"] = clean_text(pairs.get("문의"))
                    row["application_method_raw"] = clean_text(pairs.get("신청방법"))
                    row["instructor"] = clean_text(pairs.get("강사명")) or row["instructor"]
                    description = clean_text(" ".join(part for part in [pairs.get("강좌소개"), pairs.get("기타")] if clean_text(part)))
                    row["description"] = description or clean_text(detail_soup.get_text(" ", strip=True))[:1000]
                    row["provider_course_id"] = stable_course_id(target.provider, raw_url, row["title"], row["branch"])
                    row["raw_fields"] = {**row["raw_fields"], "detail_pairs": pairs}
                except Exception as exc:
                    logger.debug("Mokpo lifelong detail fetch failed %s: %s", raw_url, exc)

            rows.append(row)
            page_rows += 1

        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "pagination_detected": pagination_detected or pages > 1,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "mokpo_lifelong_table_detail", meta


def collect_yuseong_lifelong_classes(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    page_heading = clean_text((soup.select_one("h2") or soup.select_one("h1") or soup).get_text(" ", strip=True))
    rows: list[dict[str, Any]] = []
    for item in soup.select(".item-inner"):
        title = clean_text((item.select_one(".title") or item).get_text(" ", strip=True))
        if not title or is_low_value_title(title):
            continue
        status_nodes = item.select(".status-wrap .status")
        place_node = item.select_one(".status-wrap .status.place")
        branch = clean_text(place_node.get_text(" ", strip=True)) if place_node else page_heading
        status = ""
        for node in status_nodes:
            if place_node is not None and node is place_node:
                continue
            status = clean_text(node.get_text(" ", strip=True))
            if status:
                break
        if not branch:
            branch = clean_text(target.branch) or "유성구 평생학습센터"
        pairs: dict[str, str] = {}
        for li in item.select(".list-1st li"):
            key = normalize_korean_label((li.select_one(".tit") or li).get_text(" ", strip=True))
            value_node = li.select_one(".txt")
            value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
            if key:
                pairs[key] = value
        key_no = clean_text((item.select_one("a[data-key-no]") or {}).get("data-key-no"))
        group_id = clean_text((item.select_one("a[data-group-id]") or {}).get("data-group-id"))
        raw_query = urlencode({"groupId": group_id, "keyNo": key_no}) if key_no else urlparse(target.url).query
        raw_url = urlparse(target.url)._replace(query=raw_query).geturl()
        capacity_current = parse_capacity_number(pairs.get("접수인원"))
        capacity_total = parse_capacity_number(pairs.get("모집인원"))
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "fee": clean_text(pairs.get("수강료")),
                "period": normalize_mixed_date_range(pairs.get("수강기간", "") or pairs.get("교육기간", "")),
                "apply_period": normalize_mixed_date_range(pairs.get("접수일시", "") or pairs.get("접수기간", "")),
                "schedule_raw": clean_text(pairs.get("요일/시간") or pairs.get("교육시간") or pairs.get("교육일시")),
                "target": clean_text(pairs.get("교육대상")),
                "capacity": capacity_total,
                "capacity_current": capacity_current,
                "application_method_raw": clean_text(pairs.get("접수방법")),
                "contact": clean_text(pairs.get("문의처")),
                "description": clean_text(item.get_text(" ", strip=True)),
                "raw_fields": {"parser": "yuseong_lifelong_classes", "pairs": pairs, "key_no": key_no, "group_id": group_id},
            }
        )
    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": bool(soup.select(".pagination, .paging, .page-item")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "yuseong_lifelong_classes", meta


def collect_dobong_course_boxes(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False
    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["Page"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for item in soup.select(".course_box"):
            title_node = item.select_one(".tit_area .tit")
            title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
            if not title or is_low_value_title(title):
                continue
            onclick = clean_text(title_node.get("onclick") if title_node else "")
            id_match = re.search(r"goDesc\(['\"]?(\d+)", onclick)
            course_id = id_match.group(1) if id_match else ""
            raw_url = current_url
            if course_id:
                raw_url = parsed._replace(query=urlencode({**base_query, "Idx": [course_id]}, doseq=True)).geturl()
            periods = [clean_text(node.get_text(" ", strip=True)) for node in item.select(".tit_area .period")]
            period_pairs = pairs_from_lines(periods)
            tags = [clean_text(node.get_text(" ", strip=True)).lstrip("#") for node in item.select(".has_tag span")]
            image = item.select_one(".img_area img")
            status = clean_text((item.select_one(".course_btn_area .btn") or item).get_text(" ", strip=True))
            fee = clean_text((item.select_one(".price") or item).get_text(" ", strip=True))
            target_text = next((tag for tag in tags if any(token in tag for token in ("초등", "중등", "고등", "성인", "청소년", "유아"))), "")
            category = next((tag for tag in tags if tag in {"기타", "문화", "체육", "예술", "과학"}), "")
            venue = tags[0] if tags else target.branch
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, venue),
                    "title": title,
                    "branch": venue,
                    "category": category,
                    "raw_url": raw_url,
                    "application_url": raw_url if "마감" not in status else "",
                    "status": status,
                    "fee": fee,
                    "period": normalize_yymmdd_range(period_pairs.get("교육기간", "")),
                    "apply_period": normalize_yymmdd_range(period_pairs.get("접수기간", "")),
                    "schedule_raw": "",
                    "target": target_text,
                    "room": venue,
                    "venue_name": venue,
                    "image_url": normalize_link(current_url, image.get("src") if image else None),
                    "description": clean_text((item.select_one(".info_list .txt") or item).get_text(" ", strip=True)),
                    "raw_fields": {"parser": "dobong_course_boxes", "tags": tags, "course_id": course_id},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination"))
        if page_rows == 0:
            break
    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "dobong_course_boxes", meta


