def seogu_library_branch_from_url(url: str) -> tuple[str, str, str]:
    path = urlparse(url).path
    match = re.search(r"/library/([^/]+)/", path)
    key = match.group(1) if match else "wolpyeonglib"
    name, address = SEOGU_LIBRARY_BRANCHES.get(key, ("????쒓뎄?꾩꽌愿", "??꾧킅??떆 ?쒓뎄"))
    return key, name, address


def seogu_library_list_url(url: str) -> str:
    parsed = urlparse(url)
    if parsed.path.endswith("/index.do"):
        base_path = parsed.path.rsplit("/", 1)[0] + "/contents/learning/lib/02/lib.02.001.motion"
        return parsed._replace(path=base_path, query="mnucd=MENU0600030").geturl()
    if "lib.02.001.motion" in parsed.path and "bmode=detail" in parsed.query:
        query = parse_qs(parsed.query)
        query.pop("bmode", None)
        query.pop("lecId", None)
        query["mnucd"] = [query.get("mnucd", ["MENU0600030"])[0]]
        return parsed._replace(query=urlencode(query, doseq=True)).geturl()
    return url


def seogu_library_detail_url(list_url: str, lec_id: str) -> str:
    parsed = urlparse(list_url)
    query = parse_qs(parsed.query)
    mnucd = query.get("mnucd", ["MENU0600030"])[0]
    detail_query = {
        "bmode": "detail",
        "lecId": lec_id,
        "mnucd": mnucd,
    }
    return parsed._replace(query=urlencode(detail_query)).geturl()


def seogu_library_pairs_from_detail(soup: BeautifulSoup) -> dict[str, str]:
    table = soup.select_one("table.tbl_basic_view")
    if not table:
        return {}
    pairs: dict[str, str] = {}
    for tr in table.select("tr"):
        cells = [cell for cell in tr.find_all(["th", "td"], recursive=False)]
        if len(cells) == 2:
            key = clean_text(cells[0].get_text(" ", strip=True))
            value = clean_text(cells[1].get_text(" ", strip=True))
            if key and value:
                pairs[key] = value
        elif len(cells) >= 4:
            key1 = clean_text(cells[0].get_text(" ", strip=True))
            val1 = clean_text(cells[1].get_text(" ", strip=True))
            key2 = clean_text(cells[2].get_text(" ", strip=True))
            val2 = clean_text(cells[3].get_text(" ", strip=True))
            if key1 and val1:
                pairs[key1] = val1
            if key2 and val2:
                pairs[key2] = val2
        elif len(cells) == 1 and clean_text(cells[0].get_text(" ", strip=True)) == "媛뺤쓽?댁슜":
            next_row = tr.find_next_sibling("tr")
            if next_row:
                content = next_row.select_one(".content_box") or next_row.find("td")
                if content:
                    pairs["媛뺤쓽?댁슜"] = clean_text(content.get_text(" ", strip=True))
                    image = content.find("img")
                    if image:
                        pairs["image_url"] = normalize_link(soup.base.get("href") if soup.base else "", image.get("src"))
    return pairs


def seogu_library_status(capacity: str, apply_period: str) -> str:
    current, total = parse_capacity_pair(capacity)
    if current is not None and total is not None and total > 0 and current >= total:
        return "접수마감"
    _, apply_end = parse_date_range(apply_period)
    if apply_end and apply_end < datetime.now().date():
        return "접수마감"
    return "접수가능" if apply_period or capacity else ""


def collect_seogu_library_classes(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    list_url = seogu_library_list_url(target.url)
    parsed = urlparse(list_url)
    branch_code, branch_name, branch_address = seogu_library_branch_from_url(list_url)
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False

    for page in range(1, max_pages + 1):
        current_url = list_url
        if page > 1:
            query = parse_qs(parsed.query)
            query["pageIndex"] = [str(page)]
            current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        table = soup.select_one("table.tbl_basic")
        if not table:
            break
        page_rows = 0
        for tr in table.select("tbody tr"):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
            if len(cells) < 7:
                continue
            link = tr.select_one("td.left a[onclick], td a[onclick]")
            onclick = clean_text(link.get("onclick")) if link else ""
            lec_match = re.search(r"'(LEC_[^']+)'", onclick)
            lec_id = lec_match.group(1) if lec_match else cells[0]
            title = clean_text(link.get_text(" ", strip=True)) if link else cells[2]
            detail_url = seogu_library_detail_url(list_url, lec_id)
            category = cells[1]
            target_text = cells[3]
            period = normalize_mixed_date_range(cells[4])
            schedule_raw = " ".join(part for part in [period, cells[5]] if part)
            capacity = cells[6]
            detail_pairs: dict[str, str] = {}
            if detail_pages < detail_limit:
                try:
                    detail_soup = fetch_soup(s, detail_url, timeout=timeout)
                    detail_pairs = seogu_library_pairs_from_detail(detail_soup)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("seogu library detail fetch failed %s: %s", detail_url, exc)

            detail_title = clean_text(detail_pairs.get("?쒕ぉ"))
            if detail_title:
                bracket_match = re.search(r"\]\s*(.+)$", detail_title)
                title = clean_text(bracket_match.group(1) if bracket_match else detail_title)
            period = normalize_mixed_date_range(detail_pairs.get("?쇱떆") or period)
            schedule_raw = " ".join(
                part
                for part in [
                    period,
                    clean_text(detail_pairs.get("?붿씪")),
                    clean_text(detail_pairs.get("?쒓컙")) or cells[5],
                ]
                if part
            )
            apply_period = clean_text(detail_pairs.get("?좎껌湲곌컙"))
            capacity = clean_text(detail_pairs.get("紐⑥쭛?몄썝") or capacity)
            description = clean_text(detail_pairs.get("媛뺤쓽?댁슜")) or clean_text(tr.get_text(" ", strip=True))
            image_url = clean_text(detail_pairs.get("image_url"))

            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, detail_url, title, branch_name),
                    "title": title,
                    "branch": branch_name,
                    "branch_code": branch_code,
                    "address": branch_address,
                    "venue_name": branch_name,
                    "venue_address": branch_address,
                    "category": category,
                    "category_raw": category,
                    "raw_url": detail_url,
                    "application_url": detail_url,
                    "application_type": "online",
                    "status": seogu_library_status(capacity, apply_period),
                    "fee": "臾대즺",
                    "period": period,
                    "schedule_raw": schedule_raw,
                    "apply_period": apply_period,
                        "target": clean_text(detail_pairs.get("\uAD50\uC721\uB300\uC0C1")) or target_text,
                    "capacity": capacity,
                    "waitlist_total": clean_text(detail_pairs.get("?덈퉬?몄썝")),
                    "instructor": clean_text(detail_pairs.get("媛뺤궗")),
                    "description": description,
                    "image_url": image_url,
                    "reservation_available": "접수" in seogu_library_status(capacity, apply_period),
                    "raw_fields": {
                        "cells": cells,
                        "detail_pairs": detail_pairs,
                        "parser": "seogu_library_classes",
                    },
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination a.pagenum"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "seogu_library_classes+detail", meta


YJLIB_BRANCH_ALIASES = {
    "?ъ＜": "?ъ＜?꾩꽌愿",
    "?몄쥌": "?몄쥌?꾩꽌愿",
    "?먮룞": "?먮룞?꾩꽌愿",
    "?곕턿": "?곕턿?묒??꾩꽌愿",
    "遺곷궡": "遺곷궡?묒??꾩꽌愿",
    "?ъ＜湲곗쟻": "?ъ＜湲곗쟻?섎룄?쒓?",
    "?μ쿇": "?μ쿇?꾩꽌愿",
    "湲덉궗": "湲덉궗?꾩꽌愿",
}


def yjlib_normalize_branch(raw_branch: Any, title: Any = "", venue_name: Any = "") -> str:
    branch = clean_text(raw_branch)
    title_text = clean_text(title)
    venue_text = clean_text(venue_name)
    for value in (venue_text, title_text):
        match = re.search(r"([가-힣A-Za-z0-9]+(?:기적의도서관|작은도서관|도서관))", value)
        if match:
            return clean_text(match.group(1))
    if branch in YJLIB_BRANCH_ALIASES:
        return YJLIB_BRANCH_ALIASES[branch]
    if branch and not branch.endswith("?꾩꽌愿"):
        return f"{branch}?꾩꽌愿"
    return branch or "?ъ＜?쒕┰?꾩꽌愿"


def yjlib_detail_pairs(view: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for block in view.select(".info > div"):
        label_el = block.find("strong", recursive=False)
        value_el = block.find("div", recursive=False)
        label = clean_text(label_el.get_text(" ", strip=True) if label_el else "")
        if not label or not value_el:
            continue
        pairs[label] = clean_text(value_el.get_text(" ", strip=True))
    return pairs


def yjlib_clean_period(value: Any) -> str:
    return clean_text(re.sub(r"\b(?:교육예정|교육중|교육종료|접수예정|접수중|접수종료|대기접수)\b", " ", clean_text(value)))


def fetch_yjlib_detail(s: requests.Session, raw_url: str, timeout: int) -> dict[str, Any]:
    detail: dict[str, Any] = {}
    try:
        soup = fetch_soup(s, raw_url, timeout=timeout)
    except RequestException as exc:
        logger.debug("YJLIB detail fetch failed %s: %s", raw_url, exc)
        return detail
    view = soup.select_one(".article-view")
    if not view:
        return detail

    title_el = view.select_one("h6.title")
    raw_branch = clean_text((title_el.select_one(".lib") or {}).get_text(" ", strip=True) if title_el and title_el.select_one(".lib") else "")
    if title_el:
        for child in title_el.select(".lib"):
            child.extract()
    title = clean_text(title_el.get_text(" ", strip=True) if title_el else "")
    pairs = yjlib_detail_pairs(view)
    venue_name = clean_text(pairs.get("장소"))
    weekday = clean_text(pairs.get("강좌요일"))
    time_text = clean_text(pairs.get("강좌시간"))
    schedule_raw = clean_text(" ".join(part for part in (weekday, time_text) if part))
    con_area = view.select_one(".conArea")
    description = clean_text(con_area.get_text(" ", strip=True) if con_area else view.get_text(" ", strip=True))
    image_el = con_area.select_one("img[src]") if con_area else None
    fee_text = clean_text(pairs.get("수강료 및 재료비"))
    material_note = clean_text(" / ".join(part for part in (fee_text, pairs.get("준비물")) if clean_text(part) and clean_text(part) != "-"))

    detail.update(
        {
            "title": title,
            "branch": yjlib_normalize_branch(raw_branch, title, venue_name),
            "period": yjlib_clean_period(pairs.get("강좌기간")),
            "schedule_raw": schedule_raw,
            "target": clean_text(pairs.get("교육대상")),
            "room": venue_name,
            "venue_name": venue_name,
            "instructor": clean_instructor_name(pairs.get("강사명")),
            "fee": fee_text or "臾대즺",
            "material_note": material_note,
            "material_fee": extract_material_fee_amount(fee_text, material_note, description),
            "apply_period": clean_text(pairs.get("접수일시")),
            "status": clean_text(
                (view.select_one(".status") or view.select_one(".eduStat") or {}).get_text(" ", strip=True)
                if (view.select_one(".status") or view.select_one(".eduStat"))
                else ""
            ),
            "capacity": clean_text(pairs.get("접수현황")),
            "phone": clean_text(pairs.get("문의전화")),
            "description": description,
            "image_url": urljoin(raw_url, image_el.get("src")) if image_el else "",
            "raw_fields": {"pairs": pairs, "parser": "yjlib_article_detail"},
        }
    )
    return {key: value for key, value in detail.items() if value not in (None, "")}


def collect_yjlib_lecture_list(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 0,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query["currentPageNo"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='currentPageNo']"))

        for item in soup.select(".article-item"):
            title_el = item.select_one(".info-title .title")
            title = clean_text(title_el.get_text(" ", strip=True) if title_el else "")
            if not title:
                continue
            onclick = clean_text(title_el.get("onclick") if title_el else "")
            detail_id = ""
            match = re.search(r"fnDetail\('([^']+)'\)", onclick)
            if match:
                detail_id = match.group(1)
            detail_query = parse_qs(parsed.query)
            detail_query["lectureIdx"] = [detail_id or "0"]
            raw_url = parsed._replace(path="/web/menu/10071/program/30020/lectureDetail.do", query=urlencode(detail_query, doseq=True)).geturl()

            category = clean_text((item.select_one(".info-cate .type") or {}).get_text(" ", strip=True) if item.select_one(".info-cate .type") else "")
            raw_branch = clean_text((item.select_one(".info-cate .lib") or {}).get_text(" ", strip=True) if item.select_one(".info-cate .lib") else "") or target.branch
            status = clean_text((item.select_one(".item-status .status") or {}).get_text(" ", strip=True) if item.select_one(".item-status .status") else "")
            if not status:
                status = clean_text((item.select_one(".eduStat") or {}).get_text(" ", strip=True) if item.select_one(".eduStat") else "")

            pairs: dict[str, str] = {}
            for p in item.select(".info-info p"):
                label_el = p.find("b")
                label = clean_text(label_el.get_text(" ", strip=True) if label_el else "")
                if not label:
                    continue
                if label_el:
                    label_el.extract()
                pairs[label] = clean_text(p.get_text(" ", strip=True).lstrip(":"))

            capacity_text = clean_text((item.select_one(".apply-num") or {}).get_text(" ", strip=True) if item.select_one(".apply-num") else "")
            venue_name = clean_text(pairs.get("?μ냼"))
            branch = yjlib_normalize_branch(raw_branch, title, venue_name)
            row = {
                "provider": target.provider,
                "title": title,
                "branch": branch,
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "fee": "臾대즺",
                "period": clean_text(pairs.get("\uAD50\uC721\uAE30\uAC04")),
                "apply_period": clean_text(pairs.get("\uC811\uC218\uC77C\uC2DC")),
                "schedule_raw": clean_text(pairs.get("\uC694\uC77C/\uC2DC\uAC04") or pairs.get("\uAD50\uC721\uAE30\uAC04")),
                "target": clean_text(pairs.get("\uAD50\uC721\uB300\uC0C1") or pairs.get("대상")),
                "room": venue_name,
                "venue_name": venue_name,
                "capacity": capacity_text,
                "description": clean_text(item.get_text(" ", strip=True)),
                "raw_fields": {"pairs": pairs, "capacity": capacity_text, "detail_id": detail_id, "parser": "yjlib_article_cards"},
            }
            if detail_id and (detail_limit <= 0 or detail_pages < detail_limit):
                detail = fetch_yjlib_detail(s, raw_url, timeout)
                detail_pages += 1
                if detail:
                    raw_fields = dict(row.get("raw_fields") or {})
                    raw_fields["detail"] = detail.get("raw_fields")
                    row.update({key: value for key, value in detail.items() if key != "raw_fields"})
                    row["raw_fields"] = raw_fields
            row["provider_course_id"] = stable_course_id(target.provider, raw_url, row.get("title"), row.get("branch"))
            rows.append(row)
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "yjlib_article_cards+detail", meta


CNALL_BRANCH_ALIASES = {
    "학생교육문화원": "충청남도교육청학생교육문화원",
    "평생교육원": "충청남도교육청평생교육원",
    "남부평생교육원": "충청남도교육청남부평생교육원",
    "서부평생교육원": "충청남도교육청서부평생교육원",
    "진로융합교육원": "충청남도교육청진로융합교육원",
}


def cnall_normalize_branch(value: Any) -> str:
    branch = clean_text(value)
    return CNALL_BRANCH_ALIASES.get(branch, branch)


def cnall_clean_target(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    parts = [clean_text(part) for part in re.split(r"\s*(?:/|,|쨌)\s*", text) if clean_text(part)]
    if not parts:
        return text
    return " 쨌 ".join(dict.fromkeys(parts))


def cnall_branch_from_organ_name(value: Any) -> str:
    name = clean_text(value)
    if not name:
        return ""
    if "교육지원청" in name:
        return cnall_normalize_branch(name.split("교육지원청", 1)[1])
    return cnall_normalize_branch(name)


def cnall_fetch_organ_map(s: requests.Session, base_url: str, timeout: int) -> dict[str, dict[str, str]]:
    url = urljoin(base_url, "/organ/organList.do")
    try:
        soup = fetch_soup(s, url, timeout=timeout)
    except RequestException as exc:
        logger.debug("CNALL organ list fetch failed %s: %s", url, exc)
        return {}

    organ_map: dict[str, dict[str, str]] = {}
    for tr in soup.select("table.board-list tr"):
        tds = tr.select("td")
        if len(tds) < 4:
            continue
        region = clean_text(tds[0].get_text(" ", strip=True))
        organ_name = clean_text(tds[1].get_text(" ", strip=True))
        branch = cnall_branch_from_organ_name(organ_name)
        address = clean_text(tds[2].get_text(" ", strip=True))
        phone = clean_text(tds[3].get_text(" ", strip=True))
        website_url = ""
        organ_idx = ""
        for link in tds[1].select("a[href]"):
            href = clean_text(link.get("href"))
            if href and "#none" not in href:
                website_url = urljoin(url, href)
                break
        for link in tr.select("a[href]"):
            href = clean_text(link.get("href"))
            match = re.search(r"organIdxArr=(\d+)", href)
            if match:
                organ_idx = match.group(1)
                break
        if not branch:
            continue
        data = {
            "branch": branch,
            "branch_code": f"organ_{organ_idx}" if organ_idx else "",
            "organ_name": organ_name,
            "region": region,
            "address": address,
            "phone": phone,
            "website_url": website_url,
        }
        for key in {branch, organ_name, cnall_normalize_branch(branch)}:
            if key:
                organ_map[key] = data
    return organ_map


def cnall_apply_organ_data(row: dict[str, Any], organ_map: dict[str, dict[str, str]]) -> dict[str, Any]:
    branch = cnall_normalize_branch(row.get("branch"))
    data = organ_map.get(branch) or organ_map.get(clean_text(row.get("venue_name")))
    if not data:
        return row
    row["branch"] = data["branch"]
    row["venue_name"] = data["branch"]
    if data.get("branch_code"):
        row["branch_code"] = data["branch_code"]
    if data.get("address"):
        row["address"] = data["address"]
        row["venue_address"] = data["address"]
    if data.get("phone") and not clean_text(row.get("phone")):
        row["phone"] = data["phone"]
    if data.get("website_url") and not clean_text(row.get("website_url")):
        row["website_url"] = data["website_url"]
    raw_fields = dict(row.get("raw_fields") or {})
    raw_fields["organ"] = {
        "organ_name": data.get("organ_name"),
        "region": data.get("region"),
        "address_source": "/organ/organList.do",
    }
    row["raw_fields"] = raw_fields
    return row


def cnall_list_url(base_url: str, page: int) -> str:
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    query.update(
        {
            "organAllYn": ["Y"],
            "organAllChk": ["Y"],
            "currentPageNo": [str(page)],
            "recordCountPerPage": [query.get("recordCountPerPage", ["20"])[0] or "20"],
        }
    )
    return parsed._replace(path="/lecture/lectureList.do", query=urlencode(query, doseq=True)).geturl()


def cnall_detail_url(base_url: str, lecture_idx: str) -> str:
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    query.update({"lectureIdx": [lecture_idx], "organAllYn": ["Y"], "organAllChk": ["Y"]})
    return parsed._replace(path="/lecture/lectureDetail.do", query=urlencode(query, doseq=True)).geturl()


def cnall_pairs_from_detail(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for table in soup.select("table.board-view"):
        for tr in table.select("tr"):
            th = tr.find("th")
            td = tr.find("td")
            key = clean_text(th.get_text(" ", strip=True) if th else "")
            value = clean_text(td.get_text(" ", strip=True) if td else "")
            if key and value:
                pairs[key] = value
    return pairs


def cnall_extract_homepage(soup: BeautifulSoup) -> str:
    for table in soup.select("table.board-view"):
        for link in table.select("a[href]"):
            text = clean_text(link.get_text(" ", strip=True))
            href = clean_text(link.get("href"))
            if text == "홈페이지" and href:
                return href
    return ""


def cnall_extract_phone(value: Any) -> str:
    text = clean_text(value)
    match = re.search(r"(?:대표전화|전화번호)\s*:\s*([0-9)(내선\s\-]+)", text)
    return clean_text(match.group(1)) if match else ""


def cnall_split_period_schedule(value: Any) -> tuple[str, str]:
    text = clean_text(value)
    if not text:
        return "", ""
    parts = [clean_text(part) for part in re.split(r"\s*/\s*", text) if clean_text(part)]
    period = parts[0] if parts else text
    schedule = clean_text(" ".join(parts[1:]))
    return period, schedule


def cnall_extract_description(soup: BeautifulSoup) -> str:
    node = soup.select_one("td.content")
    if not node:
        return ""
    return clean_text(node.get_text(" ", strip=True))[:4000]


def cnall_extract_image_url(raw_url: str, soup: BeautifulSoup) -> str:
    node = soup.select_one("td.content img[src]")
    src = clean_text(node.get("src") if node else "")
    if not src or "ico_down" in src:
        return ""
    return urljoin(raw_url, src)


def cnall_detail_data(s: requests.Session, raw_url: str, timeout: int) -> dict[str, Any]:
    try:
        soup = fetch_soup(s, raw_url, timeout=timeout)
    except RequestException as exc:
        logger.debug("CNALL detail fetch failed %s: %s", raw_url, exc)
        return {}

    pairs = cnall_pairs_from_detail(soup)
    period, schedule = cnall_split_period_schedule(pairs.get("강좌기간"))
    branch = cnall_normalize_branch(clean_text(str(pairs.get("기관정보") or "").split("|", 1)[0]))
    phone = cnall_extract_phone(pairs.get("기관정보")) or cnall_extract_phone(pairs.get("담당부서"))
    capacity_text = clean_text(pairs.get("신청/대기"))
    capacity_current, capacity_total = parse_capacity_pair(capacity_text)
    wait_current, wait_total = parse_capacity_pair(cnall_text_after_label(capacity_text, "대기신청자"))
    description = cnall_extract_description(soup)
    status_raw = clean_text(" ".join(part for part in (pairs.get("접수기간"), capacity_text) if part))
    return {
        "branch": branch,
        "venue_name": branch,
        "phone": phone,
        "website_url": cnall_extract_homepage(soup),
        "period": period,
        "schedule_raw": schedule,
        "apply_period": clean_text(pairs.get("접수일시") or pairs.get("접수기간")),
        "target": cnall_clean_target(pairs.get("대상")),
        "fee": clean_text(pairs.get("수강료")) or "무료",
        "description": description,
        "image_url": cnall_extract_image_url(raw_url, soup),
        "capacity": capacity_total,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_total": wait_total or wait_current,
        "status": status_raw,
        "application_url": raw_url,
        "raw_fields": {"detail_pairs": pairs, "parser": "cnall_lecture_detail"},
    }


def cnall_text_after_label(value: str, label: str) -> str:
    text = clean_text(value)
    return clean_text(text.split(label, 1)[1].lstrip(":")) if label in text else ""


def parse_cnall_list_item(target: CrawlTarget, page_url: str, item: BeautifulSoup) -> dict[str, Any] | None:
    title_link = item.select_one(".title a")
    title = clean_text(title_link.get_text(" ", strip=True) if title_link else "")
    onclick = clean_text(title_link.get("href") if title_link else "")
    match = re.search(r"fnDetail\('([^']+)'\)", onclick)
    lecture_idx = match.group(1) if match else ""
    if not title or not lecture_idx:
        return None

    raw_url = cnall_detail_url(page_url, lecture_idx)
    icons = [clean_text(icon.get_text(" ", strip=True)) for icon in item.select(".title i")]
    area = clean_text((item.select_one(".title i.etc") or {}).get_text(" ", strip=True) if item.select_one(".title i.etc") else "")
    target_values = [clean_text(icon.get_text(" ", strip=True)) for icon in item.select(".title i.target") if clean_text(icon.get_text(" ", strip=True))]
    fee_icon = item.select_one(".title i.nCharge, .title i.charge")
    fee = clean_text(fee_icon.get_text(" ", strip=True) if fee_icon else "")

    info_blocks = item.select(".info")
    first_spans = [clean_text(span.get_text(" ", strip=True)) for span in info_blocks[0].select("span")] if info_blocks else []
    second_spans = [clean_text(span.get_text(" ", strip=True)) for span in info_blocks[1].select("span")] if len(info_blocks) > 1 else []
    branch = ""
    period = ""
    schedule_parts: list[str] = []
    for span in first_spans:
        if "기관" in span and ":" in span:
            branch = cnall_normalize_branch(cnall_text_after_label(span, "기관"))
        elif "강좌기간" in span:
            period = cnall_text_after_label(span, "강좌기간")
        else:
            schedule_parts.append(span)
    apply_period = ""
    capacity_text = ""
    wait_text = ""
    for span in second_spans:
        if "접수기간" in span:
            apply_period = cnall_text_after_label(span, "접수기간")
        elif "온라인신청자" in span or "모집인원" in span:
            capacity_text = span
        elif "대기신청자" in span:
            wait_text = span
        elif "수강료" in span and not fee:
            fee = cnall_text_after_label(span, "수강료")
    capacity_current, capacity_total = parse_capacity_pair(capacity_text)
    wait_current, wait_total = parse_capacity_pair(wait_text)
    status = clean_text((item.select_one(".info_r") or {}).get_text(" ", strip=True) if item.select_one(".info_r") else "")
    return {
        "provider": target.provider,
        "provider_course_id": lecture_idx,
        "title": title,
        "branch": branch or target.branch,
        "category": " / ".join(icon for icon in icons if icon and icon not in {fee, *target_values}),
        "collection_category": target.extra.get("collection_category") or "도서관",
        "domain_category": target.extra.get("domain_category") or "도서관",
        "source_group": target.extra.get("source_group") or "library",
        "operator_type": target.extra.get("operator_type") or "교육청 도서관",
        "collection_type": "static_html",
        "raw_url": raw_url,
        "application_url": raw_url,
        "status": status,
        "fee": fee or "무료",
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": clean_text(" ".join(schedule_parts)),
        "target": cnall_clean_target(" 쨌 ".join(dict.fromkeys(target_values))),
        "capacity": capacity_total,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_total": wait_total or wait_current,
        "venue_name": branch or target.branch,
        "raw_fields": {"area": area, "capacity_text": capacity_text, "wait_text": wait_text, "parser": "cnall_lecture_list"},
    }


def collect_cnall_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    max_page_seen = 0
    organ_map = cnall_fetch_organ_map(s, target.url, timeout)

    for page in range(1, max(1, max_pages) + 1):
        page_url = cnall_list_url(target.url, page)
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        page_rows = 0
        pagination_detected = pagination_detected or bool(soup.select(".paging"))
        for link in soup.select(".paging a[onclick]"):
            match = re.search(r"fnList\((\d+)\)", clean_text(link.get("onclick")))
            if match:
                max_page_seen = max(max_page_seen, int(match.group(1)))
        for item in soup.select(".lecture-list > li"):
            row = parse_cnall_list_item(target, page_url, item)
            if not row:
                continue
            if detail_limit <= 0 or detail_pages < detail_limit:
                detail = cnall_detail_data(s, row["raw_url"], timeout)
                if detail:
                    raw_fields = dict(row.get("raw_fields") or {})
                    raw_fields["detail"] = detail.get("raw_fields")
                    row.update({key: value for key, value in detail.items() if key != "raw_fields" and value not in (None, "")})
                    row["raw_fields"] = raw_fields
                detail_pages += 1
            row = cnall_apply_organ_data(row, organ_map)
            row["provider_course_id"] = clean_text(row.get("provider_course_id")) or stable_course_id(
                target.provider, row.get("raw_url"), row.get("title"), row.get("branch")
            )
            rows.append(row)
            page_rows += 1
        if page_rows == 0:
            break
        if max_page_seen and page >= max_page_seen and page >= 10:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected or max_page_seen > 1,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "cnall_lecture_cards+detail", meta


