def inje_lifelong_fetch_soup(
    s: requests.Session,
    url: str,
    timeout: int,
    params: dict[str, Any] | None = None,
) -> BeautifulSoup:
    response = s.get(url, params=params, timeout=timeout, verify=False)
    response.raise_for_status()
    response.encoding = response.apparent_encoding or response.encoding or "utf-8"
    return BeautifulSoup(response.text, "html.parser")


def inje_lifelong_title_category(title_node: BeautifulSoup | None) -> tuple[str, str]:
    if not title_node:
        return "", ""
    category_node = title_node.find("span")
    category = clean_text(category_node.get_text(" ", strip=True) if category_node else "").strip("[]")
    if category_node:
        category_node.extract()
    return clean_text(title_node.get_text(" ", strip=True)), category


def inje_lifelong_kv_from_list_text(text: str, key: str) -> str:
    text = clean_text(text)
    marker = f"{key}:"
    start = text.find(marker)
    if start < 0:
        return ""
    start += len(marker)
    end = len(text)
    for next_key in ("援먯쑁湲곌컙:", "?좎껌湲곌컙:", "援먯쑁???", "?묒닔?곹깭:", "?섍컯猷??щ즺鍮?", "紐⑥쭛?몄썝:"):
        if next_key == marker:
            continue
        index = text.find(next_key, start)
        if index >= 0:
            end = min(end, index)
    return clean_text(text[start:end])


def inje_lifelong_fee_parts(value: str) -> tuple[str, str]:
    text = clean_text(value)
    if not text:
        return "", ""
    parts = [clean_text(part) for part in text.split("/", 1)]
    return (parts[0] if parts else ""), (parts[1] if len(parts) > 1 else "")


def inje_lifelong_status(value: str) -> str:
    text = clean_text(value)
    if any(token in text for token in ("신청중", "대기접수중", "접수중")):
        return "접수중"
    if any(token in text for token in ("교육중", "진행중")):
        return "교육중"
    return text


def inje_lifelong_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for tr in soup.select("table tr"):
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
        cells = [cell for cell in cells if cell]
        if len(cells) == 1 and "title" not in pairs:
            pairs["title"] = cells[0]
        elif len(cells) >= 2:
            pairs[cells[0]] = cells[1]
    return pairs


def inje_lifelong_facility_map(s: requests.Session, timeout: int, max_pages: int) -> dict[str, dict[str, str]]:
    facilities: dict[str, dict[str, str]] = {}
    for page in range(1, max(1, max_pages) + 1):
        soup = inje_lifelong_fetch_soup(s, INJE_LIFELONG_FACILITIES_URL, timeout, params={"page.page": page})
        items = soup.select(".facList li")
        if not items:
            break
        for item in items:
            name = clean_text((item.select_one(".facTitle") or item).get_text(" ", strip=True))
            if not name:
                continue
            info: dict[str, str] = {}
            for p in item.find_all("p"):
                text = clean_text(p.get_text(" ", strip=True))
                if text.startswith("주소:"):
                    address = clean_text(text.split(":", 1)[1])
                    if address and address != ".":
                        info["address"] = address
                elif text.startswith("전화번호:"):
                    phone = clean_text(text.split(":", 1)[1])
                    if phone and phone != ".":
                        info["phone"] = phone
                elif text.startswith("기관유형"):
                    info["facility_type"] = clean_text(text.split(":", 1)[1] if ":" in text else text)
            if info:
                facilities.setdefault(name, info)
        if len(items) < 10:
            break
    return facilities


def inje_lifelong_extract_address(*values: str) -> str:
    text = clean_text(" ".join(value for value in values if value))
    if not text:
        return ""

    def normalize_fragment(candidate: str) -> str:
        candidate = clean_text(candidate)
        if not candidate:
            return ""
        if not (any(token in candidate for token in ("로", "길", "읍", "면")) and re.search(r"\d", candidate)):
            return ""
        if not candidate.startswith(("강원", "인제")):
            candidate = f"강원특별자치도 인제군 {candidate}"
        elif candidate.startswith("인제군"):
            candidate = f"강원특별자치도 {candidate}"
        elif re.match(r"인제(?:읍|남면|북면|기린면|상남면|서화면)", candidate):
            candidate = f"강원특별자치도 인제군 {candidate}"
        return candidate

    for candidate in re.findall(r"[\[(]([^\]\)]+)[\]\)]", text):
        normalized = normalize_fragment(candidate)
        if normalized:
            return normalized
    road_match = re.search(
        r"((?:강원(?:특별자치도)?\s*)?(?:인제군\s*)?(?:[가-힣A-Za-z0-9]+\s+)*(?:[가-힣A-Za-z0-9]+(?:로|길|번길)\s*\d+(?:-\d+)?(?:,\s*\d층)?))",
        text,
    )
    if road_match:
        return normalize_fragment(road_match.group(1))
    return ""


def inje_lifelong_venue_name(place: str, branch: str) -> str:
    text = clean_text(place)
    if not text:
        return branch
    if "/" in text:
        tail = clean_text(text.rsplit("/", 1)[-1])
        if tail:
            return re.sub(r"\[[^\]]+\]", "", tail).strip() or tail
    return re.sub(r"\[[^\]]+\]", "", text).strip() or branch


def inje_lifelong_image_url(soup: BeautifulSoup, raw_url: str) -> str:
    for hidden in soup.select("input[type=hidden][id^=attach_]"):
        value = clean_text(hidden.get("value"))
        if re.search(r"\.(?:jpg|jpeg|png|gif|webp)(?:$|\?)", value, re.I):
            return urldefrag(urljoin(raw_url, value))[0]
    for img in soup.select("img"):
        value = clean_text(img.get("src"))
        if value and not any(token in value for token in ("/logo", "/btn_", "/icon", "/common/")):
            return urldefrag(urljoin(raw_url, value))[0]
    return ""


def inje_lifelong_row_from_card(
    target: CrawlTarget,
    card: BeautifulSoup,
    list_url: str,
    facility_map: dict[str, dict[str, str]],
    detail_soup: BeautifulSoup | None = None,
) -> dict[str, Any] | None:
    raw_url = urldefrag(urljoin(list_url, card.get("href")))[0]
    branch = clean_text((card.select_one(".eduCenter") or card).get_text(" ", strip=True))
    if card.select_one(".eduCenter"):
        branch = clean_text(card.select_one(".eduCenter").get_text(" ", strip=True))
    branch = branch or INJE_LIFELONG_DEFAULT_BRANCH
    title_node = card.select_one(".eduTitle")
    title, category = inje_lifelong_title_category(BeautifulSoup(str(title_node), "html.parser").select_one(".eduTitle") if title_node else None)
    text = clean_text(card.get_text(" ", strip=True))
    if not title:
        title = text
    period = inje_lifelong_kv_from_list_text(text, "교육기간")
    apply_period = inje_lifelong_kv_from_list_text(text, "신청기간")
    target_text = inje_lifelong_kv_from_list_text(text, "교육대상")
    status = inje_lifelong_status(inje_lifelong_kv_from_list_text(text, "접수상태"))
    fee, material_fee = inje_lifelong_fee_parts(inje_lifelong_kv_from_list_text(text, "수강료/재료비"))
    capacity = inje_lifelong_kv_from_list_text(text, "모집인원")
    detail_pairs: dict[str, str] = {}
    description = ""
    place = ""
    schedule_raw = ""
    instructor = ""
    phone = ""
    image_url = ""
    if detail_soup:
        detail_pairs = inje_lifelong_detail_pairs(detail_soup)
        period = detail_pairs.get("교육기간") or period
        target_text = detail_pairs.get("교육대상") or target_text
        place = detail_pairs.get("교육장소") or ""
        schedule_raw = detail_pairs.get("교육일시") or ""
        phone = detail_pairs.get("연락처") or facility_map.get(branch, {}).get("phone", "")
        instructor = detail_pairs.get("강사명") or ""
        description = detail_pairs.get("내용") or ""
        image_url = inje_lifelong_image_url(detail_soup, raw_url)
    facility = facility_map.get(branch, {})
    venue_address = inje_lifelong_extract_address(description, place) or clean_text(facility.get("address")) or INJE_LIFELONG_DEFAULT_ADDRESS
    venue_name = inje_lifelong_venue_name(place, branch)
    map_branch = branch
    if venue_name and venue_name != branch and place:
        map_branch = f"{branch} - {venue_name}"
    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, map_branch),
        "title": title,
        "branch": map_branch,
        "branch_code": map_branch,
        "preserve_branch": True,
        "category": category,
        "collection_category": "평생교육",
        "domain_category": "평생교육",
        "source_group": "lifelong_learning",
        "operator_type": "지자체/공공기관",
        "collection_type": "static_html",
        "raw_url": raw_url,
        "application_url": raw_url,
        "application_method_raw": "온라인/전화/방문 접수",
        "status": status,
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": schedule_raw or period,
        "target": target_text,
        "eligibility_raw": target_text,
        "fee": fee,
        "material_fee": material_fee,
        "capacity": capacity,
        "venue_name": venue_name,
        "room": place or venue_name,
        "address": venue_address,
        "venue_address": venue_address,
        "phone": phone,
        "instructor": instructor,
        "description": description,
        "image_url": image_url,
        "program_type": "강좌",
        "reservation_available": status in {"접수중", "대기접수중"},
        "raw_fields": {
            "list_text": text,
            "detail_pairs": detail_pairs,
            "facility": facility,
            "original_branch": branch,
            "parser": "inje_lifelong_course_cards",
        },
    }


def collect_inje_lifelong_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    seen_urls: set[str] = set()
    facility_map = inje_lifelong_facility_map(s, timeout=timeout, max_pages=max_pages)
    for list_url in INJE_LIFELONG_LIST_URLS:
        for page in range(1, max(1, max_pages) + 1):
            soup = inje_lifelong_fetch_soup(s, list_url, timeout, params={"page.page": page})
            cards = soup.select(".eduList2 a[href*='courseSeq=']")
            if not cards:
                break
            pages += 1
            for card in cards:
                raw_url = urldefrag(urljoin(list_url, card.get("href")))[0]
                if raw_url in seen_urls:
                    continue
                seen_urls.add(raw_url)
                detail_soup = None
                if detail_pages < max(0, detail_limit):
                    try:
                        detail_soup = inje_lifelong_fetch_soup(s, raw_url, timeout)
                        detail_pages += 1
                    except Exception as exc:
                        logger.debug("inje lifelong detail fetch failed %s: %s", raw_url, exc)
                row = inje_lifelong_row_from_card(target, card, list_url, facility_map, detail_soup)
                if row:
                    rows.append(row)
            if len(cards) < 10:
                break
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": len(seen_urls),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > len(INJE_LIFELONG_LIST_URLS),
        "recursion_depth": 0,
        "facilities": len(facility_map),
    }
    return dedupe_rows(rows), "inje_lifelong_course_cards", meta


