BUSAN_LIFELONG_PROVIDER = "MUNI_LLL_BUSAN_GO_KR_944C621B"
BUKGU_DAEGU_PROVIDER = "MUNI_WWW_BUK_DAEGU_KR_RESERVATION"


def busan_lifelong_offices(soup: BeautifulSoup) -> list[dict[str, str]]:
    offices: dict[str, dict[str, str]] = {}
    for option in soup.select("#o_search_ch option[value]"):
        code = clean_text(option.get("value"))
        name = clean_text(option.get_text(" ", strip=True))
        if code:
            offices.setdefault(code, {"code": code, "name": name, "phone": "", "office_status": ""})

    for link in soup.select("a[onclick*='fn_learning_list']"):
        onclick = clean_text(link.get("onclick"))
        match = re.search(r"fn_learning_list\('([^']+)'\)", onclick)
        if not match:
            continue
        code = clean_text(match.group(1))
        text = clean_text(link.get_text(" ", strip=True))
        office = offices.setdefault(code, {"code": code, "name": "", "phone": "", "office_status": ""})
        status_pattern = "|".join(re.escape(status) for status in ("접수중", "접수대기", "접수종료"))
        parsed = re.match(rf"^({status_pattern})\s+(.+?)(?:\s+전화\s+([0-9-]+))?$", text)
        if parsed:
            office["office_status"] = clean_text(parsed.group(1))
            office["name"] = office["name"] or clean_text(parsed.group(2))
            office["phone"] = clean_text(parsed.group(3) or "")
        elif text and not office["name"]:
            office["name"] = text

    return [office for office in offices.values() if office.get("code") and office.get("name")]


def collect_busan_lifelong_learning(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    office_code = clean_text((query.get("inst_id") or [""])[0]) or clean_text(target.extra.get("branch_code"))
    if office_code:
        query["inst_id"] = [office_code]
        query.setdefault("searchCondition", ["0"])
        query.setdefault("searchKeyword", [""])
        query.setdefault("out_inst_yn", ["N"])
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False

    def span_value(node: Any) -> str:
        if not node:
            return ""
        clone = BeautifulSoup(str(node), "lxml")
        for hidden in clone.select("em.hidden"):
            hidden.extract()
        return clean_text(clone.get_text(" ", strip=True))

    def title_time(title: str) -> str:
        match = re.search(r"(?:(?:오전|오후)\s*)?\d{1,2}:\d{2}\s*~\s*(?:(?:오전|오후)\s*)?\d{1,2}:\d{2}", title)
        return clean_text(match.group(0)) if match else ""

    for page in range(1, max_pages + 1):
        query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        pagination_detected = pagination_detected or bool(soup.select("a[onclick*='fn_list'], a[href*='pageIndex=']"))

        for tr in soup.select("table tr"):
            title_el = tr.select_one("td.subject span.tit")
            title = clean_text(title_el.get_text(" ", strip=True) if title_el else "")
            if not title:
                continue
            link = tr.select_one("td.subject a[href]")
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            branch = clean_text((tr.select_one("td.subject span.org") or {}).get_text(" ", strip=True) if tr.select_one("td.subject span.org") else "") or target.branch
            type_spans = tr.select("td.type span")
            fee = clean_text(type_spans[0].get_text(" ", strip=True)) if type_spans else ""
            instructor = clean_text(type_spans[1].get_text(" ", strip=True)) if len(type_spans) > 1 else ""
            period = normalize_yymmdd_range(span_value(tr.select_one("td .s_type.blue")))
            apply_period = normalize_yymmdd_range(span_value(tr.select_one("td .s_type.red1")))
            capacity = span_value(tr.select_one("td .s_type.indigo1"))
            status = clean_text((tr.select_one("td .s_btn") or {}).get_text(" ", strip=True) if tr.select_one("td .s_btn") else "")
            schedule = clean_text(" ".join(part for part in [period, title_time(title)] if part))
            row_text = clean_text(tr.get_text(" ", strip=True))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "branch_code": office_code,
                    "category": "?됱깮?숈뒿",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": fee,
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule,
                    "target": "",
                    "capacity": capacity,
                    "instructor": instructor,
                    "description": row_text,
                    "raw_fields": {
                        "office_code": office_code,
                        "row_text": row_text,
                        "parser": "busan_lifelong_learning_table",
                    },
                }
            )
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "busan_lifelong_learning_table", meta


def collect_busan_lifelong_office_cycle(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    offices = busan_lifelong_offices(soup)
    base_url = urljoin(target.url, "/yeyak/ilms/learning/learningList.do")
    rows: list[dict[str, Any]] = []
    pages = 1
    detail_pages = 0
    pagination_detected = False
    row_limit = 0
    try:
        row_limit = max(0, int(target.extra.get("per_target_limit") or 0))
    except (TypeError, ValueError):
        row_limit = 0

    for office in offices:
        if row_limit > 0 and len(rows) >= row_limit:
            break
        list_url = (
            f"{base_url}?{urlencode({'inst_id': office['code'], 'pageIndex': 1, 'searchCondition': 0, 'searchKeyword': '', 'out_inst_yn': 'N'})}"
        )
        branch_target = CrawlTarget(
            provider=target.provider,
            name=target.name,
            branch=office["name"],
            url=list_url,
            source=target.source,
            priority=target.priority,
            region=target.region,
            extra={**target.extra, "branch_code": office["code"], "branch_phone": office.get("phone", "")},
        )
        branch_rows, _parser, meta = collect_busan_lifelong_learning(branch_target, timeout=timeout, max_pages=max_pages)
        pages += int(meta.get("pages") or 0)
        detail_pages += int(meta.get("detail_pages") or 0)
        pagination_detected = pagination_detected or bool(meta.get("pagination_detected"))
        for row in branch_rows:
            if row_limit > 0 and len(rows) >= row_limit:
                break
            row["branch"] = office["name"]
            row["branch_code"] = office["code"]
            row["phone"] = office.get("phone", "")
            row["venue_name"] = office["name"]
            row["collection_category"] = "怨듦났?덉빟"
            row["domain_category"] = "?됱깮援먯쑁"
            row["source_group"] = "public_reservation"
            row["operator_type"] = "吏?먯껜/怨듦났湲곌?"
            row.setdefault("raw_fields", {})
            row["raw_fields"].update(
                {
                    "office_code": office["code"],
                    "office_name": office["name"],
                    "office_phone": office.get("phone", ""),
                    "office_status": office.get("office_status", ""),
                    "parser": "busan_lifelong_office_cycle",
                }
            )
            rows.append(row)

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(offices),
        "reservation_discovery_links": len(rows),
        "pagination_detected": pagination_detected,
        "recursion_depth": 1,
        "branches": len(offices),
    }
    return dedupe_rows(rows), "busan_lifelong_office_cycle", meta


def michuhol_dl_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for dl in soup.select("dl"):
        dt = dl.find("dt")
        dd = dl.find("dd")
        if dt and dd:
            label = clean_text(dt.get_text(" ", strip=True))
            value = clean_text(dd.get_text(" ", strip=True))
        else:
            parts = [clean_text(part) for part in dl.get_text("\n", strip=True).splitlines() if clean_text(part)]
            label = parts[0] if parts else ""
            value = clean_text(" ".join(parts[1:])) if len(parts) > 1 else ""
        if label:
            pairs[label.rstrip(":")] = value
    return pairs


def michuhol_detail_description(soup: BeautifulSoup) -> str:
    heading = None
    for node in soup.find_all(["h3", "h4", "strong", "p", "dt"]):
        if clean_text(node.get_text(" ", strip=True)) == "강좌소개":
            heading = node
            break
    if not heading:
        return ""
    chunks: list[str] = []
    for sibling in heading.find_all_next():
        text = clean_text(sibling.get_text(" ", strip=True))
        if not text:
            continue
        if text in {"강의계획서", "참고사항", "신청하기", "목록"}:
            break
        if text != "강좌소개":
            chunks.append(text)
        if len(chunks) >= 4:
            break
    return clean_text(" ".join(chunks))


def michuhol_sq_from_url(url: str) -> str:
    query = parse_qs(urlparse(url).query)
    return clean_text((query.get("sq") or query.get("edu_sq") or [""])[0])


def collect_michuhol_education_apply(target: CrawlTarget, timeout: int, max_pages: int, detail_limit: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    address = "인천광역시 미추홀구 독정이로 95"

    for page in range(1, max(1, max_pages) + 1):
        query["page"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        page_rows = 0
        pages += 1
        for tr in soup.select("tbody tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
            if len(cells) < 8:
                continue
            title_link = tr.select_one("a[href*='step1.do']")
            if not title_link:
                continue
            title = clean_text(title_link.get_text(" ", strip=True))
            if not title or is_low_value_title(title):
                continue
            raw_url = normalize_link(current_url, title_link.get("href")) or current_url
            apply_link = tr.select_one("a[href*='step2.do']")
            application_url = normalize_link(current_url, apply_link.get("href") if apply_link else None) or raw_url
            category, _list_title, branch, apply_period, period, target_text, capacity, status = cells[:8]
            sq = michuhol_sq_from_url(raw_url)

            detail: dict[str, str] = {}
            description = ""
            if detail_pages < max(0, detail_limit):
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail = michuhol_dl_pairs(detail_soup)
                    description = michuhol_detail_description(detail_soup)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("Michuhol detail fetch failed %s: %s", raw_url, exc)

            detail_branch = clean_text(detail.get("기관") or branch or target.branch)
            detail_period = normalize_mixed_date_range(clean_text(detail.get("수강기간") or period))
            schedule = clean_text(" ".join(part for part in [detail.get("수강기간", ""), detail.get("교육시간", "")] if part))
            schedule = clean_text(re.sub(r"\d{4}-\d{2}-\d{2}\s*~\s*\d{4}-\d{2}-\d{2}", "", schedule).strip())
            schedule = clean_text(re.sub(r"\(\s*\)", "", schedule))

            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, detail_branch),
                    "title": title,
                    "branch": detail_branch,
                    "branch_code": clean_text((parse_qs(parsed.query).get("organ_cd") or [""])[0]) or re.sub(r"[^A-Za-z0-9가-힣]+", "_", detail_branch).strip("_"),
                    "category": clean_text(detail.get("분류") or category),
                    "raw_url": raw_url,
                    "application_url": application_url,
                    "status": clean_text(status),
                    "fee": clean_text(detail.get("수강료")),
                    "material_fee": clean_text(detail.get("재료비")),
                    "period": detail_period,
                    "apply_period": normalize_mixed_date_range(detail.get("접수일시") or apply_period),
                    "schedule_raw": schedule,
                    "target": clean_text(detail.get("교육대상")) or target_text,
                    "capacity": clean_text(detail.get("정원") or capacity),
                    "room": clean_text(detail.get("강의실")),
                    "venue_name": clean_text(detail.get("강의실") or detail_branch),
                    "address": address,
                    "venue_address": address,
                    "phone": clean_text(detail.get("문의처")),
                    "application_method_raw": clean_text(detail.get("접수방법")),
                    "description": description or clean_text(" ".join(cells)),
                    "collection_category": "공공예약",
                    "domain_category": "평생교육",
                    "operator_type": "지자체/공공기관",
                    "source_group": "public_reservation",
                    "collection_type": "static_html",
                    "program_type": "강좌",
                    "application_type": "ONLINE_RESERVATION",
                    "reservation_available": "신청" in clean_text(status),
                    "raw_fields": {"cells": cells, "detail_pairs": detail, "sq": sq, "parser": "michuhol_education_apply_table"},
                }
            )
            page_rows += 1

        pagination_detected = pagination_detected or page_rows >= 30
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "michuhol_education_apply_table", meta


def collect_ansan_reserve_cards(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    row_limit = 0
    try:
        row_limit = max(0, int(target.extra.get("per_target_limit") or 0))
    except (TypeError, ValueError):
        row_limit = 0

    view_path = parsed.path.split(";jsessionid", 1)[0].replace("List.do", "View.do")
    current_menu_no = clean_text((query.get("currentMenuNo") or [""])[0])

    for page in range(1, max_pages + 1):
        if row_limit > 0 and len(rows) >= row_limit:
            break
        query["pageIndex"] = [str(page)]
        clean_path = parsed.path.split(";jsessionid", 1)[0]
        current_url = parsed._replace(path=clean_path, params="", query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        pagination_detected = pagination_detected or bool(soup.select("a[onclick*='fnSearch'], a[href*='pageIndex=']"))

        for item in soup.select("ul.blog.reserv > li"):
            if row_limit > 0 and len(rows) >= row_limit:
                break
            link = item.select_one("a[onclick*='fnView']")
            title = clean_text((item.select_one(".txtW .tit") or {}).get_text(" ", strip=True) if item.select_one(".txtW .tit") else "")
            if not link or not title:
                continue
            onclick = clean_text(link.get("onclick"))
            match = re.search(r"fnView\('([^']+)'", onclick)
            reservation_id = clean_text(match.group(1) if match else "")
            detail_query = {"resrId": reservation_id}
            if current_menu_no:
                detail_query["currentMenuNo"] = current_menu_no
            raw_url = parsed._replace(path=view_path, params="", query=urlencode(detail_query)).geturl() if reservation_id else current_url

            pairs: dict[str, str] = {}
            for line in item.select(".txtW .etc li"):
                label_node = line.select_one(".em")
                label = clean_text(label_node.get_text(" ", strip=True) if label_node else "")
                if label_node:
                    label_node.extract()
                value = clean_text(line.get_text(" ", strip=True))
                if label:
                    pairs[label] = value

            status = clean_text((item.select_one(".label") or {}).get_text(" ", strip=True) if item.select_one(".label") else "")
            badges = [clean_text(node.get_text(" ", strip=True)) for node in item.select(".addLabel span")]
            fee = clean_text(pairs.get("\uC218\uAC15\uB8CC")) or next((badge for badge in badges if "원" in badge or badge in {"무료", "유료"}), "")
            branch = clean_text(pairs.get("기관/부서")) or target.branch
            period = normalize_mixed_date_range(clean_text(pairs.get("교육기간") or pairs.get("체험/견학기간") or pairs.get("예약기간")))
            apply_period = normalize_mixed_date_range(clean_text(pairs.get("접수기간") or pairs.get("신청기간")))
            weekday = clean_text(pairs.get("요일"))
            schedule_raw = clean_text(" ".join(part for part in [period, f"요일 {weekday}" if weekday else ""] if part))
            row_text = clean_text(item.get_text(" ", strip=True))

            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "category": "공공예약",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": fee,
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule_raw,
                    "target": clean_text(pairs.get("대상")),
                    "room": clean_text(pairs.get("위치")),
                    "venue_name": clean_text(pairs.get("위치")),
                    "description": row_text,
                    "raw_fields": {
                        "reservation_id": reservation_id,
                        "badges": badges,
                        "pairs": pairs,
                        "parser": "ansan_reserve_cards",
                    },
                }
            )
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ansan_reserve_cards", meta


