def nihc_list_url(content_uid: str, page: int = 1) -> str:
    query = {
        "page": str(page),
        "boardUid": NIHC_BOARD_UID,
        "contentUid": content_uid,
        "layoutUid": "",
        "searchType": "",
        "keyword": "",
        "categoryUid1": "",
        "categoryUid2": "",
        "cateogryUid3": "",
    }
    return f"{NIHC_BASE_URL}/planweb/board/list.9is?{urlencode(query)}"


def nihc_clean_date_text(value: str) -> str:
    text = clean_text(value)
    text = re.sub(r"\([^)]*\)", "", text)
    text = re.sub(r"(\d{4})\s*년", r"\1.", text)
    text = re.sub(r"(\d{1,2})\s*월", r"\1.", text)
    text = re.sub(r"(\d{1,2})\s*일", r"\1", text)
    text = text.replace("∼", "~").replace("~", " ~ ")
    return clean_text(text)


def nihc_normalize_date_range(value: Any, fallback_year: int | None = None) -> str:
    text = clean_text(value)
    if not text:
        return ""
    cleaned = nihc_clean_date_text(text)
    match = re.search(
        r"(\d{4})\s*[.-]\s*(\d{1,2})\s*[.-]\s*(\d{1,2})\s*[.]?\s*~\s*(?:(\d{4})\s*[.-]\s*)?(\d{1,2})\s*[.-]\s*(\d{1,2})",
        cleaned,
    )
    if match:
        start_year = int(match.group(1))
        end_year = int(match.group(4) or start_year)
        return (
            f"{start_year:04d}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"
            f" ~ {end_year:04d}-{int(match.group(5)):02d}-{int(match.group(6)):02d}"
        )
    match = re.search(r"(\d{1,2})\s*[.-]\s*(\d{1,2})\s*[.]?\s*~\s*(\d{1,2})\s*[.-]\s*(\d{1,2})", cleaned)
    if match and fallback_year:
        return (
            f"{fallback_year:04d}-{int(match.group(1)):02d}-{int(match.group(2)):02d}"
            f" ~ {fallback_year:04d}-{int(match.group(3)):02d}-{int(match.group(4)):02d}"
        )
    return normalize_mixed_date_range(text)


def nihc_period_and_schedule_from_card(value: Any) -> tuple[str, str]:
    text = clean_text(value)
    if not text:
        return "", ""
    bracket = ""
    bracket_match = re.search(r"\[([^\]]+)\]", text)
    if bracket_match:
        bracket = clean_text(bracket_match.group(1))
    period = nihc_normalize_date_range(re.sub(r"\[[^\]]+\]", "", text))
    return period, bracket


def nihc_info_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in soup.select(".infoBox li"):
        key_node = item.find("strong")
        value_node = item.find("span")
        key = clean_text(key_node.get_text(" ", strip=True) if key_node else "")
        if not key or not value_node:
            continue
        value = clean_text(value_node.get_text(" ", strip=True))
        marker = clean_text((value_node.find("em") or {}).get_text(" ", strip=True) if value_node.find("em") else "")
        if marker and value.startswith(marker):
            value = clean_text(value[len(marker) :])
        if value:
            pairs[key] = value
    return pairs


def nihc_detail_description(soup: BeautifulSoup) -> str:
    view = soup.select_one(".viewList .view-con")
    if not view:
        return ""
    return clean_text(view.get_text(" ", strip=True))[:3000]


def nihc_labeled_value(text: str, labels: tuple[str, ...]) -> str:
    source = clean_text(text)
    stop_labels = (
        "모집기간",
        "모집인원",
        "모집대상",
        "교육명",
        "교육목적",
        "교육기간",
        "교육장소",
        "교육대상",
        "교육내용",
        "운영일수",
        "운영 시간",
        "신청기간",
        "신청방법",
        "전화 문의",
        "교육비",
        "교재비",
        "참가비",
        "수강료",
        "기타사항",
        "문의전화",
    )
    stop_pattern = "|".join(rf"(?:[ㆍ·\-*]\s*)?{re.escape(label)}\s*(?:[:：]|\s)" for label in stop_labels)
    for label in labels:
        pattern = rf"(?:^|\s)(?:[ㆍ·\-*]\s*)?{re.escape(label)}\s*[:：]?\s*(.*?)(?=\s*(?:{stop_pattern})|$)"
        match = re.search(pattern, source, re.DOTALL)
        if match:
            return clean_text(match.group(1))
    return ""


def nihc_application_link(detail_url: str, soup: BeautifulSoup) -> str:
    candidates: list[str] = []
    for a in soup.select(".view-con a[href], #boardWrap a[href]"):
        text = clean_text(a.get_text(" ", strip=True))
        href = normalize_link(detail_url, a.get("href"))
        if not href:
            continue
        haystack = f"{text} {href}".lower()
        if any(token in haystack for token in ("support.nihc.go.kr", "apply", "crse", "edu", "신청", "접수", "예약")):
            candidates.append(href)
    return candidates[0] if candidates else ""


def nihc_image_url(base_url: str, *nodes: Any) -> str:
    for node in nodes:
        if not node:
            continue
        for image in node.select("img[src]") if hasattr(node, "select") else []:
            raw_src = clean_text(image.get("src"))
            if not raw_src or raw_src.startswith(("data:", "javascript:")):
                continue
            src = urldefrag(urljoin(base_url, raw_src))[0]
            parsed = urlparse(src)
            if parsed.scheme not in {"http", "https"} or not parsed.netloc:
                continue
            if src and not any(token in src.lower() for token in ("logo", "favicon", "blank")):
                return src
    return ""


def nihc_material_note(description: str) -> str:
    lines = [clean_text(line) for line in re.split(r"[\r\n]|(?=\s*[ㆍ·\-*]\s*)", description) if clean_text(line)]
    notes = [line for line in lines if any(token in line for token in ("재료비", "재료", "준비물", "체험 키트", "꾸러미"))]
    return clean_text(" ".join(notes))[:500]


def nihc_should_skip_expired(period: str) -> bool:
    _, end_date = parse_date_range(period)
    return bool(end_date and end_date < datetime.now().astimezone().date())


def collect_national_intangible_heritage_center(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    seen_urls: set[str] = set()
    effective_max_pages = max(1, max_pages)

    for section_name, content_uid in NIHC_CONTENTS:
        stop_section = False
        for page in range(1, effective_max_pages + 1):
            current_url = nihc_list_url(content_uid, page)
            soup = fetch_soup(s, current_url, timeout=timeout)
            items = soup.select("ul.type-thumb > li")
            course_items = [item for item in items if item.select_one("dt")]
            if not course_items:
                break
            pages += 1
            pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='page=']"))

            for item in course_items:
                title = clean_text((item.select_one("dt") or item).get_text(" ", strip=True))
                if not title or is_low_value_title(title):
                    continue

                dds = [clean_text(dd.get_text(" ", strip=True)) for dd in item.select("dd") if clean_text(dd.get_text(" ", strip=True))]
                period, card_schedule = nihc_period_and_schedule_from_card(dds[0] if dds else "")
                if nihc_should_skip_expired(period):
                    continue

                status = next((value for value in reversed(dds) if status_has_course_state(value) or "신청가능" in value), "")
                link = item.select_one(".btn_rev a[href]") or item.find("a", href=True)
                raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
                if raw_url in seen_urls:
                    continue
                seen_urls.add(raw_url)

                image_url = nihc_image_url(current_url, item)
                info_pairs: dict[str, str] = {}
                description = ""
                application_url = ""
                material_note = ""
                material_fee = None
                detail_pairs_from_text: dict[str, str] = {}
                detail_image_url = ""
                if raw_url and detail_pages < max(1, detail_limit):
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail_pages += 1
                        info_pairs = nihc_info_pairs(detail_soup)
                        description = nihc_detail_description(detail_soup)
                        application_url = nihc_application_link(raw_url, detail_soup)
                        detail_image_url = nihc_image_url(raw_url, detail_soup.select_one(".thumbnail"), detail_soup.select_one(".view-con"))
                        material_note = nihc_material_note(description)
                        material_fee = extract_material_fee_amount(material_note, description)
                        detail_pairs_from_text = {
                            "period": nihc_labeled_value(description, ("교육기간",)),
                            "apply_period": nihc_labeled_value(description, ("신청기간", "모집기간", "접수기간")),
                            "target": nihc_labeled_value(description, ("교육대상", "모집대상", "참여대상", "대상")),
                            "fee": nihc_labeled_value(description, ("교육비", "교재비", "참가비", "수강료")),
                            "application_method": nihc_labeled_value(description, ("신청방법",)),
                            "capacity": nihc_labeled_value(description, ("모집인원", "모집인원 및 일수")),
                            "room": nihc_labeled_value(description, ("교육장소",)),
                        }
                    except Exception as exc:
                        logger.debug("NIHC detail fetch failed %s: %s", raw_url, exc)

                info_title = clean_text(info_pairs.get("제목"))
                if info_title:
                    title = info_title
                info_period = clean_text(info_pairs.get("일정"))
                if info_period:
                    period = nihc_normalize_date_range(info_period) or period
                fallback_year = None
                parsed_start, _ = parse_date_range(period)
                if parsed_start:
                    fallback_year = parsed_start.year
                detail_period = nihc_normalize_date_range(detail_pairs_from_text.get("period"), fallback_year=fallback_year)
                if detail_period:
                    period = detail_period
                if nihc_should_skip_expired(period):
                    continue

                schedule_parts = []
                detail_period_raw = clean_text(detail_pairs_from_text.get("period"))
                weekday_tail = re.sub(r".*?~\s*(?:\d{4}[.\-]\s*)?\d{1,2}[.\-]\s*\d{1,2}[.]?\s*,?", "", nihc_clean_date_text(detail_period_raw))
                if weekday_tail and weekday_tail != detail_period_raw:
                    schedule_parts.append(weekday_tail)
                for value in (clean_text(info_pairs.get("교육시간")), card_schedule):
                    if value and value not in schedule_parts:
                        schedule_parts.append(value)

                apply_period = clean_text(info_pairs.get("접수기간"))
                detail_apply_period = nihc_normalize_date_range(detail_pairs_from_text.get("apply_period"), fallback_year=fallback_year)
                if detail_apply_period:
                    apply_period = detail_apply_period
                elif apply_period:
                    apply_period = nihc_normalize_date_range(apply_period) or apply_period

                category = clean_text(info_pairs.get("교육구분")) or section_name
                target_text = clean_text(info_pairs.get("교육대상") or detail_pairs_from_text.get("target"))
                room = clean_text(info_pairs.get("교육장소") or detail_pairs_from_text.get("room"))
                fee = clean_text(detail_pairs_from_text.get("fee"))
                if "무료" in fee and any(token in fee for token in ("재료비", "재료", "준비물")):
                    material_note = clean_text(" ".join(part for part in [material_note, fee] if part))[:500]
                    material_fee = material_fee or extract_material_fee_amount(material_note)
                    fee = "무료"
                if not fee and "무료" in description:
                    fee = "무료"
                application_method = clean_text(detail_pairs_from_text.get("application_method"))
                contact = clean_text(info_pairs.get("담당자 연락처")) or NIHC_PHONE

                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                        "title": title,
                        "branch": target.branch,
                        "branch_code": target.provider,
                        "category": category,
                        "raw_url": raw_url,
                        "application_url": application_url,
                        "status": status,
                        "fee": fee,
                        "material_fee": material_fee,
                        "material_note": material_note,
                        "period": period,
                        "apply_period": apply_period,
                        "schedule_raw": clean_text(" ".join(schedule_parts)),
                        "target": target_text,
                        "capacity": clean_text(detail_pairs_from_text.get("capacity")),
                        "room": room,
                        "venue_name": room or target.branch,
                        "venue_address": NIHC_ADDRESS,
                        "address": NIHC_ADDRESS,
                        "phone": contact,
                        "instructor": clean_text(info_pairs.get("담당자")),
                        "application_method_raw": application_method,
                        "description": description,
                        "image_url": detail_image_url or image_url,
                        "program_type": "강좌",
                        "collection_category": "박물관/과학관",
                        "domain_category": "문화유산/체험",
                        "source_group": "national_institution",
                        "operator_type": "국립/공공기관",
                        "collection_type": "static_html",
                        "preserve_branch": True,
                        "raw_fields": {
                            "parser": "nihc_type_thumb_detail",
                            "section": section_name,
                            "content_uid": content_uid,
                            "card_dds": dds,
                            "info_pairs": info_pairs,
                            "detail_pairs_from_text": detail_pairs_from_text,
                            "robots_disallow_all": True,
                        },
                    }
                )
            if stop_section:
                break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen_urls),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "robots_disallow_all": True,
    }
    return dedupe_rows(rows), "nihc_type_thumb_detail", meta


def national_ocean_schedule_text(value: Any) -> str:
    text = clean_text(value)
    ranges = [
        clean_text(match.group(0))
        for match in re.finditer(r"\d{1,2}:\d{2}\s*(?:~|-|–)\s*\d{1,2}:\d{2}", text)
    ]
    if ranges:
        return clean_text(" / ".join(dict.fromkeys(ranges[:6])))
    for label in ("교육시간", "운영시간"):
        if label not in text:
            continue
        tail = clean_text(text.split(label, 1)[-1]).lstrip(":： ")
        for token in ("교육 대상", "교육기간", "운영 기간", "참여인원", "문의", "📅", "📝", "📞", "👥", "🌊"):
            if token in tail:
                tail = clean_text(tail.split(token, 1)[0])
        if tail:
            return tail[:80]
    return ""


def collect_national_ocean_science(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": target.url, "X-Requested-With": "XMLHttpRequest"})
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    for page in range(1, max_pages + 1):
        response = s.get(
            "https://www.kosm.or.kr/kosm/bbs/boardAjax.do",
            params={"bbsId": "BSD0008", "type": "r", "pageIndex": page},
            timeout=timeout,
        )
        response.raise_for_status()
        payload = response.json()
        items = payload.get("list") or []
        if not items:
            break
        pages += 1
        for item in items:
            title = clean_text(item.get("sj"))
            if not title or is_low_value_title(title):
                continue
            bbs_seq = clean_text(item.get("bbsSeq"))
            raw_url = f"https://www.kosm.or.kr/kosm/bbs/boardView.do?idx={bbs_seq}&pageNo=1&bbsId=BSD0008"
            reserve_url = f"https://www.kosm.or.kr/kosm/reserve/smartReserve.do?bbsSeq={bbs_seq}&bbsId=BSD0008"
            file_row = item.get("file") if isinstance(item.get("file"), dict) else {}
            image_url = ""
            if file_row:
                image_url = normalize_link(target.url, f"/upload/M0060/{clean_text(file_row.get('streFileNm'))}")
            description = clean_text(item.get("rsvtReference"))
            if detail_pages < max_pages * 2:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    text = clean_text(detail_soup.get_text(" ", strip=True))
                    if "문의처" in text:
                        description = clean_text(text.split("문의처", 1)[-1])[:2000]
                    detail_image = detail_soup.select_one(".view_cont img, .board_view img, img")
                    if detail_image:
                        image_url = image_url or normalize_link(raw_url, detail_image.get("src"))
                except Exception as exc:
                    logger.debug("national ocean detail fetch failed %s: %s", raw_url, exc)
            schedule = clean_text(item.get("rsvtTime") or item.get("timeInfo")) or national_ocean_schedule_text(description)
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "category": clean_text(item.get("rsvtCateg") or item.get("bbsNm")),
                    "raw_url": raw_url,
                    "application_url": reserve_url if clean_text(item.get("rsvtTypek")) == "온라인" else raw_url,
                    "status": clean_text(item.get("rsvtStatusk")),
                    "fee": "무료" if clean_text(item.get("rsvtCost")) in {"0", "0.0"} else clean_text(item.get("rsvtCost")),
                    "period": f"{clean_text(item.get('startDatef'))} ~ {clean_text(item.get('endDatef'))}",
                    "apply_period": f"{clean_text(item.get('rsvtStartDatef'))} ~ {clean_text(item.get('rsvtEndDatef'))}",
                    "schedule_raw": schedule,
                    "target": clean_text(item.get("rsvtTarget") or item.get("rsvtTargetk")),
                    "capacity": clean_text(item.get("rsvtPeopleLimit")),
                    "room": clean_text(item.get("rsvtPlace")),
                    "venue_name": clean_text(item.get("rsvtPlace")),
                    "application_method_raw": clean_text(item.get("rsvtTypek")),
                    "program_type": "강좌",
                    "description": description,
                    "image_url": image_url,
                    "raw_fields": {"bbsSeq": bbs_seq, "parser": "national_ocean_board_ajax"},
                }
            )
        if page >= int(payload.get("pageCount") or page):
            break
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages < int((locals().get("payload") or {}).get("pageCount") or pages),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "national_ocean_board_ajax", meta


def collect_national_park_reservation(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": target.url, "X-Requested-With": "XMLHttpRequest"})
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    pages = 0
    groups = [("G", "해설탐방/환경교육"), ("H", "치유탐방 프로그램"), ("PET", "반려견 동반")]
    for orgnzt_gbn, group_name in groups:
        for page in range(1, max_pages + 1):
            response = s.post(
                "https://res.knps.or.kr/trprogram/trprogramList.do",
                data={
                    "dept_id": "",
                    "dept_name": "전체",
                    "orgnzt_gbn": orgnzt_gbn,
                    "pageNo": page,
                    "listScale": 10,
                },
                timeout=timeout,
            )
            response.raise_for_status()
            soup = BeautifulSoup(response.text, "lxml")
            body_rows = soup.select("table tbody tr") or soup.select("tr")[1:]
            if not body_rows:
                break
            pages += 1
            for tr in body_rows:
                cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
                if len(cells) < 5:
                    continue
                park_name = cells[1]
                venue = cells[2]
                title = cells[3]
                period = cells[4]
                link = tr.find("a", href=True)
                raw_url = normalize_link("https://res.knps.or.kr", link.get("href") if link else None) or target.url
                row = {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": park_name or target.branch,
                    "category": group_name,
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": "예약가능",
                    "period": period,
                    "schedule_raw": period,
                    "room": venue,
                    "venue_name": venue,
                    "description": "",
                    "raw_fields": {"orgnzt_gbn": orgnzt_gbn, "parser": "national_park_trprogram"},
                }
                if raw_url and detail_pages < max_pages * 4:
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail_pages += 1
                        pairs = pairs_from_definition_lists(detail_soup)
                        description = first_by_keys(pairs, ("주요내용", "주의사항", "내용"))
                        row["description"] = description
                        row["target"] = first_by_keys(pairs, ("참가대상", "대상")) or row.get("target", "")
                        row["capacity"] = first_by_keys(pairs, ("참가인원", "정원")) or row.get("capacity", "")
                        row["application_method_raw"] = first_by_keys(pairs, ("참가방법", "예약방법")) or row.get("application_method_raw", "")
                    except Exception as exc:
                        logger.debug("national park detail fetch failed %s: %s", raw_url, exc)
                rows.append(row)
            if page >= 1 and len(body_rows) < 10:
                break
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages >= max_pages,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "national_park_trprogram", meta


