def dgs_dong_key(value: Any) -> str:
    return clean_text(value).replace("쨌", ",").replace(" ", "")


def dgs_dong_display(value: Any) -> str:
    return dgs_dong_key(value).replace(",", "쨌")


def dgs_dong_code(value: Any) -> str:
    key = dgs_dong_key(value)
    for index, dong in enumerate(DGS_DONG_DIRECTION_MIDS, start=1):
        if dgs_dong_key(dong) == key:
            return f"DGS_LCTR_{index:02d}"
    digest = hashlib.sha1(key.encode("utf-8")).hexdigest()[:8].upper()
    return f"DGS_LCTR_{digest}"


def dgs_card_pairs(item: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in item.select(".info-wrap li"):
        label_node = li.find("span")
        label = clean_text(label_node.get_text(" ", strip=True) if label_node else "")
        text = clean_text(li.get_text(" ", strip=True))
        value = clean_text(text.replace(label, "", 1)) if label else text
        if label and value:
            pairs[label] = value
    return pairs


def dgs_table_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    table = soup.select_one("table.edu_info") or soup.select_one("table")
    if not table:
        return pairs
    for tr in table.select("tr"):
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"], recursive=False)]
        cells = [cell for cell in cells if cell]
        for index in range(0, len(cells) - 1, 2):
            key = cells[index]
            value = cells[index + 1]
            if key and value and len(key) <= 20:
                pairs[key] = value
    return pairs


def dgs_normalize_fee(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    if "무료" in text:
        return "무료"
    match = re.search(r"(\d+(?:[.,]\d+)?)\s*만\s*원", text)
    if match:
        amount = int(float(match.group(1).replace(",", "")) * 10000)
        return f"{amount:,}원"
    match = re.search(r"(\d+(?:[.,]\d+)?)\s*천\s*원", text)
    if match:
        amount = int(float(match.group(1).replace(",", "")) * 1000)
        return f"{amount:,}원"
    return text


def dgs_branch_info_from_direction_pages(s: requests.Session, timeout: int) -> dict[str, dict[str, str]]:
    output: dict[str, dict[str, str]] = {}
    for dong, mid in DGS_DONG_DIRECTION_MIDS.items():
        url = f"https://www.dgs.go.kr/dong/contents.do?mid={mid}"
        try:
            soup = fetch_soup(s, url, timeout=timeout)
        except Exception as exc:
            logger.debug("DGS dong direction fetch failed %s: %s", url, exc)
            continue
        address_node = soup.select_one(".mapInfo .map_adress span:last-child")
        phone_node = soup.select_one(".mapInfo .map_call span:last-child")
        address = clean_text(address_node.get_text(" ", strip=True) if address_node else "")
        phone = clean_text(phone_node.get_text(" ", strip=True) if phone_node else "")
        output[dgs_dong_key(dong)] = {
            "address": address,
            "phone": phone,
            "url": url,
        }
    return output


def collect_dgs_lctr_center_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    seen_idxs: set[tuple[str, str]] = set()
    branch_infos = dgs_branch_info_from_direction_pages(s, timeout)

    for source in DGS_RESERVE_SOURCES:
        for page in range(1, max(1, max_pages) + 1):
            current_url = f"{source['list_url']}&page={page}"
            soup = fetch_soup(s, current_url, timeout=timeout)
            items = soup.select(".edu-application .item")
            if not items:
                break
            pages += 1
            pagination_detected = pagination_detected or bool(soup.select(".bod_page a, .bod_page span"))
            page_rows = 0

            for item in items:
                link = item.find("a")
                href = clean_text(link.get("href") if link else "")
                idx = clean_text(link.get("data-req-get-p-idx") if link else "")
                if not idx and href:
                    idx = clean_text((parse_qs(urlparse(href).query).get("idx") or [""])[0])
                key = (clean_text(source["key"]), idx)
                if not idx or key in seen_idxs:
                    continue
                seen_idxs.add(key)

                title = clean_text((item.select_one(".btxt") or item).get_text(" ", strip=True))
                if not title or is_low_value_title(title):
                    continue
                card_pairs = dgs_card_pairs(item)
                status = clean_text((item.select_one(".text_ing") or item.select_one(".state") or item).get_text(" ", strip=True))
                detail_pairs: dict[str, str] = {}
                raw_url = f"{source['view_url']}&idx={idx}"
                if detail_limit <= 0 or detail_pages < detail_limit:
                    try:
                        if source["detail_method"] == "post":
                            detail_response = s.post(source["view_url"], data={"idx": idx, "page": str(page)}, timeout=timeout)
                        else:
                            detail_response = s.get(raw_url, timeout=timeout)
                        detail_response.raise_for_status()
                        if not detail_response.encoding or detail_response.encoding.lower() == "iso-8859-1":
                            detail_response.encoding = detail_response.apparent_encoding
                        detail_soup = BeautifulSoup(detail_response.text, "lxml")
                        detail_pairs = dgs_table_pairs(detail_soup)
                        detail_pages += 1
                    except Exception as exc:
                        logger.debug("DGS detail fetch failed source=%s idx=%s: %s", source["key"], idx, exc)

                if source["key"] == "lctrCntr":
                    dong = clean_text(detail_pairs.get("동명") or (item.select_one(".stxt") or item).get_text(" ", strip=True))
                    dong_key = dgs_dong_key(dong)
                    dong_display = dgs_dong_display(dong)
                    branch = f"{dong_display} 주민자치센터"
                    branch_info = branch_infos.get(dong_key, {})
                    branch_code = dgs_dong_code(dong)
                    address = clean_text(branch_info.get("address"))
                    phone = clean_text(branch_info.get("phone"))
                    branch_url = clean_text(branch_info.get("url"))
                    period = clean_text(detail_pairs.get("운영기간") or card_pairs.get("운영기간"))
                    schedule = clean_text(detail_pairs.get("시간") or card_pairs.get("시간"))
                    fee_raw = clean_text(detail_pairs.get("이용료"))
                    room = clean_text(detail_pairs.get("장소"))
                    capacity = clean_text(detail_pairs.get("인원") or card_pairs.get("인원"))
                    instructor = clean_text(detail_pairs.get("강사") or card_pairs.get("강사"))
                    target_text = clean_text(source["target"])
                    title = clean_text(detail_pairs.get("강좌명") or title)
                    application_method = "동 행정복지센터 문의"
                else:
                    branch = clean_text(source["branch"])
                    branch_code = clean_text(source["branch_code"])
                    address = clean_text(source["address"])
                    phone = ""
                    branch_url = clean_text(source["list_url"])
                    period = clean_text(detail_pairs.get("수강기간") or detail_pairs.get("교육기간") or card_pairs.get("교육기간"))
                    schedule = clean_text(detail_pairs.get("강의시간") or card_pairs.get("강의시간"))
                    fee_raw = clean_text(detail_pairs.get("이용료") or detail_pairs.get("수강료"))
                    room = clean_text(detail_pairs.get("강의장소"))
                    capacity = clean_text(detail_pairs.get("신청인원") or card_pairs.get("신청인원"))
                    instructor = clean_text(detail_pairs.get("강사명") or card_pairs.get("강사명"))
                    target_text = clean_text(source["target"])
                    title = clean_text(detail_pairs.get("강좌명") or detail_pairs.get("개설과정") or title)
                    application_method = clean_text(detail_pairs.get("접수방법"))

                period_has_time = bool(re.search(r"\d{1,2}\s*(?::|시)\s*\d{0,2}", period))
                period_has_date = bool(re.search(r"\d{4}|(?:\d{1,2}\s*[./월]\s*\d{1,2})|(?:\d{1,2}\s*월)", period))
                if period == "시간":
                    period = ""
                if not schedule and period_has_time:
                    schedule = period
                if not period or (period_has_time and not period_has_date):
                    period = "상시"
                if not schedule:
                    schedule = "운영시간 미표기"
                content = clean_text(detail_pairs.get("내용") or detail_pairs.get("기타사항"))
                description = content or clean_text(
                    " / ".join(
                        part
                        for part in [
                            f"분류 {source['category']}",
                            f"기간 {period}" if period else "",
                            f"시간 {schedule}" if schedule else "",
                            f"이용료 {fee_raw}" if fee_raw else "",
                            f"장소 {room}" if room else "",
                        ]
                        if part
                    )
                )
                application_url = "" if "마감" in status else raw_url

                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": f"{source['key']}:{idx}",
                        "title": title,
                        "branch": branch,
                        "branch_code": branch_code,
                        "category": clean_text(source["category"]),
                        "raw_url": raw_url,
                        "application_url": application_url,
                        "status": status or ("상시운영" if source["key"] == "lctrCntr" else ""),
                        "fee": dgs_normalize_fee(fee_raw),
                        "period": period,
                        "schedule_raw": schedule,
                        "target": target_text,
                        "capacity": capacity,
                        "capacity_total": capacity,
                        "instructor": instructor,
                        "room": room,
                        "venue_name": room or branch,
                        "venue_address": address,
                        "address": address,
                        "phone": phone,
                        "branch_url": branch_url,
                        "application_method_raw": application_method,
                        "description": description,
                        "program_type": "강좌",
                        "collection_category": "공공예약",
                        "domain_category": "공공예약",
                        "source_group": "public_reservation",
                        "operator_type": "지자체/공공기관",
                        "collection_type": "static_html",
                        "preserve_branch": True,
                        "raw_fields": {
                            "parser": "dgs_reserve_three_lists+detail",
                            "source_key": source["key"],
                            "idx": idx,
                            "card_pairs": card_pairs,
                            "detail_pairs": detail_pairs,
                            "fee_raw": fee_raw,
                        },
                    }
                )
                page_rows += 1
            if page_rows == 0:
                break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen_idxs),
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "branch_address_count": sum(1 for value in branch_infos.values() if value.get("address")),
        "source_count": len(DGS_RESERVE_SOURCES),
    }
    return dedupe_rows(rows), "dgs_reserve_three_lists+detail", meta


def gwangju_status(row: dict[str, Any]) -> str:
    if clean_text(row.get("acceptDiv")) == "E":
        return "접수마감"
    status = clean_text(row.get("status"))
    if status == "R":
        return "접수대기"
    if status == "S":
        try:
            applicant = int(row.get("applicantCnt") or 0)
            limit = int(row.get("limit") or 0)
            standby = int(row.get("standbyLimit") or 0) if clean_text(row.get("standbyYn")) == "Y" else 0
        except (TypeError, ValueError):
            applicant = limit = standby = 0
        return "접수불가" if limit and applicant >= limit + standby else "접수중"
    if status == "E":
        return "접수마감"
    return status


GWANGJU_ADDRESS_PATTERN = re.compile(
    r"(?P<addr>(?:동구|서구|남구|북구|광산구)\s+[가-힣A-Za-z0-9\s]+(?:대로|번길|로|길)\s*\d+(?:-\d+)?)"
)

GWANGJU_CITY_HALL_ADDRESS = "광주광역시 서구 내방로 111"
GWANGJU_INVALID_VENUES = {"신청 장소", "회차별상세", "광주"}
GWANGJU_CITY_HALL_DEPTS = {"안전정책관", "관리운영과"}
GWANGJU_KNOWN_BRANCH_ADDRESSES = {
    "광주AI창업캠프": "광주광역시 동구 금남로 193-22",
    "광주AI창업캠프 4층 교육실": "광주광역시 동구 금남로 193-22",
    "광주광역시 일생활균형지원센터": "광주광역시 서구 무진대로 576",
    "광주광역시 농업기술센터": "광주광역시 광산구 평동로 639-22",
    "광주광역시 보건환경연구원": "광주광역시 서구 무진대로 584",
    "광주광역시청": GWANGJU_CITY_HALL_ADDRESS,
    "광주김치타운": "광주광역시 남구 김치로 60",
    "광주역사민속박물관": "광주광역시 북구 서하로 48-25",
    "혁신농가공창업보육센터": "광주광역시 광산구 평동로 639-22",
    "화계초등학교": "광주광역시 광산구 화계로 155",
    "유덕동 전시온실정원": "광주광역시 서구 유촌동 820-8",
    "유오빌딩": "광주광역시 동구 금남로 193-22",
    "유오파크": "광주광역시 동구 금남로 193-22",
}


def gwangju_complete_address(value: str) -> str:
    address = clean_text(value)
    if not address:
        return ""
    if address.startswith("광주광역시"):
        return address
    if re.match(r"^(동구|서구|남구|북구|광산구)\s+", address):
        return f"광주광역시 {address}"
    return address


def gwangju_extract_address(value: Any) -> str:
    text = clean_text(value)
    match = GWANGJU_ADDRESS_PATTERN.search(text)
    return gwangju_complete_address(match.group("addr")) if match else ""


def gwangju_should_skip_item(item: dict[str, Any], title: str) -> bool:
    if title == "부하테스트":
        return True
    return False


def gwangju_normalize_branch(item: dict[str, Any], target: CrawlTarget) -> tuple[str, str, str]:
    venue = clean_text(item.get("eduAddress"))
    dept = clean_text(item.get("manageDeptName"))
    address = gwangju_extract_address(venue)
    value = re.sub(r"\([^)]*\)", "", venue).strip()

    if not value or value in GWANGJU_INVALID_VENUES:
        if dept in GWANGJU_CITY_HALL_DEPTS or value in {"신청 장소", "광주"}:
            branch = "광주광역시청"
            address = address or GWANGJU_CITY_HALL_ADDRESS
        else:
            branch = dept or target.branch
    elif "역사민속박물관" in value:
        branch = "광주역사민속박물관"
    elif "농업기술센터" in value:
        branch = "광주광역시 농업기술센터"
    elif "김치타운" in value or "김치발효식품관" in value:
        branch = "광주김치타운"
    elif "광주문학관" in value:
        branch = "광주문학관"
    elif "광주광역시청" in value:
        branch = "광주광역시청"
        address = address or GWANGJU_CITY_HALL_ADDRESS
    elif "보건환경연구원" in value:
        branch = "광주광역시 보건환경연구원"
    elif "일생활균형지원센터" in value:
        branch = "광주광역시 일생활균형지원센터"
    elif "무등산분청사기" in value:
        branch = "무등산분청사기전시실"
    elif "예술의전당" in value:
        branch = "광주예술의전당"
    else:
        branch = re.sub(r"\s*(?:\d+층|[0-9]+층|시청각실|교육관|교육체험관|발효교육체험관|생활문화교육관|유리온실)$", "", value).strip()
        branch = branch or dept or target.branch

    address = address or GWANGJU_KNOWN_BRANCH_ADDRESSES.get(branch, "")
    return branch[:100], venue, address


def collect_gwangju_booking(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    page_id = (query.get("pageId") or ["reserve1"])[0]
    search_cate1 = (query.get("searchCate1") or ["A"])[0]
    search_cate2 = (query.get("searchCate2") or [""])[0]
    endpoint = f"{parsed.scheme}://{parsed.netloc}/reserve/getBookingList.do"
    referer = target.url
    s.headers.update({"Referer": referer, "X-Requested-With": "XMLHttpRequest"})

    rows: list[dict[str, Any]] = []
    total_count = 0
    page_count = 0
    for page in range(1, max_pages + 1):
        payload = {
            "pageId": page_id,
            "movePage": str(page),
            "searchCate1": search_cate1,
            "searchCate2": search_cate2,
            "searchEduTargetChk": "",
            "searchEduPriceTypeChk": "",
            "bookingCode": "0",
            "userId": "",
            "searchQuery": "",
            "searchDept": "",
            "searchState": "",
            "searchPeriod": "R",
            "searchStartDate": "",
            "searchEndDate": "",
            "searchEduType": "",
            "searchEduTarget": "",
            "searchEduPriceType": "",
        }
        response = s.post(endpoint, data=payload, timeout=timeout)
        response.raise_for_status()
        data = response.json()
        if clean_text(data.get("error")) != "N":
            break
        data_map = data.get("dataMap") or {}
        items = data_map.get("list") or []
        total_count = int(float(data_map.get("totalCnt") or total_count or 0))
        page_count = int(float(data_map.get("pageCnt") or page_count or 0))
        if not items:
            break
        for item in items:
            booking_code = clean_text(item.get("bookingCode"))
            title = clean_text(item.get("eduNm"))
            if not title:
                continue
            if gwangju_should_skip_item(item, title):
                continue
            branch, venue_name, venue_address = gwangju_normalize_branch(item, target)
            start_edu_date = clean_text(item.get("startEduDate"))
            end_edu_date = clean_text(item.get("endEduDate"))
            start_edu_time = clean_text(item.get("startEduTime"))
            end_edu_time = clean_text(item.get("endEduTime"))
            status = gwangju_status(item)
            raw_url = urljoin(
                target.url,
                f"/reserve/bookingView.do?pageId={page_id}&searchCate1={search_cate1}&bookingCode={booking_code}",
            )
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "preserve_branch": True,
                    "category": clean_text(item.get("cateNm")) or search_cate1,
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "application_type": "ONLINE_RESERVATION",
                    "reservation_available": status in {"접수중", "접수대기"},
                    "discovery_status": "gwangju_booking_api",
                    "status": status,
                    "fee": "유료" if clean_text(item.get("eduPriceType")) == "P" else "무료",
                    "period": f"{start_edu_date} ~ {end_edu_date}" if start_edu_date and end_edu_date else "",
                    "apply_period": (
                        f"{clean_text(item.get('startPeriodDate'))} ~ {clean_text(item.get('endPeriodDate'))}"
                        if item.get("startPeriodDate") and item.get("endPeriodDate")
                        else ""
                    ),
                    "schedule_raw": clean_text(" ~ ".join(part for part in [start_edu_time, end_edu_time] if part)),
                    "target": clean_text(item.get("eduTarget") or item.get("targetNm")),
                    "room": venue_name,
                    "venue_name": venue_name,
                    "venue_address": venue_address,
                    "address": venue_address,
                    "instructor": clean_text(item.get("charge")),
                    "phone": clean_text(item.get("information")),
                    "capacity_total": item.get("limit"),
                    "capacity_current": item.get("applicantCnt"),
                    "waitlist_total": item.get("standbyLimit"),
                    "description": html_to_text(item.get("contents")),
                    "material_note": html_to_text(item.get("notes")),
                    "image_url": urljoin(target.url, clean_text(item.get("fileMediaThumbUrl"))),
                    "raw_fields": {
                        "parser": "gwangju_booking_api",
                        "area": clean_text(item.get("areaNm")),
                        "area_code": clean_text(item.get("areaCode")),
                        "manage_dept": clean_text(item.get("manageDept")),
                        "manage_dept_name": clean_text(item.get("manageDeptName")),
                        "cate_code": clean_text(item.get("cateCode")),
                        "edu_address": clean_text(item.get("eduAddress")),
                        "accept_div": clean_text(item.get("acceptDiv")),
                        "status": clean_text(item.get("status")),
                    },
                }
            )
        if page_count and page >= page_count:
            break

    meta = {
        "pages": min(max_pages, page_count or max_pages) if rows else 0,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": page_count > 1,
        "recursion_depth": 0,
        "total_count": total_count,
        "page_count": page_count,
    }
    return dedupe_rows(rows), "gwangju_booking_api", meta


PC_RESERVATION_BASE = "https://reserve.pc.go.kr"
PC_RESERVATION_PATHS = (
    ("/pcreserve/reserve/sport", "공공체육시설", "스포츠시설"),
    ("/pcreserve/reserve/culture", "문화시설", "문화시설"),
    ("/pcreserve/training/facility", "전지훈련시설", "스포츠시설"),
)


def pc_reservation_address(value: Any) -> str:
    address = clean_text(value)
    if not address:
        return ""
    if address.startswith(("강원특별자치도", "강원도")):
        return address
    if address.startswith("평창군"):
        return f"강원특별자치도 {address}"
    return f"강원특별자치도 평창군 {address}"


def pc_reservation_span_pairs(node: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not node:
        return pairs
    for span in node.select("span"):
        label_node = span.find("strong")
        label = clean_text(label_node.get_text(" ", strip=True)) if label_node else ""
        value = clean_text(span.get_text(" ", strip=True))
        if label and value.startswith(label):
            value = clean_text(value[len(label):])
        if label and value:
            pairs[label] = value
    return pairs


def pc_reservation_first_fee_text(soup: BeautifulSoup) -> str:
    content = soup.select_one(".preview") or soup.select_one("#content") or soup
    text = clean_text(content.get_text(" ", strip=True))
    match = re.search(r"\d{1,3}(?:,\d{3})+\s*원", text)
    return match.group(0).replace(" ", "") if match else ""


def pc_reservation_detail(
    s: requests.Session,
    page_url: str,
    seq: str,
    timeout: int,
) -> dict[str, Any]:
    response = s.post(
        page_url,
        data={
            "pageIndex": "1",
            "mode": "view",
            "seq": seq,
            "rsvtFacilityCd": "",
            "areaCode": "",
            "searchCondition": "",
            "searchKeyword": "",
        },
        timeout=timeout,
    )
    response.raise_for_status()
    soup = BeautifulSoup(response.text, "html.parser")
    preview = soup.select_one(".preview") or soup.select_one("#content") or soup
    title = clean_text((preview.select_one(".review-tit em") or {}).get_text(" ", strip=True) if preview.select_one(".review-tit em") else "")
    pairs = pc_reservation_span_pairs(preview.select_one(".review-tit .address"))
    images = [
        urljoin(page_url, img.get("src"))
        for img in preview.select(".slick img, .preview_bx img")
        if clean_text(img.get("src")) and "/page/reservation/images/" not in clean_text(img.get("src"))
    ]
    description_parts: list[str] = []
    for heading in preview.select(".titLv, .titLv2"):
        section_text = clean_text(heading.get_text(" ", strip=True))
        if section_text and section_text not in description_parts:
            description_parts.append(section_text)
    table_text = clean_text(" ".join(table.get_text(" ", strip=True) for table in preview.select("table.skinTb")))
    if table_text:
        description_parts.append(table_text)
    caution = clean_text(" ".join(node.get_text(" ", strip=True) for node in preview.select(".caution")))
    if caution:
        description_parts.append(caution)
    return {
        "title": title,
        "pairs": pairs,
        "image_url": images[0] if images else "",
        "description": clean_text(" ".join(description_parts))[:4000],
        "fee": pc_reservation_first_fee_text(soup),
    }


def pc_reservation_card_rows(
    target: CrawlTarget,
    s: requests.Session,
    path: str,
    section_label: str,
    domain_category: str,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], int, bool]:
    page_url = f"{PC_RESERVATION_BASE}{path}"
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    pagination_detected = False
    seen_seq: set[str] = set()
    for page in range(1, max_pages + 1):
        response = s.post(
            page_url,
            data={
                "pageIndex": str(page),
                "mode": "list",
                "seq": "0",
                "rsvtFacilityCd": "",
                "areaCode": "",
                "searchCondition": "",
                "searchKeyword": "",
            },
            timeout=timeout,
        )
        response.raise_for_status()
        soup = BeautifulSoup(response.text, "html.parser")
        cards = soup.select(".public_wrap")
        if not cards:
            break
        page_new = 0
        for card in cards:
            link = card.select_one(".btn-content-view")
            seq = clean_text(link.get("data-seq") if link else "")
            title = clean_text((card.select_one(".public_txt em") or {}).get_text(" ", strip=True) if card.select_one(".public_txt em") else "")
            if not seq or not title or seq in seen_seq:
                continue
            seen_seq.add(seq)
            page_new += 1
            list_pairs = pc_reservation_span_pairs(card.select_one(".public_address"))
            list_image = clean_text((card.select_one(".public img") or {}).get("src") if card.select_one(".public img") else "")
            card_html = card.decode()
            available = "예약가능" in card_html or "reserveFlag = Y" in card_html
            detail = {}
            if detail_pages < detail_limit:
                try:
                    detail = pc_reservation_detail(s, page_url, seq, timeout)
                    detail_pages += 1
                except Exception as exc:
                    detail = {"raw_error": str(exc)}
            detail_pairs = detail.get("pairs") if isinstance(detail.get("pairs"), dict) else {}
            merged_pairs = {**list_pairs, **detail_pairs}
            title = clean_text(detail.get("title")) or title
            address = pc_reservation_address(merged_pairs.get("주소"))
            branch_code_seed = clean_text(f"{title}|{address}")
            branch_code = f"pc-{hashlib.sha1(branch_code_seed.encode('utf-8')).hexdigest()[:16]}"
            facility_type = clean_text(merged_pairs.get("시설유형"))
            related = clean_text(merged_pairs.get("관련종목"))
            schedule = clean_text(merged_pairs.get("운영시간"))
            phone = clean_text(merged_pairs.get("전화번호"))
            category = clean_text(" > ".join(part for part in [section_label, facility_type or related] if part))
            raw_url = f"{page_url}?mode=view&seq={seq}"
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, path, seq, title),
                    "title": title,
                    "branch": title,
                    "branch_code": branch_code,
                    "preserve_branch": True,
                    "category": category,
                    "collection_category": "공공시설예약",
                    "domain_category": domain_category,
                    "source_group": "arts_culture",
                    "operator_type": "지자체/공공기관",
                    "collection_type": "static_html",
                    "raw_url": raw_url,
                    "application_url": page_url,
                    "application_type": "FACILITY_RESERVATION",
                    "application_method_raw": "온라인예약" if available else "예약 문의",
                    "reservation_available": available,
                    "discovery_status": "pc_reservation_facility",
                    "status": "예약가능" if available else "예약문의",
                    "fee": clean_text(detail.get("fee")),
                    "period": "상시 운영",
                    "schedule_raw": schedule,
                    "target": "일반 이용자",
                    "venue_name": title,
                    "venue_address": address,
                    "address": address,
                    "room": title,
                    "phone": phone,
                    "description": clean_text(detail.get("description")),
                    "image_url": clean_text(detail.get("image_url")) or urljoin(page_url, list_image),
                    "raw_fields": {
                        "parser": "pc_reservation_facility",
                        "path": path,
                        "section": section_label,
                        "seq": seq,
                        "pairs": merged_pairs,
                    },
                }
            )
        pagination_detected = pagination_detected or page_new >= 9
        if page_new == 0:
            break
    return rows, detail_pages, pagination_detected


def collect_pc_reservation_facilities(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    pagination_detected = False
    pages_per_section = max(1, max_pages)
    detail_limit_remaining = detail_limit if detail_limit else 9999
    for path, section_label, domain_category in PC_RESERVATION_PATHS:
        section_rows, section_detail_pages, section_pagination = pc_reservation_card_rows(
            target,
            s,
            path,
            section_label,
            domain_category,
            timeout,
            pages_per_section,
            detail_limit_remaining,
        )
        rows.extend(section_rows)
        detail_pages += section_detail_pages
        detail_limit_remaining = max(0, detail_limit_remaining - section_detail_pages)
        pagination_detected = pagination_detected or section_pagination

    meta = {
        "pages": len(PC_RESERVATION_PATHS) * pages_per_section,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "pc_reservation_facility", meta


def nested_value_name(value: Any) -> str:
    if isinstance(value, dict):
        for key in ("name", "valueName", "nm", "title"):
            text = clean_text(value.get(key))
            if text:
                return text
        return ""
    return clean_text(value)


def cheongju_lctre_condition(url: str) -> tuple[str, dict[str, Any]]:
    parsed = urlparse(url)
    path = parsed.path.rstrip("/")
    if path == "/papp/P020101":
        url = f"{parsed.scheme}://{parsed.netloc}/papp/P020104"
        return url, {"lctreTy": "inner", "edcSe": "C0020001"}
    if path == "/papp/P020104":
        return url, {"lctreTy": "inner", "edcSe": "C0020001"}
    if path == "/papp/P020202":
        return url, {"lctreTy": "inner", "edcSe": "C0020004"}
    if path == "/ccu/capp/C1202":
        return url, {"lctreTy": "inner", "edcSe": "C0020012"}
    return url, {}


def cheongju_fee_text(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    try:
        amount = int(float(text))
    except ValueError:
        return text
    if amount <= 0:
        return "\ubb34\ub8cc"
    return f"{amount:,}\uc6d0"


def cheongju_period(item: dict[str, Any], start_key: str, end_key: str, start_time_key: str = "", end_time_key: str = "") -> str:
    start = clean_text(item.get(start_key))
    end = clean_text(item.get(end_key))
    if start_time_key and clean_text(item.get(start_time_key)):
        start = clean_text(f"{start} {item.get(start_time_key)}")
    if end_time_key and clean_text(item.get(end_time_key)):
        end = clean_text(f"{end} {item.get(end_time_key)}")
    if start and end:
        return f"{start} ~ {end}"
    if start or end:
        return start or end
    result = item.get("result") if isinstance(item.get("result"), dict) else {}
    date_text = clean_text(result.get("edcDeText"))
    dates = re.findall(r"(\d{4})[./-](\d{1,2})[./-](\d{1,2})", date_text)
    if len(dates) >= 2:
        first = f"{int(dates[0][0]):04d}-{int(dates[0][1]):02d}-{int(dates[0][2]):02d}"
        last = f"{int(dates[-1][0]):04d}-{int(dates[-1][1]):02d}-{int(dates[-1][2]):02d}"
        return f"{first} ~ {last}"
    if len(dates) == 1:
        return f"{int(dates[0][0]):04d}-{int(dates[0][1]):02d}-{int(dates[0][2]):02d}"
    return ""


def cheongju_instructors(item: dict[str, Any]) -> str:
    names: list[str] = []
    for instructor in item.get("instrctrs") or []:
        if not isinstance(instructor, dict):
            continue
        name = clean_text(instructor.get("instrctrNm")) or nested_value_name(instructor.get("instrctrCode"))
        if name and name not in names:
            names.append(name)
    for key in ("instrctr", "trgetInstrctr"):
        name = nested_value_name(item.get(key))
        if name and name not in names:
            names.append(name)
    return clean_text(", ".join(names))


def cheongju_schedule_text(item: dict[str, Any]) -> str:
    day = nested_value_name(item.get("edcDow")) or nested_value_name((item.get("result") or {}).get("edcDow"))
    day = {
        "Mon": "\uc6d4",
        "Tue": "\ud654",
        "Wed": "\uc218",
        "Thu": "\ubaa9",
        "Fri": "\uae08",
        "Sat": "\ud1a0",
        "Sun": "\uc77c",
    }.get(day, day)
    start = clean_text(item.get("beginTm"))
    end = clean_text(item.get("endTm"))
    if day and start and end:
        return f"{day} {start}~{end}"
    if start and end:
        return f"{start}~{end}"
    result = item.get("result") if isinstance(item.get("result"), dict) else {}
    result_schedule = bsdonggu_normalize_date(clean_text(result.get("edcDeText") or result.get("edcTmText") or result.get("edcDowText")))
    return result_schedule or day


def cheongju_branch_name(item: dict[str, Any], fallback: str) -> str:
    center = clean_text(item.get("cnterNm"))
    if center:
        return center
    result = item.get("result") if isinstance(item.get("result"), dict) else {}
    result_instt = clean_text(result.get("insttNm"))
    if result_instt:
        return result_instt
    institution = nested_value_name(item.get("edcInstt"))
    return institution or fallback


def cheongju_row_from_item(target: CrawlTarget, list_url: str, item: dict[str, Any]) -> dict[str, Any]:
    seq = clean_text(item.get("lctreSeq") or item.get("seq"))
    title = clean_text(item.get("lctreNm")) or nested_value_name(item.get("lctreSbject"))
    raw_url = f"{list_url.split('#', 1)[0]}#{seq}" if seq else list_url
    branch = cheongju_branch_name(item, target.branch)
    status = nested_value_name(item.get("lctreStep")) or nested_value_name((item.get("result") or {}).get("lctreSttus"))
    edc_name = nested_value_name(item.get("edcSe"))
    category = clean_text(" > ".join(part for part in [edc_name, nested_value_name(item.get("lctreCl")), nested_value_name(item.get("bsnsTy"))] if part))
    capacity = ""
    current = clean_text(item.get("applyCnt") or (item.get("result") or {}).get("apply"))
    total = clean_text(item.get("psncpa"))
    if current and total:
        capacity = f"{current}/{total}"
    elif total:
        capacity = total
    venue_address = clean_text((item.get("edcInstt") or {}).get("etc") if isinstance(item.get("edcInstt"), dict) else "")
    result = item.get("result") if isinstance(item.get("result"), dict) else {}
    venue_name = clean_text(item.get("lctrumCenter")) or nested_value_name(item.get("lctrum")) or clean_text(result.get("insttNm")) or nested_value_name(item.get("edcInstt"))
    description = html_to_text(item.get("referMatter"))
    period = cheongju_period(item, "beginDe", "endDe")
    schedule_raw = cheongju_schedule_text(item)
    target_text = nested_value_name(item.get("edcTrget")) or clean_text(item.get("trget"))
    if not description:
        description = clean_text(" | ".join(part for part in [title, category, branch, period, schedule_raw, target_text] if part))
    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, seq or raw_url, title, branch),
        "title": title,
        "branch": branch,
        "branch_code": clean_text(item.get("cnterNm") or nested_value_name(item.get("edcInstt")) or branch),
        "category": category,
        "raw_url": raw_url,
        "application_url": clean_text(item.get("outLctUrl")) or (raw_url if "\uc811\uc218" in status else ""),
        "status": status,
        "fee": cheongju_fee_text(item.get("amount")),
        "material_fee": extract_material_fee_amount(description),
        "period": period,
        "schedule_raw": schedule_raw,
        "target": target_text,
        "instructor": cheongju_instructors(item),
        "capacity": capacity,
        "apply_period": cheongju_period(item, "rceptBeginDe", "rceptEndDe", "rceptBeginTm", "rceptEndTm"),
        "venue_name": venue_name,
        "venue_address": venue_address,
        "description": description,
        "raw_fields": {"parser": "cheongju_lctre_api", "item": item},
    }


def collect_cheongju_lctre_request(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    list_url, condition = cheongju_lctre_condition(target.url)
    parsed = urlparse(list_url)
    root_url = f"{parsed.scheme}://{parsed.netloc}"
    headers = {
        "Referer": list_url,
        "Accept": "application/json, text/javascript, */*; q=0.01",
        "X-Requested-With": "XMLHttpRequest",
    }
    rows: list[dict[str, Any]] = []
    total_pages = 0
    total_elements = 0
    page_size = 20
    for page in range(1, max_pages + 1):
        params = dict(condition)
        params.update({"page": str(page), "size": str(page_size)})
        response = s.get(f"{root_url}/info/lctre/request/paging", params=params, headers=headers, timeout=timeout, verify=False)
        response.raise_for_status()
        payload = response.json()
        data_list = payload.get("dataList") or []
        paging = payload.get("paging") or {}
        total_pages = max(total_pages, int(paging.get("totalPages") or 0))
        total_elements = max(total_elements, int(paging.get("totalElements") or 0))
        for item in data_list:
            if isinstance(item, dict):
                row = cheongju_row_from_item(target, list_url, item)
                if row.get("title"):
                    rows.append(row)
        if not data_list or (total_pages and page >= total_pages):
            break

    detail_pages = 0
    enriched_rows: list[dict[str, Any]] = []
    for row in dedupe_rows(rows):
        seq = clean_text(row.get("raw_url")).split("#", 1)[-1] if "#" in clean_text(row.get("raw_url")) else ""
        if seq and detail_pages < detail_limit:
            try:
                detail_response = s.get(
                    f"{root_url}/info/lctre/request",
                    params={"lctreSeq": seq, "batchTy": "", "aditOrdr": ""},
                    headers=headers,
                    timeout=timeout,
                    verify=False,
                )
                detail_response.raise_for_status()
                detail_item = (detail_response.json() or {}).get("data") or {}
                if isinstance(detail_item, dict):
                    detail_row = cheongju_row_from_item(target, list_url, detail_item)
                    schedule_response = s.get(
                        f"{root_url}/info/schdul",
                        params={"trgetLctre": seq},
                        headers=headers,
                        timeout=timeout,
                        verify=False,
                    )
                    if schedule_response.ok:
                        schedule_payload = schedule_response.json() or {}
                        dates = [
                            clean_text(item.get("edcDe"))
                            for item in schedule_payload.get("dataList") or []
                            if isinstance(item, dict) and clean_text(item.get("edcDe"))
                        ]
                        if dates:
                            detail_row["schedule_dates"] = dates
                            detail_row["sessions"] = len(dates)
                    row = merge_course_rows(row, detail_row)
                    detail_pages += 1
            except Exception as exc:
                logger.debug("cheongju detail fetch failed %s: %s", seq, exc)
        enriched_rows.append(row)

    meta = {
        "pages": min(max_pages, total_pages or max_pages) if rows else 0,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": total_pages > 1,
        "recursion_depth": 0,
        "total_count": total_elements,
        "condition": condition,
    }
    return enriched_rows, "cheongju_lctre_api", meta


def fmcs_root_url(url: str) -> str:
    parsed = urlparse(url)
    prefix = parsed.path.split("/fmcs/", 1)[0].rstrip("/")
    root_path = f"{prefix}/" if prefix else "/"
    return f"{parsed.scheme}://{parsed.netloc}{root_path}"


def fmcs_http_method(s: requests.Session, root_url: str, referer: str, timeout: int) -> str:
    headers = {
        "Referer": referer,
        "Accept": "application/json, text/javascript, */*; q=0.01",
        "X-Requested-With": "XMLHttpRequest",
    }
    endpoint = urljoin(root_url, "rest/common/company")
    response = s.get(endpoint, params={"type": "L"}, headers=headers, timeout=timeout, verify=False)
    if response.status_code == 405:
        return "post"
    return "get"


def fmcs_request_json(
    s: requests.Session,
    root_url: str,
    endpoint: str,
    params: dict[str, Any],
    method: str,
    referer: str,
    timeout: int,
) -> Any:
    headers = {
        "Referer": referer,
        "Accept": "application/json, text/javascript, */*; q=0.01",
        "X-Requested-With": "XMLHttpRequest",
    }
    url = urljoin(root_url, endpoint)
    if method == "post":
        response = s.post(url, data=params, headers=headers, timeout=timeout, verify=False)
    else:
        response = s.get(url, params=params, headers=headers, timeout=timeout, verify=False)
    if response.status_code == 405 and method == "get":
        response = s.post(url, data=params, headers=headers, timeout=timeout, verify=False)
    response.raise_for_status()
    return response.json()


def fmcs_json_rows(data: Any) -> list[dict[str, Any]]:
    if isinstance(data, list):
        return [item for item in data if isinstance(item, dict)]
    if isinstance(data, dict):
        for key in ("data", "items", "list", "result", "rows"):
            rows = data.get(key)
            if isinstance(rows, list):
                return [item for item in rows if isinstance(item, dict)]
    return []


def fmcs_int(value: Any, default: int = 0) -> int:
    text = clean_text(value)
    if not text:
        return default
    try:
        return int(float(text.replace(",", "")))
    except ValueError:
        return default


def fmcs_category_context(category: dict[str, Any]) -> dict[str, str]:
    category_code = clean_text(category.get("category_code"))
    category_level = clean_text(category.get("category_level")) or "9"
    category_name = clean_text(category.get("category_name"))
    parent_name = clean_text(category.get("parent_category_name"))
    top_name = clean_text(category.get("top_category_name"))
    parts = [part for part in [top_name, category_name] if part]
    return {
        "category_cd": category_code,
        "category_level": category_level,
        "category_name": category_name,
        "parent_category_name": parent_name,
        "top_category_name": top_name,
        "category_path": clean_text(" > ".join(dict.fromkeys(parts))),
    }


def fmcs_category_contexts(
    s: requests.Session,
    root_url: str,
    comcd: str,
    method: str,
    referer: str,
    timeout: int,
) -> list[dict[str, str]]:
    contexts: list[dict[str, str]] = [
        {
            "category_cd": "",
            "category_level": "9",
            "category_name": "",
            "parent_category_name": "",
            "top_category_name": "",
            "category_path": "",
        }
    ]
    try:
        top_categories = fmcs_json_rows(
            fmcs_request_json(s, root_url, "rest/common/category", {"company_code": comcd}, method, referer, timeout)
        )
    except Exception as exc:
        logger.debug("fmcs category fetch failed company=%s: %s", comcd, exc)
        return contexts

    for category in top_categories:
        code = clean_text(category.get("category_code"))
        if not code:
            continue
        contexts.append(fmcs_category_context(category))
        if fmcs_int(category.get("low_category_count")) <= 0:
            continue
        try:
            children = fmcs_json_rows(
                fmcs_request_json(
                    s,
                    root_url,
                    "rest/common/category",
                    {"company_code": comcd, "code": code},
                    method,
                    referer,
                    timeout,
                )
            )
        except Exception as exc:
            logger.debug("fmcs child category fetch failed company=%s code=%s: %s", comcd, code, exc)
            continue
        for child in children:
            child_code = clean_text(child.get("category_code"))
            if child_code:
                contexts.append(fmcs_category_context(child))

    unique_contexts: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for context in contexts:
        key = (context.get("category_cd", ""), context.get("category_level", "9"))
        if key in seen:
            continue
        seen.add(key)
        unique_contexts.append(context)
    return unique_contexts


def fmcs_status_text(value: Any) -> str:
    status = clean_text(value).upper()
    return {
        "R": "\uc811\uc218\uc911",
        "%": "\uc811\uc218\uc911",
        "RW": "\ub300\uae30\uc811\uc218",
        "W": "\uc900\ube44\uc911",
        "E": "\ub9c8\uac10",
    }.get(status, clean_text(value))


