SEJONG_LIFELONG_API_BASE = f"{SEJONG_LIFELONG_BASE_URL}/api"
SEJONG_LIFELONG_MANAGE_CODE = "150018"
SEJONG_LIFELONG_ADDRESS = "?몄쥌?밸퀎?먯튂???곗슱3濡?124"
SEJONG_LIFELONG_BRANCH_CODE = "SEJONG_LIFELONG_EDU_MAIN"


def sejong_lifelong_clean_html(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    soup = BeautifulSoup(text.replace("&nbsp;", " "), "html.parser")
    return clean_text(soup.get_text(" ", strip=True))


def sejong_lifelong_date(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    match = re.search(r"(\d{4})[-.](\d{1,2})[-.](\d{1,2})", text)
    if not match:
        return ""
    return f"{int(match.group(1)):04d}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"


def sejong_lifelong_date_range(start_value: Any, end_value: Any) -> str:
    start = sejong_lifelong_date(start_value)
    end = sejong_lifelong_date(end_value)
    if start and end:
        return start if start == end else f"{start} ~ {end}"
    return start or end


def sejong_lifelong_time(value: Any) -> str:
    text = clean_text(value)
    match = re.search(r"\d{1,2}:\d{2}", text)
    return match.group(0) if match else ""


def sejong_lifelong_days(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    day_map = {
        "mon": "월",
        "monday": "월",
        "tue": "화",
        "tues": "화",
        "tuesday": "화",
        "wed": "수",
        "wednesday": "수",
        "thu": "목",
        "thur": "목",
        "thurs": "목",
        "thursday": "목",
        "fri": "금",
        "friday": "금",
        "sat": "토",
        "saturday": "토",
        "sun": "일",
        "sunday": "일",
    }
    values: list[str] = []
    for token in re.split(r"[,/| ]+", text):
        token = clean_text(token).lower()
        if not token:
            continue
        values.append(day_map.get(token, token))
    return clean_text("".join(dict.fromkeys(values)))


def sejong_lifelong_fee(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    try:
        amount = int(float(text.replace(",", "")))
    except ValueError:
        amount = extract_krw_amount(text)
    if amount <= 0:
        return "무료"
    return f"{amount:,}원"


