def sb_clean_label(value: Any) -> str:
    return clean_text(value).lstrip("※").strip()


def sb_normalize_range(value: Any) -> str:
    text = clean_text(value).replace("\r", " ").replace("\n", " ")
    text = re.sub(r"\s*~\s*", " ~ ", text)
    text = re.sub(r"\s+", " ", text).strip()
    text = re.sub(
        r"(\d{4})[.](\d{1,2})[.](\d{1,2})",
        lambda match: f"{match.group(1)}-{int(match.group(2)):02d}-{int(match.group(3)):02d}",
        text,
    )
    return text


def sb_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for table in soup.select("table"):
        for tr in table.select("tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
            cells = [cell for cell in cells if cell]
            if len(cells) == 2:
                pairs[sb_clean_label(cells[0])] = cells[1]
    return pairs


def sb_extract_address(soup: BeautifulSoup) -> tuple[str, str, str]:
    venue_name = clean_text(soup.select_one(".map_info").get_text(" ", strip=True)) if soup.select_one(".map_info") else ""
    address = clean_text(soup.select_one(".map_info_item.address").get_text(" ", strip=True)) if soup.select_one(".map_info_item.address") else ""
    phone = clean_text(soup.select_one(".map_info_item.tel").get_text(" ", strip=True)) if soup.select_one(".map_info_item.tel") else ""
    if address:
        return venue_name, address.replace("\xa0", " "), phone
    lines = [clean_text(line).replace("\xa0", " ") for line in soup.get_text("\n", strip=True).splitlines()]
    for index, line in enumerate(lines):
        if re.match(r"^(서울|경기|인천|부산|대구|광주|대전|울산|세종|강원|충북|충남|전북|전남|경북|경남|제주)", line):
            venue_name = lines[index - 1] if index > 0 else ""
            phone = lines[index + 1] if index + 1 < len(lines) and re.search(r"\d{2,4}-\d{3,4}-\d{4}", lines[index + 1]) else ""
            return venue_name, line, phone
    return "", "", ""


def sb_detail_fields(
    s: requests.Session,
    params: dict[str, str],
    title: str,
    timeout: int,
) -> tuple[dict[str, Any], str]:
    detail_url = f"{SB_DETAIL_URL}?{urlencode(params)}"
    try:
        soup = fetch_soup(s, detail_url, timeout=timeout)
    except Exception:
        return {}, detail_url
    pairs = sb_detail_pairs(soup)
    venue_name, venue_address, phone = sb_extract_address(soup)
    time_range = sb_normalize_range(pairs.get("교육시간"))
    weekday = clean_text(pairs.get("교육요일"))
    schedule_raw = clean_text(" ".join(part for part in [weekday, time_range] if part))
    fee = extract_krw_amount(pairs.get("이용요금")) or clean_text(pairs.get("이용요금"))
    branch = clean_text(pairs.get("운영기관")) or venue_name
    if venue_name and branch and venue_name not in branch:
        branch = f"{branch}[{venue_name}]"
    detail_text = soup.get_text("\n", strip=True)
    description = ""
    match = re.search(r"운영내용\s+(.*?)(?:장소안내|유의사항|환불정책|목록)", detail_text, re.DOTALL)
    if match:
        description = clean_text(match.group(1))
        if description == "운영내용":
            description = ""
    return (
        {
            "title": title,
            "branch": branch,
            "category": clean_text(pairs.get("교육과정")),
            "raw_url": detail_url,
            "application_url": detail_url,
            "period": sb_normalize_range(pairs.get("교육기간")),
            "apply_period": sb_normalize_range(pairs.get("접수기간")),
            "schedule_raw": schedule_raw,
            "target": clean_text(pairs.get("교육대상") or pairs.get("대상")),
            "room": clean_text(pairs.get("장소")) or venue_name,
            "venue_name": venue_name or clean_text(pairs.get("장소")),
            "venue_address": venue_address,
            "address": venue_address,
            "phone": phone or clean_text(pairs.get("문의전화")),
            "fee": fee,
            "material_fee": extract_material_fee_amount(pairs.get("재료비") or pairs.get("교재비")),
            "description": description,
            "capacity": parse_capacity_number(pairs.get("모집인원")),
            "waitlist_capacity": parse_capacity_number(pairs.get("대기 모집인원")),
            "application_method_raw": clean_text(pairs.get("접수방법")),
            "raw_fields": {"detail_pairs": pairs, "parser": "sb_unity_program_categories"},
        },
        detail_url,
    )


def sb_row_from_table(
    target: CrawlTarget,
    s: requests.Session,
    tr: Any,
    params: dict[str, str],
    category_label: str,
    timeout: int,
    detail_pages: int,
    detail_limit: int,
) -> tuple[dict[str, Any], int]:
    cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.select("td")]
    if len(cells) < 8:
        return {}, detail_pages
    title = cells[1]
    link = tr.find("a", href=True)
    match = re.search(r"fnView\([^,]+,\s*(\d+)\)", link.get("href") if link else "")
    program_no = match.group(1) if match else ""
    detail_params = dict(params)
    detail_params["progrmNo"] = program_no
    raw_url = f"{SB_DETAIL_URL}?{urlencode(detail_params)}" if program_no else target.url
    branch = cells[4] or target.branch
    current_capacity, total_capacity = parse_capacity_pair(cells[6])
    base: dict[str, Any] = {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
        "title": title,
        "branch": branch,
        "category": category_label,
        "raw_url": raw_url,
        "application_url": raw_url,
        "apply_period": sb_normalize_range(cells[2]),
        "period": sb_normalize_range(cells[3]),
        "schedule_raw": sb_normalize_range(cells[3]),
        "capacity": total_capacity,
        "capacity_current": current_capacity,
        "status": cells[7],
        "collection_category": "吏?먯껜",
        "domain_category": "怨듦났?덉빟",
        "operator_type": "吏?먯껜",
        "source_group": "public_reservation",
        "collection_type": "static_html",
                        "program_type": "\uAC15\uC88C",
        "raw_fields": {
            "list_cells": cells,
            "category_code": params.get("searchProgrmSe", ""),
            "parser": "sb_unity_program_categories",
        },
    }
    if program_no and detail_pages < detail_limit:
        detail, raw_url = sb_detail_fields(s, detail_params, title, timeout)
        if detail:
            base = merge_course_rows(base, detail)
            base["status"] = cells[7] or base.get("status", "")
            base["provider_course_id"] = stable_course_id(target.provider, base.get("raw_url") or raw_url, title, base.get("branch") or branch)
            detail_pages += 1
    return base, detail_pages


def collect_sb_unity_program_categories(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    pages_seen = 0
    category_pages: dict[str, int] = {}
    base_params = {
        "key": "6508",
        "insttTy": "URINTY01",
        "searchInsttNo": "84",
        "viewType": "list",
        "pageUnit": "20",
    }
    for category_code, category_label in SB_PROGRAM_CATEGORIES:
        page_index = 1
        while page_index <= max_pages:
            params = dict(base_params)
            params["pageIndex"] = str(page_index)
            if category_code:
                params["searchProgrmSe"] = category_code
            soup = fetch_soup(s, f"{SB_LIST_URL}?{urlencode(params)}", timeout=timeout)
            table_rows = soup.select("table.p-table tbody tr")
            if not table_rows:
                break
            pages_seen += 1
            category_pages[category_label] = category_pages.get(category_label, 0) + 1
            before = len(rows)
            for tr in table_rows:
                parsed, detail_pages = sb_row_from_table(
                    target,
                    s,
                    tr,
                    params,
                    category_label,
                    timeout,
                    detail_pages,
                    detail_limit,
                )
                if parsed:
                    rows.append(parsed)
            if len(rows) == before:
                break
            page_index += 1
            if len(rows) >= 1000:
                break
    rows = dedupe_rows(rows)
    return (
        rows,
        "sb_unity_program_categories",
        {
            "pages": pages_seen,
            "detail_pages": detail_pages,
            "pagination_detected": pages_seen > len(SB_PROGRAM_CATEGORIES),
            "category_pages": category_pages,
        },
    )


def collect_fmcs_lecture_api(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    root_url = fmcs_root_url(target.url)
    referer = target.url
    method = fmcs_http_method(s, root_url, referer, timeout)
    companies = fmcs_request_json(s, root_url, "rest/common/company", {"type": "L"}, method, referer, timeout)
    if isinstance(companies, dict):
        companies = []

    rows: list[dict[str, Any]] = []
    api_pages = 0
    api_requests = 0
    raw_row_count = 0
    category_combo_count = 0
    total_count = 0
    pagination_detected = False
    page_size = 100
    page_limit = max(1, max_pages)

    parsed_query = parse_qs(urlparse(target.url).query)
    target_center = clean_text((parsed_query.get("center") or [""])[0])
    use_global_all_query = target.provider == "MUNI_WWW_IJONGNO_CO_KR_F9ED1CA5"
    use_target_center_query = bool(target_center) and not use_global_all_query
    if use_global_all_query:
        category_combo_count += 1
        for search_type in ("%",):
            page = 1
            while page <= page_limit:
                params = {
                    "company_code": "",
                    "mem_no": "",
                    "search_type": search_type,
                    "category_cd": "",
                    "category_level": "9",
                    "class_nm": "",
                    "train_day": "",
                    "adult_gubn": "",
                    "lecturer_nm": "",
                    "page": str(page),
                    "page_size": str(page_size),
                }
                data = fmcs_request_json(s, root_url, "rest/lecture/list", params, method, referer, timeout)
                api_requests += 1
                list_rows = fmcs_json_rows(data)
                if not list_rows:
                    break
                api_pages += 1
                raw_row_count += len(list_rows)
                page_total_count = fmcs_int(list_rows[0].get("total_count"))
                total_count = max(total_count, page_total_count)
                pagination_detected = pagination_detected or page_total_count > page_size
                for item in list_rows:
                    row = fmcs_row_from_api_item(target, target.url, item, search_type)
                    if row.get("title"):
                        rows.append(row)
                if len(list_rows) < page_size:
                    break
                page += 1

    if not rows and use_target_center_query:
        category_combo_count += 1
        for search_type in ("%",):
            page = 1
            while page <= page_limit:
                params = {
                    "company_code": target_center,
                    "mem_no": "",
                    "search_type": search_type,
                    "category_cd": "",
                    "category_level": "9",
                    "class_nm": "",
                    "train_day": "",
                    "adult_gubn": "",
                    "lecturer_nm": "",
                    "page": str(page),
                    "page_size": str(page_size),
                }
                data = fmcs_request_json(s, root_url, "rest/lecture/list", params, method, referer, timeout)
                api_requests += 1
                list_rows = fmcs_json_rows(data)
                if not list_rows:
                    break
                api_pages += 1
                raw_row_count += len(list_rows)
                page_total_count = fmcs_int(list_rows[0].get("total_count"))
                total_count = max(total_count, page_total_count)
                pagination_detected = pagination_detected or page_total_count > page_size
                for item in list_rows:
                    row = fmcs_row_from_api_item(target, target.url, item, search_type)
                    if row.get("title"):
                        rows.append(row)
                if len(list_rows) < page_size:
                    break
                page += 1

    if not rows:
        if target_center:
            companies = [
                company
                for company in companies
                if clean_text(company.get("comcd")) == target_center
            ]
        for company in companies:
            if api_pages >= page_limit:
                break
            comcd = clean_text(company.get("comcd"))
            if not comcd:
                continue
            company_row_start = len(rows)
            category_contexts = fmcs_category_contexts(s, root_url, comcd, method, referer, timeout)
            category_combo_count += len(category_contexts)
            for category_context in category_contexts:
                if api_pages >= page_limit:
                    break
                for search_type in ("%",):
                    if api_pages >= page_limit:
                        break
                    page = 1
                    while page <= page_limit and api_pages < page_limit:
                        category_cd = clean_text(category_context.get("category_cd"))
                        category_level = clean_text(category_context.get("category_level")) or "9"
                        params = {
                            "company_code": comcd,
                            "mem_no": "",
                            "search_type": search_type,
                            "category_cd": category_cd,
                            "category_level": category_level,
                            "class_nm": "",
                            "train_day": "",
                            "adult_gubn": "",
                            "lecturer_nm": "",
                            "page": str(page),
                            "page_size": str(page_size),
                        }
                        data = fmcs_request_json(s, root_url, "rest/lecture/list", params, method, referer, timeout)
                        api_requests += 1
                        list_rows = fmcs_json_rows(data)
                        if not list_rows:
                            break
                        api_pages += 1
                        raw_row_count += len(list_rows)
                        page_total_count = fmcs_int(list_rows[0].get("total_count"))
                        total_count = max(total_count, page_total_count)
                        pagination_detected = pagination_detected or page_total_count > page_size
                        for item in list_rows:
                            row = fmcs_row_from_api_item(target, target.url, item, search_type, category_context)
                            if row.get("title"):
                                rows.append(row)
                        if len(list_rows) < page_size:
                            break
                        page += 1

            if len(rows) == company_row_start and api_pages < page_limit:
                for search_type in ("R", "E"):
                    if api_pages >= page_limit:
                        break
                    page = 1
                    while page <= page_limit and api_pages < page_limit:
                        params = {
                            "company_code": comcd,
                            "mem_no": "",
                            "search_type": search_type,
                            "category_cd": "",
                            "category_level": "9",
                            "class_nm": "",
                            "train_day": "",
                            "adult_gubn": "",
                            "lecturer_nm": "",
                            "page": str(page),
                            "page_size": str(page_size),
                        }
                        data = fmcs_request_json(s, root_url, "rest/lecture/list", params, method, referer, timeout)
                        api_requests += 1
                        list_rows = fmcs_json_rows(data)
                        if not list_rows:
                            break
                        api_pages += 1
                        raw_row_count += len(list_rows)
                        page_total_count = fmcs_int(list_rows[0].get("total_count"))
                        total_count = max(total_count, page_total_count)
                        pagination_detected = pagination_detected or page_total_count > page_size
                        for item in list_rows:
                            row = fmcs_row_from_api_item(target, target.url, item, search_type)
                            if row.get("title"):
                                rows.append(row)
                        if len(list_rows) < page_size:
                            break
                        page += 1

    detail_pages = 0
    enriched_rows: list[dict[str, Any]] = []
    for row in dedupe_rows(rows):
        if detail_pages < detail_limit and row.get("raw_url"):
            try:
                detail = fmcs_detail_fields(s, row["raw_url"], timeout)
                row = merge_course_rows(row, detail)
                detail_pages += 1
            except Exception as exc:
                logger.debug("fmcs detail fetch failed %s: %s", row.get("raw_url"), exc)
        enriched_rows.append(row)

    meta = {
        "pages": api_pages,
        "api_requests": api_requests,
        "raw_row_count": raw_row_count,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "company_count": len(companies),
        "category_combo_count": category_combo_count,
        "global_all_query": use_global_all_query and bool(rows),
        "target_center": target_center,
        "target_center_query": use_target_center_query and bool(rows),
        "total_count": total_count,
        "http_method": method,
    }
    return enriched_rows, "fmcs_lecture_api", meta


