def syf_read_url(center_code: str, comcd: str, class_cd: str, search_type: str = "R") -> str:
    query = urlencode(
        {
            "center": center_code,
            "action": "read",
            "comcd": comcd,
            "classcd": class_cd,
            "type": search_type,
        }
    )
    return f"{SYF_LECTURE_LIST_URL}?{query}"


def syf_apply_period_from_lines(lines: list[str]) -> str:
    for index, line in enumerate(lines):
        text = clean_text(line)
        if "수강신청 기간" not in text:
            continue
        match = re.search(r"(\d{4}[-.]\d{1,2}[-.]\d{1,2})\s*~\s*(\d{4}[-.]\d{1,2}[-.]\d{1,2})", text)
        if match:
            return normalize_mixed_date_range(f"{match.group(1)} ~ {match.group(2)}")
        if index + 1 < len(lines):
            next_line = clean_text(lines[index + 1])
            match = re.search(r"(\d{4}[-.]\d{1,2}[-.]\d{1,2})\s*~\s*(\d{4}[-.]\d{1,2}[-.]\d{1,2})", next_line)
            if match:
                return normalize_mixed_date_range(f"{match.group(1)} ~ {match.group(2)}")
    return ""


def syf_fee_table_fields(scope: BeautifulSoup) -> dict[str, str]:
    table = scope.select_one("table#fee_list")
    if not table:
        return {}
    headers = [clean_text(cell.get_text(" ", strip=True)) for cell in table.select("thead th")]
    row = table.select_one("tbody tr")
    if not row:
        return {}
    cells = [clean_text(cell.get_text(" ", strip=True)) for cell in row.find_all("td")]
    values = dict(zip(headers, cells))
    return {
        "fee": fmcs_fee_text(values.get("수강료")),
        "period": clean_text(values.get("수강기간")),
        "product_name": clean_text(values.get("상품명")),
    }


def syf_image_url(base_url: str, src: str | None) -> str:
    src = clean_text(src)
    if not src:
        return ""
    absolute = urldefrag(urljoin(base_url, src))[0]
    parsed = urlparse(absolute)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return ""
    if absolute.endswith("/upload/file/") or "/noimage/" in absolute:
        return ""
    return absolute


def syf_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    scope = soup.select_one(".proc_read") or soup
    pairs = pairs_from_tables(scope)
    lines = lines_from_soup(scope)
    fee_fields = syf_fee_table_fields(scope)
    intro = fmcs_detail_text(lines, "강좌 소개")
    content = fmcs_detail_text(lines, "강좌 내용")
    description = clean_text(" ".join(part for part in [intro, content] if part))
    image = scope.select_one(".top_area .picture img[src], .pic_box img[src]")
    image_url = syf_image_url(url, image.get("src") if image else "")
    center = clean_text(pairs.get("운영센터"))
    phone = ""
    if "/" in center:
        center, phone = [clean_text(part) for part in center.split("/", 1)]
    return {
        "title": clean_text(pairs.get("강좌명")),
        "branch": center,
        "period": fee_fields.get("period", ""),
        "schedule_raw": clean_text(pairs.get("요일/시간") or pairs.get("강좌시간")),
        "target": clean_text(pairs.get("교육대상") or pairs.get("대상")),
        "instructor": clean_text(pairs.get("강사명")),
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "capacity": clean_text(pairs.get("신청인원/정원")),
        "venue_name": clean_text(pairs.get("교육장소")),
        "room": clean_text(pairs.get("교육장소")),
        "fee": fee_fields.get("fee", ""),
        "description": description,
        "material_fee": extract_material_fee_amount(description),
        "material_note": clean_text(
            "\n".join(
                line
                for line in description.splitlines()
                if any(keyword in line for keyword in ("재료", "재료비", "준비물", "교재비"))
            )
        ),
        "apply_period": syf_apply_period_from_lines(lines),
        "phone": phone,
        "image_url": image_url,
        "raw_detail_pairs": pairs,
        "raw_detail_fee": fee_fields,
    }


def syf_row_from_api_item(target: CrawlTarget, item: dict[str, Any], search_type: str = "R") -> dict[str, Any]:
    title = clean_text(item.get("class_nm"))
    center_code = clean_text(item.get("comcd"))
    class_cd = clean_text(item.get("class_cd"))
    branch_info = SYF_BRANCH_INFO.get(center_code, {})
    branch = clean_text(item.get("comnm") or branch_info.get("name") or target.branch)
    raw_url = syf_read_url(center_code, center_code, class_cd, search_type)
    start_time = clean_text(item.get("train_stime"))
    end_time = clean_text(item.get("train_etime"))
    train_day = clean_text(item.get("train_day_nm"))
    schedule = clean_text(f"{train_day} {start_time}~{end_time}") if start_time and end_time else train_day
    reg_person = clean_text(item.get("reg_person"))
    capa = clean_text(item.get("capa"))
    capacity = f"{reg_person}/{capa}" if reg_person and capa else capa
    status_code = clean_text(item.get("status")).upper()
    target_text = clean_text(item.get("target_age_name")) or extract_target_text(title)
    category = clean_text(" > ".join(part for part in [clean_text(item.get("category1")), clean_text(item.get("category2"))] if part))
    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, f"{center_code}:{class_cd}", title, branch),
        "title": title,
        "branch": branch,
        "branch_code": center_code or branch,
        "address": clean_text(branch_info.get("address")),
        "venue_address": clean_text(branch_info.get("address")),
        "phone": clean_text(branch_info.get("phone")),
        "category": category,
        "collection_category": "공공예약",
        "domain_category": "청소년문화체육",
        "source_group": "public_reservation",
        "operator_type": "지자체/공공기관",
        "collection_type": "api",
        "raw_url": raw_url,
        "application_url": raw_url if status_code in {"R", "RW", "W"} else "",
        "status": fmcs_status_text(status_code),
        "fee": fmcs_fee_text(item.get("course_fee")),
        "period": "",
        "schedule_raw": schedule,
        "target": target_text,
        "instructor": clean_text(item.get("teacher_name")),
        "capacity": capacity,
        "capacity_current": reg_person,
        "capacity_total": capa,
        "application_method_raw": clean_text(item.get("apply_type") or item.get("receipt_type") or "온라인 접수"),
        "description": "",
        "preserve_branch": True,
        "raw_fields": {
            "parser": "syf_lecture_api",
            "search_type": search_type,
            "item": item,
        },
    }


def collect_syf_lecture_api(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    root_url = "https://yeyak.syf.or.kr/"
    referer = SYF_LECTURE_LIST_URL
    method = "post"
    try:
        s.get(referer, timeout=timeout)
    except Exception as exc:
        logger.debug("syf initial page fetch failed: %s", exc)
    companies = fmcs_json_rows(
        fmcs_request_json(s, root_url, "rest/common/company", {"type": "L"}, method, referer, timeout)
    )
    if not companies:
        companies = [{"comcd": code, "comnm": info["name"]} for code, info in SYF_BRANCH_INFO.items()]

    rows: list[dict[str, Any]] = []
    api_pages = 0
    api_requests = 0
    raw_row_count = 0
    total_count = 0
    pagination_detected = False
    company_counts: dict[str, int] = {}
    page_size = 100
    page_limit = max(1, max_pages)

    for company in companies:
        center_code = clean_text(company.get("comcd"))
        if not center_code:
            continue
        company_counts.setdefault(center_code, 0)
        page = 1
        while page <= page_limit:
            params = {
                "company_code": center_code,
                "mem_no": "",
                "search_type": "R",
                "category_cd": "",
                "category_level": "9",
                "class_nm": "",
                "train_day": "",
                "adult_gubn": "",
                "lecturer_nm": "",
                "page": str(page),
                "page_size": str(page_size),
            }
            data = fmcs_request_json(s, root_url, "rest/lecture/list", params, method, referer, timeout)
            api_requests += 1
            list_rows = fmcs_json_rows(data)
            if not list_rows:
                break
            api_pages += 1
            raw_row_count += len(list_rows)
            page_total_count = fmcs_int(list_rows[0].get("total_count"))
            total_count += page_total_count if page == 1 else 0
            pagination_detected = pagination_detected or page_total_count > page_size
            for item in list_rows:
                row = syf_row_from_api_item(target, item, "R")
                if row.get("title"):
                    rows.append(row)
                    company_counts[center_code] += 1
            if len(list_rows) < page_size:
                break
            page += 1

    detail_pages = 0
    enriched_rows: list[dict[str, Any]] = []
    for row in dedupe_rows(rows):
        if detail_pages < detail_limit and row.get("raw_url"):
            try:
                detail = syf_detail_fields(s, row["raw_url"], timeout)
                row = merge_course_rows(row, detail)
                detail_pages += 1
            except Exception as exc:
                logger.debug("syf detail fetch failed %s: %s", row.get("raw_url"), exc)
        enriched_rows.append(row)

    meta = {
        "pages": api_pages,
        "api_requests": api_requests,
        "raw_row_count": raw_row_count,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "company_count": len(companies),
        "companies_with_rows": sum(1 for count in company_counts.values() if count > 0),
        "company_counts": company_counts,
        "total_count": total_count,
    }
    return enriched_rows, "syf_lecture_api+detail", meta


